                                            this.$getLocaleByCurrency(projectCurrency))
                                        }}
                                    </h5>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div class="col-xl-6 mb-2">
                        <div class="border h-100">
                            <div class="row border-bottom m-0 p-2">
                                <div class="col-md-7 pt-2 px-2">
                                    <h2 class="font-18">{{ $t('EstimatedBudget') }}
                                        :{{ this.$n(totalbudget, 'currency', this.$getLocaleByCurrency(projectCurrency))
                                        }}
                                        <!-- ({{GlobalCurrency}}): {{convertDecimalValueInFormat(totalbudget)}} -->
                                    </h2>
                                </div>
                                <div class="col-md-5 text-md-right p-0" v-if="(GlobalBudget && totalbudget) > 0"> <a
                                        href="javascript:;" class="btn btn-success"
                                        v-on:click="openEditBudgetModal()"><i class="fa fa-edit pr-2"></i><span>{{
                                            $t('Edit') }} {{ $t('Budget') }}</span></a></div>
                            </div>
                            <div class="row mt-3">
                                <div class="col-12 text-center">
                                    <div v-if="BudgetListingData.length > 0">
                                        <PieChart type="pie" width="600" :options="PieChartData" :Checktype="type"
                                            :key="key" />
                                    </div>
                                    <div v-else>
                                        <span class="text-danger no-record">{{ $t('NoRecordfound') }}</span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div class="col-xl-6 mb-2">
                        <div class="border h-100">
                            <div class="row border-bottom m-0 p-2">
                                <!-- <div class="col-md-7">
                                    <h2 class="font-18">
                                     {{ $t('FinalCost') }} 
                                        :{{this.$n(totalexpenses,'currency',this.$getLocaleByCurrency(projectCurrency))  }}
                                    </h2>
                                </div> -->

                                <div class="col-sm-12 col-md-6 col-lg-6  col-xl-6 float-left pt-2 px-2">
                                    <h6 class="font-18 float-left mr-4  "> <span class="mb-0">{{ $t('Paid') }}
                                            :{{ this.$n(totalexpenses, 'currency',
                                                this.$getLocaleByCurrency(projectCurrency))
                                            }}
                                        </span></h6>

                                    <h6 class="font-18  float-left"> <span class="mb-0">{{ $t('Pending') }}
                                            :{{ this.$n(paidexpenses, 'currency',
                                                this.$getLocaleByCurrency(projectCurrency))
                                            }}
                                        </span></h6>
                                </div>
                                <div class="col-sm-12 col-md-6 col-lg-6  col-xl-6 float-left  text-md-right p-0">
                                    <a href="javascript:;" class="btn btn-success"
                                        v-on:click="openExpenseModal(0, false)"><i class="fa fa-plus pr-2"></i><span>{{
                                            $t('Add') }} {{ $t('Expenses') }}</span></a>
                                </div>


                            </div>
                            <div class="row mt-3">
                                <div class="col-12 text-center">
                                    <div v-if="ExpensePieChartData.length > 0">
                                        <PieChart type="pie" width="600" :options="ExpensePieChartData"
                                            :Checktype="type" :key="key" />
                                    </div>
                                    <div v-else>
                                        <span class="text-danger no-record">{{ $t('NoRecordfound') }}</span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <div class="accordion custom-accr" id="accordionExample">
                <div class="card"
                    v-for="(item, index) in searchMethodforBudgetList(BudgetListingData, searchCategoryText, 'category_name')"
                    :key="index">
                    <div class="card-header" v-bind:id="'headingOne' + item.category_id">
                        <a class="collapsed"
                            v-on:click="getExpenseListingForBudgetCategory(item.category_id, item.estimated_amount)"
                            v-bind:id="'nav-link-' + item.category_id" data-toggle="collapse"
                            v-bind:data-target="'#collapseOne' + item.category_id" aria-expanded="false"
                            aria-controls="collapseOne">
                            <em class="fa fa-angle-down rotate-icon" aria-hidden="true"></em>
                            <h6 class="font-18 mt-2 ml-2"> {{ item.category_name }}:
                                {{ $n(item.estimated_amount, 'currency', $getLocaleByCurrency(projectCurrency)) }}</h6>
                        </a>
                    </div>
                    <div v-bind:id="'collapseOne' + item.category_id" class="collapse"
                        v-bind:aria-labelledby="'headingOne' + item.category_id" data-parent="#accordionExample">
                        <div class="card-body">
                            <div class="row">
                                <div class="col-sm-12 col-md-4 mt-3 ">
                                    <h6 class="font-18"> {{ $t('EstimatedBudget') }}
                                        :{{ $n(estimatedBudget, 'currency', $getLocaleByCurrency(projectCurrency)) }}
                                    </h6>
                                </div>
                                <div class="col-sm-12 col-md-4 mt-3">
                                    <h6 class="font-18"> {{ $t('FinalCost') }}
                                        :{{ $n(totalExpense, 'currency', $getLocaleByCurrency(projectCurrency)) }}
                                    </h6>
                                </div>

                                <div class="col-sm-12 col-md-4 mt-1 text-right">
                                    <a href="javascript:;" class="form-btn btn btn-success mr-2"
                                        v-on:click="openExpenseModal(item.category_id, true)"><i
                                            class="fa fa-plus pr-2"></i><span>Add New</span></a>
                                </div>
                            </div>

                        </div>
                        <div class="listing mt-2 float-none">
                            <div class="row">
                                <div class="col-md-12">
                                    <div class="progress  mx-0" :title="countingPercForBudget(estimatedBudget, totalExpense)+ '%'">
                                        <div v-bind:class="{ 'progress-bar': true, 'progress-red': countingPercForBudget(estimatedBudget, totalExpense) == 101, 'progress-green': countingPercForBudget(estimatedBudget, totalExpense) <= 100 }"
                                            role="progressbar"
                                            v-bind:style="'width:' + countingPercForBudget(estimatedBudget, totalExpense) + '%'"
                                            aria-valuenow="25" aria-valuemin="0" aria-valuemax="100">
                                            <span class="progress-text text-white font-weight-medium"  aria-valuemin="0" aria-valuemax="100">{{countingPercForBudget(estimatedBudget, totalExpense) +'%'}}</span>
                                        </div>
                                    </div>
                                </div>





                            </div>
                            <div class="table-responsive mt-3">
                                <table class="table table-bordered dt-responsive nowrap mt-0">
                                    <thead class="thead-bg">
                                        <tr>
                                            <th>{{ $t('Expense') }}</th>
                                            <th>{{ $t('Expense') }} {{ $t('Type') }}</th>
                                            <th>{{ $t('User') }}</th>
                                            <th>{{ $t('Expense') }} {{ $t('Date') }}</th>
                                            <th>File</th>
                                            <th class="text-right">{{ $t('Expense') }} {{ $t('Amount') }}</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        <tr v-for="(item, index) in eventListForBudgetCategory" :key="index">
                                            <td> {{ item.expense_title }}</td>
                                            <td>{{ item.cost_type_id == '1' ? 'Direct(Project-Specific)' :
                                                'Indirect(SharedOverhead)' }}</td>
                                            <td> {{ item.USER }}</td>
                                            <td>
                                                {{ $options.filters.formatDate(item.expense_date) }}
                                            </td>
                                             <td>                                                     <span class="text-overflow-dynamic-container">
                                                     <div title="Preview" class="ls-preview-cell" @click="previewFile(item)">
                                                         <div class="ls-icon-wrap" :style="{ background: getFileBgColor(getFileExtension(item.EXPENSE_FILE_NAME || 'file')) }">
                                                             <i class="fa fa-lg" :class="getFileIconClass(getFileExtension(item.EXPENSE_FILE_NAME || 'file'))" :style="{ color: getFileIconColor(getFileExtension(item.attachment || 'file')) }"></i>
                                                         </div>
                                                     </div>
                                                 </span>
                                             </td>
                                            <td class="text-right">
                                                {{ $n(item.expense_amount, 'currency',
                                                    $getLocaleByCurrency(projectCurrency))
                                                }}
                                            </td>
                                        </tr>
                                        <tr
                                            v-if="eventListForBudgetCategory == null || eventListForBudgetCategory.length == 0">
                                            <td colspan="6" class="text-danger text-center no-record">{{
                                                $t('NoRecordfound') }}</td>
                                        </tr>
                                        <tr>
                                            <td class="font-weight-bold" colspan="4">{{ $t('Total') }}</td>
                                            <td class="font-weight-bold"></td>
                                            <td class="font-weight-bold text-right">
                                                {{ $n(totalExpense, 'currency', $getLocaleByCurrency(projectCurrency))
                                                }}
                                            </td>
                                        </tr>
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
        <manageBudgetVue v-show="showCategoryModal" :projectCurrency="projectCurrency" :projectBudget="GlobalBudget"
            :pandingBudget="totalbudget" @callBackFunction="getBudgetListing" @GetExpenseCategory="GetExpenseCategory">
        </manageBudgetVue>
        <modaleditbudget v-if="showEditBudgetModal" :projectCurrency="projectCurrency" :projectBudget="GlobalBudget"
            :pandingBudget="paidexpenses" @callBackFunction="getBudgetListing"></modaleditbudget>
         <modalexpense v-if="showExpenseModal" :CategoryId="CategoryId" :projectCurrency="projectCurrency"
             :projectBudget="GlobalBudget" :pandingBudget="paidexpenses" @CallBackFunction="CloseAddExpense"
             @getExpenseListingForPieChart="getExpenseListingForPieChart" @getBudgetListing="getBudgetListing">
         </modalexpense>

         <!-- Preview Modal -->
         <div v-if="isPreviewVisible" class="file-preview-modal" @click.self="closePreview">
             <div class="file-preview-dialog">
                 <div class="file-preview-header">
                     <h5 class="file-preview-title" :title="fileName">{{ fileName || $t('Preview') }}</h5>
                     <button type="button" class="file-preview-close" @click="closePreview" aria-label="Close">
                         <i class="fa fa-times"></i>
                     </button>
                 </div>

                 <div class="file-preview-body">
                     <img v-if="previewType === 'image'" :src="previewSrc" class="preview-image" :alt="fileName" />

                     <iframe v-else-if="previewType === 'pdf'" :src="previewSrc" class="preview-frame"></iframe>

                     <video v-else-if="previewType === 'video'" class="preview-video" controls autoplay>
                         <source :src="previewSrc" />
                     </video>

                     <iframe v-else-if="previewType === 'doc'" :src="googleDocsViewerSrc" class="preview-frame"></iframe>

                     <div v-else class="preview-unsupported">
                         <i class="fa fa-file-o fa-3x mb-2"></i>
                         <div class="mb-2">{{ $t('PreviewNotAvailable') || 'Preview not available for this file type.' }}</div>
                         <!-- <button class="btn btn-primary btn-sm" @click="DownloadFiles(fileContent)">
                             <i class="fa fa-download pr-1"></i>{{ $t('Download') }}
                         </button> -->
                     </div>
                 </div>
             </div>
         </div>

     </section>
</template>
<script>
import manageBudgetVue from '../../../../components/Modal/manageBudget.vue';
import modaleditbudget from '../../../../components/Modal/modaleditbudget.vue'
import DataService from '../../../../services/DataService';
import PieChart from '../../../../components/Modal/PieChart.vue';
import modalexpense from '../../../../components/Modal/modalexpense.vue';
export default {
    components: { manageBudgetVue, modaleditbudget, PieChart, modalexpense },
    props: {
        projectCurrency: {
            type: String,
        },
        checkPmUser: {
            type: Boolean,
            required: true
        },
        ProjectOwner: {
            type: Boolean
        }
    },
    data() {
        return {
            IsAddProject: false,
            isLoading: false,
            CategoryId: 0,
            showCategoryModal: false,
            GlobalCurrency: 0,
            GlobalBudget: 0,
            totalbudget: 0,
            totalexpenses: 0,
            paidexpenses: 0,
            projectId: 0,
            BudgetListingData: [],
            ExpenseCategory: [],
            CompanyId: null,
            UserId: null,
            searchCategoryText: '',
            eventListForBudgetCategory: [],
            showEditBudgetModal: false,
            estimatedBudget: 0,
            PieChartData: [],
            ExpensePieChartData: [],
            PType: '',
            type: '',
            isshowBugetExpenseCategory: false,
            showExpenseModal: false,
            UserType: null,
             totalExpenseAmount: 0,
             key: 0,
             CurrencyCode: 'PKR',
             IsType: 'Project',
             BlobUrl: '',
             ContainerName: '',
             /* preview */
             isPreviewVisible: false,
             previewSrc: '',
             previewType: '',
             fileContent: null,
             fileName: '',
             /* icon/color maps */
            iconMap: {
                // Images
                svg: 'fa-file-code', psd: 'fa-file-image', ps: 'fa-file-pdf', png: 'fa-file-image', jpg: 'fa-file-image', jpeg: 'fa-file-image', ico: 'fa-file-image', gif: 'fa-file-image', bmp: 'fa-file-image', ai: 'fa-file-image',
                // Audio
                wpl: 'fa-list-ul', wma: 'fa-file-audio-o', wav: 'fa-file-audio-o', ogg: 'fa-file-audio-o', mpa: 'fa-file-audio-o', mp3: 'fa-music', midi: 'fa-keyboard-o', mid: 'fa-keyboard-o', cda: 'fa-compact-disc', aif: 'fa-file-audio-o',
                // Documents
                doc: 'fa-file-word-o', docx: 'fa-file-word-o', odt: 'fa-file-text-o', rtf: 'fa-file-text-o', tex: 'fa-file-code-o', txt: 'fa-file-text-o', wpd: 'fa-file-text-o', pdf: 'fa-file-pdf-o',
                // Presentations
                odp: 'fa-file-powerpoint-o', ppt: 'fa-file-powerpoint-o', pptx: 'fa-file-powerpoint-o',
                // Videos
                mp4: 'fa-play-circle-o', mkv: 'fa-film', avi: 'fa-film', mov: 'fa-video-camera', wmv: 'fa-video-camera', flv: 'fa-file-video-o', mpeg: 'fa-file-video-o', mpg: 'fa-file-video-o', m4v: 'fa-file-video-o', '3gp': 'fa-mobile', '3g2': 'fa-mobile', h264: 'fa-cogs', rm: 'fa-file-video-o', swf: 'fa-flash', vob: 'fa-compact-disc',
                // Compressed
                z7: 'fa-file-archive-o', deb: 'fa-cube', rar: 'fa-file-archive-o', rpm: 'fa-cube', zip: 'fa-file-archive-o',
                // Spreadsheets
                csv: 'fa-file-text-o', ods: 'fa-file-excel-o', xls: 'fa-file-excel-o', xlsm: 'fa-file-excel-o', xlsx: 'fa-file-excel-o',
                // Code/Applications
                c: 'fa-file-code', class: 'fa-gears', java: 'fa-file-code', sh: 'fa-terminal'
            },
            colorMap: {
                // Images
                svg: '#059669', psd: '#059669', ps: '#059669', png: '#059669', jpg: '#059669', jpeg: '#059669', ico: '#059669', gif: '#059669', bmp: '#059669', ai: '#059669',
                // Audio
                wpl: '#f59e0b', wma: '#f59e0b', wav: '#f59e0b', ogg: '#f59e0b', mpa: '#f59e0b', mp3: '#f59e0b', midi: '#f59e0b', mid: '#f59e0b', cda: '#f59e0b', aif: '#f59e0b',
                // Documents
                doc: '#2b579a', docx: '#2b579a', odt: '#2b579a', rtf: '#2b579a', tex: '#2b579a', txt: '#374151', wpd: '#2b579a', pdf: '#dc2626',
                // Presentations
                odp: '#d24726', ppt: '#d24726', pptx: '#d24726',
                // Videos
                mp4: '#7c3aed', mkv: '#7c3aed', avi: '#7c3aed', mov: '#7c3aed', wmv: '#7c3aed', flv: '#7c3aed', mpeg: '#7c3aed', mpg: '#7c3aed', m4v: '#7c3aed', '3gp': '#7c3aed', '3g2': '#7c3aed', h264: '#7c3aed', rm: '#7c3aed', swf: '#7c3aed', vob: '#7c3aed',
                // Compressed
                z7: '#6b7280', deb: '#6b7280', rar: '#6b7280', rpm: '#6b7280', zip: '#6b7280',
                // Spreadsheets
                csv: '#217346', ods: '#217346', xls: '#217346', xlsm: '#217346', xlsx: '#217346',
                // Code/Applications
                c: '#059669', class: '#059669', java: '#059669', sh: '#059669'
            },
            bgColorMap: {
                // Images
                svg: '#e6f7f1', psd: '#e6f7f1', ps: '#e6f7f1', png: '#e6f7f1', jpg: '#e6f7f1', jpeg: '#e6f7f1', ico: '#e6f7f1', gif: '#e6f7f1', bmp: '#e6f7f1', ai: '#e6f7f1',
                // Audio
                wpl: '#fef3c7', wma: '#fef3c7', wav: '#fef3c7', ogg: '#fef3c7', mpa: '#fef3c7', mp3: '#fef3c7', midi: '#fef3c7', mid: '#fef3c7', cda: '#fef3c7', aif: '#fef3c7',
                // Documents
                doc: '#e8f0fb', docx: '#e8f0fb', odt: '#e8f0fb', rtf: '#e8f0fb', tex: '#e8f0fb', txt: '#eef0f1', wpd: '#e8f0fb', pdf: '#fde8e8',
                // Presentations
                odp: '#fdf0eb', ppt: '#fdf0eb', pptx: '#fdf0eb',
                // Videos
                mp4: '#ede8fb', mkv: '#ede8fb', avi: '#ede8fb', mov: '#ede8fb', wmv: '#ede8fb', flv: '#ede8fb', mpeg: '#ede8fb', mpg: '#ede8fb', m4v: '#ede8fb', '3gp': '#ede8fb', '3g2': '#ede8fb', h264: '#ede8fb', rm: '#ede8fb', swf: '#ede8fb', vob: '#ede8fb',
                // Compressed
                z7: '#f3f4f6', deb: '#f3f4f6', rar: '#f3f4f6', rpm: '#f3f4f6', zip: '#f3f4f6',
                // Spreadsheets
                csv: '#e6f4ec', ods: '#e6f4ec', xls: '#e6f4ec', xlsm: '#e6f4ec', xlsx: '#e6f4ec',
                // Code/Applications
                c: '#e6f7f1', class: '#e6f7f1', java: '#e6f7f1', sh: '#e6f7f1'
            }
        }
    },
    created: async function () {
        var vm = this;
        vm.CurrencyCode = vm.GetUserInfo.Currency.replace(/[()]/g, '');
        vm.projectId = parseInt(vm.$route.params.projectId);
        vm.CompanyId = vm.GetUserInfo.CompanyId;
        vm.UserId = vm.GetUserInfo.ID;
        vm.UserType = vm.GetUserInfo.UserType
        await vm.ProjectOverview();
        await vm.getBudgetListing();
        await vm.getExpenseListingForPieChart();

    },
    mounted() {
        this.calculateTotalExpense();
    },
    computed: {
        totalExpense() {
            return this.totalExpenseAmount;
        },
        googleDocsViewerSrc() {
            if (!this.previewSrc) return '';
            return `https://view.officeapps.live.com/op/embed.aspx?src=${encodeURIComponent(this.previewSrc)}`;
        }
    },
    methods: {
        getFileExtension(filename) {
            if (!filename) return '';
            const parts = filename.split('.');
            return parts.length > 1 ? parts.pop().toLowerCase() : '';
        },
        getFileIconClass(ext) {
            return this.iconMap[ext] || 'fa-file-o';
        },
        getFileIconColor(ext) {
            return this.colorMap[ext] || '#6b7280';
        },
        getFileBgColor(ext) {
            return this.bgColorMap[ext] || '#f3f4f6';
        },
        ProjectOverview: async function () {
            var vm = this;
            var params = `projectId=${this.projectId}`;
            await DataService.GetProjectDetails(params).then(function (response) {
                if (response.data != null > 0) {
                    var ProjectDetailData = response.data.result.PROJECTOVERVIEW[0];
                    vm.GlobalBudget = ProjectDetailData.estimated_cost;
                    vm.projectCurrency = ProjectDetailData.ISO_CODE;
                }
            });
        },
        openEditBudgetModal: async function () {
            var ths = this;
            var url = 'controller=Project&action=AddUpdateBudget'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || ths.checkPmUser || ths.ProjectOwner) {
                    if (ths.BudgetListingData != null && ths.BudgetListingData.length > 0) {
                        ths.showEditBudgetModal = true;
                    }
                    else {
                        ths.ShowAlert(ths.$t('Please Enter budget first!'), "warning", true, ths.$t("Alert"));
                    }
                }
                else {
                    ths.ShowAlert(ths.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        countingPercForBudget: function (budget, expense) {
            var percentage = (expense / budget) * 100;
            if (percentage > 100) {
                percentage = 101;
            }
            return percentage;
        },
        calculateTotalExpense: function () {
            var vm = this;
            if (vm.eventListForBudgetCategory.length > 0) {
                vm.totalExpenseAmount = vm.eventListForBudgetCategory.reduce((curr, prev) => {
                    return parseFloat(curr) + parseFloat(prev.expense_amount);
                }, 0);
            }
        },
        getExpenseListingForBudgetCategory: function (categoryId, amount) {
            var thisObj = this;
            thisObj.isLoading = true;
            if (categoryId == undefined || null) {
                categoryId = thisObj.categoryid;
            }
            thisObj.estimatedBudget = amount;
            thisObj.categoryid = categoryId;
            var url = `eventId=${thisObj.projectId}&companyId=${thisObj.CompanyId}&viewerId=${thisObj.UserId}&categoryId=${thisObj.categoryid}&subModuleCode=PROJECT_DETAIL&isAll=true`
            DataService.getExpenseListingForPieChart(url).then((response) => {
                if (response.data != null) {
                    if (response.data.data.length > 0) {
                        thisObj.eventListForBudgetCategory = response.data.data;
                        thisObj.calculateTotalExpense();
                    } else {
                        thisObj.eventListForBudgetCategory = [];
                    }
                } else {
                    thisObj.eventListForBudgetCategory = [];
                }
                thisObj.isLoading = false;
            });
        },
        async getExpenseListingForPieChart() {
            var thisObj = this;
            var url = `eventId=${thisObj.projectId}&companyId=${thisObj.CompanyId}&viewerId=${thisObj.UserId}&subModuleCode=PROJECT_DETAIL&isAll=true`
            await DataService.getExpenseListingForPieChart(url).then((response) => {
                if (response.data != null) {
                    if (response.data.data.length > 0) {
                        var ExpenseListForBudgetCategory = response.data.data;
                        $.each(ExpenseListForBudgetCategory, function (index, element) {
                            element.Cost_type_name = element.cost_type_id == '1' ? 'Direct(Project-Specific)' : 'Indirect(Shared Overhead)';
                        });
                        var arrAU = [];
                        var expense = 0;
                        $.each(ExpenseListForBudgetCategory, function (index, element) {
                            arrAU.push([element.Cost_type_name, element.expense_amount]);
                            expense = expense + element.expense_amount;
                        });
                        thisObj.totalexpenses = expense;
                        thisObj.paidexpenses = thisObj.totalbudget - expense;
                        thisObj.generateExpenseChart(arrAU);
                    } else {
                        ExpenseListForBudgetCategory = [];
                    }
                } else {
                    ExpenseListForBudgetCategory = [];
                }
                thisObj.isLoading = false;
            });
        },
        searchMethodforBudgetList: function (array, searchText, attribute) {
            if (!searchText.length) return array;
            return array.filter(function (element) {
                return element[attribute].toLowerCase().indexOf(searchText.toLowerCase()) > -1;
            });
        },
        async getBudgetListing() {
            var vm = this;
            var url = 'controller=Project&action=ProjectBudget'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    var url = `eventId=${vm.projectId}`;
                    vm.isLoading = true;
                    await DataService.getBudgetListing(url).then((response) => {
                        var arrAU = [];
                        if (response.data != null) {
                            if (typeof (response.data.data) != "undefined" && response.data.data.length > 0) {
                                vm.BudgetListingData = response.data.data
                                var sum = 0;
                                $.each(vm.BudgetListingData, function (index, element) {
                                    arrAU.push([element.category_name, element.estimated_amount]);
                                    sum = sum + element.estimated_amount;
                                });
                                vm.totalbudget = sum;
                                vm.paidexpenses = vm.totalbudget - vm.totalexpenses;
                                vm.generateBudgetChart(arrAU);
                            } else {
                                vm.totalbudget = 0;
                                vm.generateBudgetChart(arrAU);
                                vm.BudgetListingData = [];
                            }
                        } else {
                            vm.totalbudget = 0;
                            vm.BudgetListingData = [];
                            vm.generateBudgetChart(arrAU);
                        }
                        vm.isLoading = false;
                    })
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });

        },
        generateBudgetChart(arrAU) {
            this.type = 'Budget';
            this.PieChartData = [...arrAU];
            this.key++;
        },
        generateExpenseChart(arrAU) {
            this.type = 'Expense';
            this.ExpensePieChartData = [...arrAU];
            this.key++;
        },
        GetExpenseCategory() {
            var vm = this;
            var url = `id=&companyId=${vm.CompanyId}&userId=${vm.UserId}&moduleName=Expenses&type=EXPENSE_CATEGORY`;
            vm.isLoading = true;
            DataService.GetExpenseCategory(url).then((response) => {
                vm.ExpenseCategory = [];
                if (response.data != null) {
                    var json = response.data;
                    vm.isLoading = false;
                    if (json != null) {
                        vm.ExpenseCategory = json.DATA;
                    }
                }

            });
        },
        openCategoryModal: async function () {
            var vm = this;
            var url = 'controller=Project&action=AddUpdateBudget'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    vm.showCategoryModal = true;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        openExpenseModal: function (categoryid) {
            var vm = this;
            if (categoryid == 0) {
                vm.isshowBugetExpenseCategory = false;
            }
            else {
                vm.isshowBugetExpenseCategory = true;
            }
            this.CategoryId = categoryid;
            this.showExpenseModal = true;
        },
        CloseAddExpense() {
            this.showExpenseModal = false;
        },
         BackToList: function () {
             var ths = this;
             ths.$router.push({ name: 'ProjectList' });
         },
         GetBlobUrl() {
             var vm = this;
             DataService.GetBlobUrl().then(response => {
                 if (response.data.length > 0) {
                     vm.BlobUrl = response.data[0].CONFIG_DATA_VALUE + vm.ContainerName + '/Upload/UserProfileImage/';
                 } else {
                     vm.BlobUrl = 'https://talygenv.github.io/Vue-UI-Content/images/user_avtar.png';
                 }
             });
         },
         previewFile(item) {
             var vm = this;
             vm.fileContent = item;
             vm.fileName = item.EXPENSE_FILE_NAME || 'File';
             var ext = vm.getFileExtension(item.EXPENSE_FILE_NAME || 'file');
             var path = item.EXPENSE_FILE_PATH ; // assuming attachment is filename
             vm.previewSrc = path;
             if (['jpg', 'jpeg', 'png', 'gif', 'bmp'].includes(ext)) {
                 vm.previewType = 'image';
             } else if (ext === 'pdf') {
                 vm.previewType = 'pdf';
             } else if (['mp4', 'webm', 'ogg', 'mov', 'avi'].includes(ext)) {
                 vm.previewType = 'video';
             } else if (['doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx'].includes(ext)) {
                 vm.previewType = 'doc';
             } else {
                 vm.previewType = 'unsupported';
             }
             vm.isPreviewVisible = true;
         },
         closePreview() {
             this.isPreviewVisible = false;
             this.previewSrc = '';
             this.previewType = '';
             this.fileContent = null;
             this.fileName = '';
         },
         DownloadFiles(item) {
             // For unsupported files, open in new tab
             var path = this.BlobUrl + item.attachment;
             window.open(path, '_blank');
         }
    }
}
</script>
