<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title">{{ discountListData ==null ?  $t('Add') :$t('Edit') }}  {{ $t('DiscountPromotion') }}</h4>
                        <button type="button" class="close" v-on:click="Close">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>
                    <div class="modal-body">
                        <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema" ref="SaveDiscountForm"
                            :mandatorytext='MandatoryString' v-on:OnSubmit="onSubmit"></dynamic-form>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import DataService from '../../../../services/DataService';
export default {
    props:{discountListData:{type: Object || Array}},
    data() {
        return {
            isLoading: false,
            MandatoryString: 'Fields marked with an asterisk (*) are mandatory.',
            FormSchema: [
                {
                    layoutType: "double",
                    group_name: 'Discount & Promotion',
                    Data: [
                        {
                            astype: "TextField",
                            label: this.$t('DiscountCode'),
                            name: "DiscountCode",
                            value: "",
                            placeholder: this.$t('Enter Discount Code'),
                            validationRules: { "required": true },
                        },
                        {
                            astype: "RadioField",
                            label: this.$t('DiscountType'),
                            name: "disType",
                            value: "1",
                            config: {
                                options: [{ value: 1, name: 'Flat' }, { value: 2, name: 'Percentage' }],
                                onChange: this.GetChangeDiscountType,
                            },
                            placeholder: this.$t('Select Discount Type'),
                            validationRules: { "required": true },
                        },
                        {
                            astype: "TextField",
                            label: this.$t('Value') + ('(Amount)'),
                            name: "Value",
                            value: "",
                            config: {
                            },
                            placeholder: this.$t('Select Discount Type'),
                            validationRules: { "required": true },
                        },
                        {
                            astype: "SelectField",
                            label: this.$t('Usages'),
                            name: "Usages",
                            value: "1",
                            placeholder: "",
                            validationRules: {
                                required: false,
                            },
                            config: {
                                options: [{ name: 'Unlimited', value: 1 }, { name: 'Limited to', value: 2 }],
                                onChange: this.GetChangeUsagesType,
                            },
                            disabled: false,
                        },
                        {
                            astype: "SelectField",
                            label: this.$t('Starts'),
                            name: "Starts",
                            value: "1",
                            placeholder: "",
                            visibility: false,
                            validationRules: {
                                required: false,
                            },
                            config: {
                                options: [{ name: 'Now', value: 1 }, { name: 'On Specific Date', value: 2 }],
                                onChange: this.GetChangeStartType,
                            },
                            disabled: false,
                        },
                        {
                            astype: "SelectField",
                            label: this.$t('Ends'),
                            name: "Ends",
                            value: "1",
                            placeholder: "",
                            visibility: false,
                            validationRules: {
                                required: false,
                            },
                            config: {
                                options: [{ name: 'When Sales End', value: 2 }, { name: 'On Specific Date', value: 1 }],
                                onChange: this.GetChangeEndType,
                            },
                            disabled: false,
                        },
                        {
                            astype: "DateField",
                            label: this.$t("StartDateTime"),
                            disabled: false,
                            name: "StartDate",
                            value: new Date(),
                            visibility: false,
                            placeholder: this.$t("StartDateTime"),
                            validationRules: {
                                required: true,
                            },
                            config: {
                                mode: "date", format: "M/D/YYYY",
                                minDate: '', maxDate: '',
                                //onChange:this.checkEndMinDate
                            },
                        },
                        {
                            astype: "DateField",
                            label: this.$t("EndDateTime"),
                            disabled: false,
                            name: "StartDate",
                            value: new Date(),
                            placeholder: this.$t("EndDateTime"),
                            validationRules: {
                                required: true,
                            },
                            config: {
                                mode: "date", format: "M/D/YYYY",
                                minDate: '', maxDate: '',
                                //onChange:this.checkEndMinDate
                            },
                        },
                        {
                            astype: "RadioField",
                            label: this.$t('Discount Apply To'),
                            name: "DiscountApplyTo",
                            value: "1",
                            config: {
                                options: [{ value: 1, name: 'ALL Activity' }, { value: 2, name: 'Specific Activity' }, { value: 3, name: 'Specific Ticket' }],
                                // { value: 3, name: 'Specific Ticket' }
                                onChange: this.GetChangeDiscountApplyToType,
                            },
                            placeholder: this.$t('Select Discount Apply To'),
                            validationRules: { "required": false },
                        },
                        {
                            astype: "SelectField",
                            label: this.$t('Event'),
                            name: "Event",
                            value: "",
                            placeholder: "",
                            visibility: false,
                            validationRules: {
                                required: false,
                            },
                            config: {
                                options: [],
                            },
                            disabled: false,
                        },
                        {
                            astype: "SelectField",
                            label: this.$t('TicketType'),
                            name: "TicketType",
                            value: "",
                            placeholder: "",
                            visibility: false,
                            validationRules: {
                                required: true,
                            },
                            config: {
                                options: [],
                            },
                            disabled: false,
                        },
                        {
                            astype: "SelectField",
                            label: this.$t('Ticket'),
                            name: "Ticket",
                            value: "",
                            visibility: false,
                            placeholder: "",
                            validationRules: {
                                required: false,
                            },
                            config: {
                                options: [],
                            },
                            disabled: false,
                        }
                    ]
                }
            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                    isVisible: true
                },
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.Close,
                },
            ],
            CompanyId: 0,
            projectId: 0,
            userId: 0,
            discountId:0,

        }
    },
    created: async function () {
        var ths = this;
        this.CompanyId = this.GetUserInfo.CompanyId;
        this.projectId = parseInt(this.$route.params.projectId);
        this.userId = this.GetUserInfo.ID;
        if(this.discountListData) this.EditDetail(this.discountListData);
        ths.GetmultidayactivityData();
        ths.GetTicketTypeData();
    },
    methods: {
        EditDetail(data){
            
            var vm=this;
            vm.discountId=data.discount_id;
            vm.FormSchema[0].Data[0].value=data.discount_code;
            vm.FormSchema[0].Data[1].value=data.discount_type;
            data.discount_type ==1 ? vm.FormSchema[0].Data[2].label = "Value" + '(Amount)' : vm.FormSchema[0].Data[2].label = "Value" + '(Percentage)';
            vm.FormSchema[0].Data[2].value=data.discount_currency;
            vm.FormSchema[0].Data[3].value=data.discount_usage_type;
            if(data.discount_usage_type =='1')
            {
                vm.FormSchema[0].Data[4].visibility = false;
                vm.FormSchema[0].Data[5].visibility = false;
            }
            else {
                vm.FormSchema[0].Data[4].visibility = true;
                vm.FormSchema[0].Data[5].visibility = true;
            }
            vm.FormSchema[0].Data[4].value =data.discount_start_type;
            if (vm.FormSchema[0].Data[4].value == '2') {
                vm.FormSchema[0].Data[6].visibility = true;
            } else {
                vm.FormSchema[0].Data[6].visibility = false;
            }
            vm.FormSchema[0].Data[5].value=data.discount_end_type;
            if (vm.FormSchema[0].Data[5].value =='2') {
                vm.FormSchema[0].Data[7].visibility = true;
            } else {
                vm.FormSchema[0].Data[7].visibility = false;
            }
            vm.FormSchema[0].Data[6].value=data.discount_start_date;
            vm.FormSchema[0].Data[7].value=data.discount_end_date;
            vm.FormSchema[0].Data[8].value=data.discount_applied_type;
            if (vm.FormSchema[0].Data[8].value == '2') {
                vm.FormSchema[0].Data[9].visibility = true;
                vm.FormSchema[0].Data[9].value=data.discount_specific_ticket_type;
                vm.FormSchema[0].Data[10].visibility = false;
                vm.FormSchema[0].Data[11].visibility = false;
            } else if (vm.FormSchema[0].Data[8].value == '3') {
                vm.FormSchema[0].Data[10].visibility = false;
                vm.FormSchema[0].Data[11].visibility = true;
                vm.FormSchema[0].Data[11].value=data.discount_specific_ticket;
                vm.FormSchema[0].Data[9].visibility = false;
            }
            else {
                vm.FormSchema[0].Data[10].visibility = false;
                vm.FormSchema[0].Data[11].visibility = false;
                vm.FormSchema[0].Data[9].visibility = false;
            }

        },
        GetChangeDiscountApplyToType() {
            var vm = this;
            var Choosevalue = vm.FormSchema[0].Data[8].value;
            if (Choosevalue == '2') {
                vm.FormSchema[0].Data[9].visibility = true;
                vm.FormSchema[0].Data[10].visibility = false;
                vm.FormSchema[0].Data[11].visibility = false;
            } else if (Choosevalue == '3') {
                vm.FormSchema[0].Data[10].visibility = false;
                vm.FormSchema[0].Data[11].visibility = true;
                vm.FormSchema[0].Data[9].visibility = false;
            }
            else {
                vm.FormSchema[0].Data[10].visibility = false;
                vm.FormSchema[0].Data[11].visibility = false;
                vm.FormSchema[0].Data[9].visibility = false;
            }
        },
        GetChangeEndType() {
            var vm = this;
            var Choosevalue = vm.FormSchema[0].Data[5].value;
            if (Choosevalue == '2') {
                vm.FormSchema[0].Data[7].visibility = true;
            } else {
                vm.FormSchema[0].Data[7].visibility = false;
            }
        },
        GetChangeStartType() {
            var vm = this;
            var Choosevalue = vm.FormSchema[0].Data[4].value;
            if (Choosevalue == '2') {
                vm.FormSchema[0].Data[6].visibility = true;
            } else {
                vm.FormSchema[0].Data[6].visibility = false;
            }
        },
        GetChangeUsagesType() {
            var vm = this;
            var Choosevalue = vm.FormSchema[0].Data[3].value;
            if (Choosevalue == '1') {
                vm.FormSchema[0].Data[4].visibility = false;
                vm.FormSchema[0].Data[5].visibility = false;
            } else {
                vm.FormSchema[0].Data[4].visibility = true;
                vm.FormSchema[0].Data[5].visibility = true;
            }
        },
        GetChangeDiscountType() {
            var vm = this;
            var Choosevalue = vm.FormSchema[0].Data[1].value;
            if (Choosevalue == '1') {
                vm.FormSchema[0].Data[2].label = "Value" + '(Amount)';
            } else {
                vm.FormSchema[0].Data[2].label = "Value" + '(Percentage)';
            }
        },
        GetTicketTypeData() {
            const url = `id=&moduleName=EM_EXPENSE&type=TICKET_TYPES&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status === 200 && response.data?.DATA && response.data.DATA.length > 0) {
                    this.FormSchema[0].Data[10].config.options = [];
                    response.data.DATA.forEach(item => {
                        const Obj = {
                            name: item.name,
                            value: item.value
                        };
                        this.FormSchema[0].Data[10].config.options.push(Obj);
                    });
                    if (this.$refs.SaveDiscountForm) {
                        this.$refs.SaveDiscountForm.UpdateKeyValue();
                    }
                }
            }).catch(error => {
                console.error("Error fetching ticket types:", error);
            });
        },
        GetmultidayactivityData() {
            var url = `id=&moduleName=EM_EXPENSE&type=MULTIDAY_ACTIVITY&search=&refId=${this.projectId}`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            this.PriorityData = response.data.DATA;
                            var Pdata = this.PriorityData.filter(item => item.name === 'Low');
                            if (Pdata.length > 0) {
                                this.IsPriority = Pdata[0].value;
                            }
                        }
                    }
                }
            })
        },
        onSubmit: async function () {
            var ths = this;
            const isValid = await this.$refs.SaveDiscountForm.validateForm.validate();
            if (isValid) {
                ths.isLoading = true;
                var obj = {
                    userId: ths.GetUserInfo.ID,
                    companyId: ths.GetUserInfo.CompanyId,
                    eventid: ths.projectId,
                    DiscountCode: ths.FormSchema[0].Data[0].value,
                    DiscountType: ths.FormSchema[0].Data[1].value,
                    DiscountValue: ths.FormSchema[0].Data[2].value,
                    Usages: ths.FormSchema[0].Data[3].value,
                    Starts: ths.FormSchema[0].Data[4].value,
                    Ends: ths.FormSchema[0].Data[5].value,
                    StartDateTime: ths.FormSchema[0].Data[6].value,
                    EndDateTime: ths.FormSchema[0].Data[7].value,
                    DiscountAppliedType: ths.FormSchema[0].Data[8].value,
                    ticketName: ths.FormSchema[0].Data[11].value,
                    ticketType: ths.FormSchema[0].Data[10].value,
                    EventType: ths.FormSchema[0].Data[9].value,
                    ActionType:ths.discount_id ==0 ? 'Add' : 'Update',
                    DiscountId: ths.discount_id
                };                
                DataService.SaveDiscountPromotion(JSON.stringify(obj)).then((response) => {
                    ths.isLoading = false;
                    if (response.data.result!='') {
                        if (response.data.code == '1') {
                            ths.ShowAlert(ths.$t("AddedSuccess",[ths.$t("Discount")]),"success",true,ths.$t("Alert"));
                            ths.$emit('CloseDiscountPromotion');
                        }
                        else if (response.data.code == -2) {
                            ths.ShowAlert(ths.$t("UpdatedSuccess",[ths.$t("Discount")]),"success",true,ths.$t("Alert"));
                            ths.$emit('CloseDiscountPromotion');
                         }
                        else{
                            ths.ShowAlert(ths.$t('UnknownErrorOccur'), "failure", true, ths.$t("Alert"));
                        }
                    }
                });
            }

        },
        Close: function () {
            this.$parent.IsDiscount=false;
        }
    }
}
</script>