<template>
  <section class="project-construction-overview">
    <div class="projectoverviewbase">
    <CommonDashboard
      ref="commonDashboard"
      :project-id="projectId"
      :check-pm-user="checkPmUser"
      :new-tab-name="NewTabName"
      :ProjectOwner="ProjectOwner"
      :tabs-array="TabsArray"
      :Template_Name="Template_Name"
      @AddView="$emit('AddView', $event)"
    />
    <div class="card col-md-12 p-0 mb-3 cn-top-card">
      <div class="card-body col-12 pt-3 pb-4 px-3 common-dashboard-shell">
        <!-- <div class="cn-intel-head d-flex flex-wrap align-items-center justify-content-between gap-3 mb-4">
          <div class="cn-intel-brand d-flex flex-wrap align-items-center">
            <em class="fa fa-star cn-intel-star" aria-hidden="true"></em>
            <span class="cn-intel-title">Template Intelligence</span>
            <span class="cn-template-badge">{{ templateTag }}</span>
          </div>
          <small class="cn-intel-note text-muted mb-0">Widgets automatically adapt to your project template.</small>
        </div> -->

        <!-- <div class="cn-kpi-row">
          <div v-for="(k, idx) in kpiCards" :key="'kpi-' + idx" class="cn-kpi-col">
            <div class="cn-kpi-card" :class="'cn-kpi-card--' + k.tint">
              <div class="cn-kpi-value">{{ k.value }}</div>
              <div class="cn-kpi-label">{{ k.label }}</div>
            </div>
          </div>
        </div> -->

        <div class="row mx-0 mcc-chart-row align-items-stretch">
          <div class="col-lg-8 mb-3 px-2 section_pp d-flex">
            <div class="section h-100 w-100 mcc-chart-section">
              <div class="section-header reddy cd-panel-head mcc-chart-panel-head">
                <span class="cd-panel-title mcc-chart-title">
                  <!-- <span class="cn-title-emoji" aria-hidden="true">&#127959;&#65039;</span> -->
                  <em class="fa fa-spinner"></em>
                  Phase Progress
                </span>
              </div>
              <div class="section-body border py-2 mcc-chart-body">
                <VueApexCharts
                  v-if="hasPhaseChart"
                  type="bar"
                  height="340"
                  :options="phaseChartOptions"
                  :series="phaseChartSeries"
                  :key="'cn-ph-' + chartKey"
                />
                <div v-else class="mcc-no-chart">{{ $t('NoRecordfound') }}</div>
              </div>
            </div>
          </div>
          <div class="col-lg-4 mb-3 px-2 section_pp d-flex">
            <div class="section h-100 w-100 mcc-chart-section">
              <div class="section-header reddy cd-panel-head mcc-chart-panel-head">
                <span class="cd-panel-title mcc-chart-title">
                  <!-- <span class="cn-title-emoji" aria-hidden="true">&#128176;</span> -->
                  <em class="fa fa-dollar"></em>
                  Budget vs Actual
                </span>
              </div>
              <div class="section-body border py-2 mcc-chart-body">
                <VueApexCharts
                  v-if="hasBudgetCompareChart"
                  type="bar"
                  height="340"
                  :options="budgetCompareOptions"
                  :series="budgetCompareSeries"
                  :key="'cn-bc-' + chartKey"
                />
                <div v-else class="mcc-no-chart">{{ $t('NoRecordfound') }}</div>
              </div>
            </div>
          </div>
        </div>

        <div class="row mx-0">
          <div class="col-12 px-2 section_pp">
            <div class="section mcc-overdue-section">
              <div class="section-header reddy cd-panel-head mcc-od-head">
                <span class="cd-panel-title mcc-od-title-wrap">
                  <em class="fa fa-search mcc-od-icon" aria-hidden="true"></em>
                  <span class="mcc-od-title-main">Inspection schedule</span>
                </span>
                <small class="cd-panel-actions">
                  <a href="javascript:;" class="mcc-view-all-link font-13" @click="openDashboardAddView">
                    <em class="fa fa-eye mr-1"></em>{{ $t('View All') }}
                  </a>
                </small>
              </div>
              <div class="section-body border p-0">
                <div class="table-responsive mcc-od-wrap">
                  <table class="table mb-0 mcc-od-table">
                    <thead>
                      <tr>
                        <th>Inspection type</th>
                        <th>Phase</th>
                        <th>Scheduled date</th>
                        <th>Inspector</th>
                        <th>Status</th>
                        <th>Pirority</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr v-for="(row, idx) in inspectionRows" :key="'insp-' + idx">
                        <td class="mcc-od-title" :title="row.inspectionType">{{ truncate(row.inspectionType, 42) }}</td>
                        <td>{{ row.phase || '—' }}</td>
                        <td>{{ formatCellDate(row.scheduledDate) }}</td>
                        <td>{{ row.inspector || '—' }}</td>
                        <td>
                          <span class="mcc-stage-pill text-white" :style="{ backgroundColor: row.status_bg_color }">{{ row.status || '—' }}</span>
                        </td>
                        <td>
                          <span class="mcc-stage-pill text-white" :style="{ backgroundColor: row.notes_color }">{{  row.notes != null && row.notes !== '' ? row.notes : '—' }}</span>
                        </td>
                      </tr>
                      <tr v-if="!inspectionRows.length">
                        <td colspan="6" class="text-center text-danger py-4">{{ $t('NoRecordfound') }}</td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    <CriticalandBlockerDetail v-if="isCriticalandBlockerDetail" :Type="Template_Name"  :HeaderText="'Inspection schedule'"/>
    </div>
  </section>
</template>

<script>
import CommonDashboard from '../CommonDashboard.vue';
import VueApexCharts from 'vue-apexcharts';
import DataService from '../../../../../../services/DataService';
import CriticalandBlockerDetail from '../../../../../../components/Modal/CriticalandBlockerDetail.vue';
function n(v, fallback = 0) {
  const x = Number(v);
  return Number.isFinite(x) ? x : fallback;
}

/** Optional API: CONSTRUCTION_DASHBOARD = { kpis, phase_progress[], budget_vs_actual{}, inspections[] } */

const DEFAULT_PHASES = [];

const PHASE_COLORS = ['#34a853', '#34a853', '#f9ab00', '#1a73e8', '#dadce0', '#dadce0'];

const DEFAULT_BUDGET_COMPARE = {};

const DEFAULT_INSPECTIONS = [];

export default {
  name: 'ConstructionManagmentPlan',
  components: { CommonDashboard, VueApexCharts,CriticalandBlockerDetail },
  props: {
    projectId: { type: Number, required: true },
    checkPmUser: { type: Boolean, required: true },
    NewTabName: { type: String, required: true },
    TabsArray: { type: Array, default: () => [] },
    Template_Name: { type: String, required: true },
    ProjectOwner:{type: Boolean, required: true},
  },
  data() {
    return {
      isCriticalandBlockerDetail:false,
      chartKey: 0,
      kpiCards: [],
      hasPhaseChart: false,
      phaseChartSeries: [],
      phaseChartOptions: {
        chart: { type: 'bar', toolbar: { show: false }, fontFamily: 'inherit' },
        plotOptions: {
          bar: {
            horizontal: true,
            barHeight: '72%',
            borderRadius: 4,
            distributed: true,
            dataLabels: { position: 'center' },
          },
        },
        dataLabels: {
          enabled: true,
          formatter: (val) => (n(val, 0) >= 100 ? 'Complete' : `${n(val, 0)}%`),
          style: { fontSize: '11px', fontWeight: 600, colors: ['#fff', '#fff', '#202124', '#fff', '#5f6368', '#5f6368'] },
          dropShadow: { enabled: false },
        },
        colors: [...PHASE_COLORS],
        xaxis: { max: 100, tickAmount: 5, labels: { style: { fontSize: '11px' } } },
        yaxis: { labels: { style: { fontSize: '11px' } } },
        grid: { strokeDashArray: 4, borderColor: '#e8eaed' },
        legend: { show: false },
        tooltip: { y: { formatter: (val) => (n(val, 0) >= 100 ? '100% (Complete)' : `${val}%`) } },
      },
      hasBudgetCompareChart: false,
      budgetCompareSeries: [],
      budgetCompareOptions: {
        chart: { type: 'bar', toolbar: { show: false }, fontFamily: 'inherit' },
        plotOptions: { bar: { borderRadius: 4, columnWidth: '58%' } },
        colors: ['#aecbfa', '#1967d2'],
        dataLabels: { enabled: false },
        stroke: { show: true, width: 0 },
        xaxis: { categories: [], labels: { style: { fontSize: '11px' } } },
        yaxis: {
          max: 450,
          tickAmount: 5,
          labels: {
            style: { fontSize: '11px' },
            formatter: (v) => (Number.isFinite(Number(v)) ? `$${Math.round(Number(v))}k` : ''),
          },
        },
        grid: { strokeDashArray: 4, borderColor: '#e8eaed' },
        legend: { position: 'top', horizontalAlign: 'center', fontSize: '12px', fontWeight: 600 },
      },
      inspectionRows: [],
      BacklogId: null,
      AssigenedUser: null,
      IsAssignedUser: false,
    };
  },
  computed: {
    templateTag() {
      return (this.Template_Name || 'CONSTRUCTION').toString().replace(/_/g, ' ').toUpperCase();
    },
  },
  watch: {
    projectId() {
      this.loadChartData();
    },
  },
  mounted() {
    this.loadChartData();
  },
  methods: {
    openDashboardAddView() {
     this.isCriticalandBlockerDetail=true;
    },
    truncate(str, len) {
      if (str == null || str === '') return '—';
      const s = String(str);
      return s.length > len ? `${s.slice(0, len - 1)}…` : s;
    },
    loadChartData() {
      const params = `ProjectId=${this.projectId}`;
      DataService.GetChartBugProject(params)
        .then((response) => {
          const res = response.data && response.data.result;
          this.applyConstructionPayload(res || {});
          this.$nextTick(() => {
            this.chartKey += 1;
          });
        })
        .catch((e) => {
          console.error('Construction management overview load:', e);
          this.applyConstructionPayload({});
        });
    },
    applyConstructionPayload(res) {
      const cd = res.CONSTRUCTION_DASHBOARD || res.construction_dashboard || {};
      this.bindKpis(cd, res);
      this.bindPhaseChart(cd, res);
      this.bindBudgetCompare(cd, res);
      this.bindInspections(cd, res);
    },
    bindKpis(cd, res) {
      const k = cd.kpis || cd.kpi || {};
      let budgetSpent = k.budget_spent != null ? String(k.budget_spent) : cd.budget_spent;
      if (budgetSpent == null && Array.isArray(res.EXPENSEDATA) && res.EXPENSEDATA.length) {
        const used = res.EXPENSEDATA.reduce((a, x) => a + n(x.USED_AMOUNT, 0), 0);
        if (used >= 1e6) budgetSpent = `$${(used / 1e6).toFixed(1)}M`;
        else if (used >= 1000) budgetSpent = `$${Math.round(used / 1000)}k`;
        else if (used > 0) budgetSpent = `$${Math.round(used)}`;
      }
      if (budgetSpent == null) budgetSpent = '$1.4M';

      let scheduleDelay = k.schedule_delay_days != null ? `${n(k.schedule_delay_days, 8)} days` : cd.schedule_delay_days;
      if (scheduleDelay == null) {
        const tasks = Array.isArray(res.TASKDATA) ? res.TASKDATA : [];
        const maxDays = tasks.reduce((m, t) => Math.max(m, n(t.DAYS_UP, 0)), 0);
        scheduleDelay = maxDays > 0 ? `${maxDays} days` : '8 days';
      }
      if (typeof scheduleDelay === 'number') scheduleDelay = `${scheduleDelay} days`;

      let incidentFree = k.days_incident_free != null ? n(k.days_incident_free, 30) : cd.days_incident_free;
      if (!Number.isFinite(incidentFree)) incidentFree = 30;

      let inspectionsDue = k.inspections_due ?? cd.inspections_due;
      if (inspectionsDue == null || inspectionsDue === '') {
        const insp = cd.inspections || cd.inspection_schedule;
        inspectionsDue = Array.isArray(insp) && insp.length ? Math.min(9, insp.length) : 3;
      } else {
        inspectionsDue = n(inspectionsDue, 3);
      }

      this.kpiCards = [
        { label: 'Budget spent', value: budgetSpent, tint: 'orange' },
        { label: 'Schedule delay', value: scheduleDelay, tint: 'rose' },
        { label: 'Days incident-free', value: incidentFree, tint: 'green' },
        { label: 'Inspections due', value: inspectionsDue, tint: 'blue' },
      ];
    },
    bindPhaseChart(cd, res) {
      
      let rows = cd.phase_progress || cd.phases;
      if (!Array.isArray(rows) || !rows.length) {
        const ph = Array.isArray(res.PHASEDATA) ? res.PHASEDATA : [];
        if (ph.length) {
          rows = ph.map((p) => ({
            label: p.PHASE_NAME || p.phase_name || 'Phase',
            pct: n(p.phase_progress ?? p.percent, 0),
          }));
        }
      }
      if (!Array.isArray(rows) || !rows.length) {
        const st = Array.isArray(res.STAGEDATA) ? res.STAGEDATA : [];
        if (st.length) {
          rows = st.map((s) => ({
            label: s.stage_name || 'Stage',
            pct: n(s.stage_progress, 0),
          }));
        }
      }
      if (!Array.isArray(rows) || !rows.length) {
        rows =[];
      }
      const categories = rows.map((r) => r.label || r.name || r.phase || 'Phase');
      const data = rows.map((r) => n(r.pct ?? r.percent ?? r.value, 0));
      const colors = rows.map((_, i) => PHASE_COLORS[i % PHASE_COLORS.length]);
      const labelColors = data.map((pct, i) => {
        if (pct >= 100) return '#fff';
        if (pct >= 50) return '#fff';
        if (pct <= 0) return '#5f6368';
        return '#202124';
      });
      this.hasPhaseChart = categories.length > 0;
      this.phaseChartSeries = [{ name: 'Progress', data }];
      this.phaseChartOptions = {
        ...this.phaseChartOptions,
        colors,
        dataLabels: {
          ...this.phaseChartOptions.dataLabels,
          style: { ...this.phaseChartOptions.dataLabels.style, colors: labelColors },
        },
        xaxis: { ...this.phaseChartOptions.xaxis, max: 100, categories },
      };
    },
    bindBudgetCompare(cd, res) {
      let cats = [];
      let budget = [];
      let actual = [];
      const bva = cd.budget_vs_actual || cd.budgetActual;
      if (bva && Array.isArray(bva.categories) && bva.categories.length) {
        cats = bva.categories.map((c) => String(c));
        budget = (bva.budget || bva.budget_values || []).map((x) => n(x, 0));
        actual = (bva.actual || bva.actual_values || []).map((x) => n(x, 0));
      } else if (Array.isArray(res.EXPENSEDATA) && res.EXPENSEDATA.length) {
        cats = res.EXPENSEDATA.map((x) => x.CATEGORY_NAME || 'Category').slice(0, 6);
        budget = res.EXPENSEDATA.map((x) => {
          const t = n(x.CATEGORY_TOTAL_AMOUNT, 0);
          return t >= 1000 ? Math.round(t / 1000) : Math.round(t);
        }).slice(0, 6);
        actual = res.EXPENSEDATA.map((x) => {
          const u = n(x.USED_AMOUNT, 0);
          return u >= 1000 ? Math.round(u / 1000) : Math.round(u);
        }).slice(0, 6);
      }
      if (!cats.length) {
        cats = [];
        budget = [];
        actual = [];
      }
      const maxVal = Math.max(50, ...budget, ...actual, 1) * 1.12;
      this.hasBudgetCompareChart = cats.length > 0;
      this.budgetCompareSeries = [
        { name: 'Budget', data: budget },
        { name: 'Actual', data: actual },
      ];
      this.budgetCompareOptions = {
        ...this.budgetCompareOptions,
        xaxis: { ...this.budgetCompareOptions.xaxis, categories: cats },
        yaxis: { ...this.budgetCompareOptions.yaxis, max: maxVal },
      };
    },
    bindInspections(cd, res) {
      let rows = cd.inspections || cd.inspection_schedule;
      if (Array.isArray(rows) && rows.length) {
        this.inspectionRows = rows.map((r) => ({
          inspectionType: r.inspection_type || r.type || r.title || r.name || '—',
          phase: r.phase || r.phase_name || '—',
          scheduledDate: r.scheduled_date || r.scheduledDate || r.due_date,
          inspector: r.inspector || r.inspector_name || '—',
          status: r.status || r.status_name || '—',
          status_bg_color:r.status_bg_color || '--',
          notes: r.priority_name || r.note || '',
          notes_color:r.color_code || '--'
        }));
        return;
      }
      const bugs = Array.isArray(res.CRITICALBLOCKERBUGS) ? res.CRITICALBLOCKERBUGS : [];
      if (bugs.length) {
        this.inspectionRows = bugs.slice(0, 15).map((b) => ({
          inspectionType: b.task_name || b.task_number || '—',
          phase: b.Component || b.Environment || '—',
          scheduledDate: b.planned_end_date || b.planned_start_date,
          inspector: b.Created_by || '—',
          status: b.status_name || '--',
          status_bg_color:b.status_bg_color || '--',
          notes: b.priority_name || b.note || '',
           notes_color:b.color_code || '--'
        }));
        return;
      }
      this.inspectionRows = DEFAULT_INSPECTIONS.map((r) => ({ ...r }));
    },
    formatCellDate(val) {
      if (!val) return '—';
      const f = this.$options.filters && this.$options.filters.formatDate;
      if (typeof f === 'function') return f(val);
      try {
        const d = val instanceof Date ? val : new Date(val);
        if (Number.isNaN(d.getTime())) return '—';
        const mm = String(d.getMonth() + 1).padStart(2, '0');
        const dd = String(d.getDate()).padStart(2, '0');
        const yy = d.getFullYear();
        return `${mm}/${dd}/${yy}`;
      } catch (e) {
        return '—';
      }
    },
    // formatInspectionDate(d) {
    //   if (!d) return '—';
    //   try {
    //     const dt = d instanceof Date ? d : new Date(d);
    //     if (Number.isNaN(dt.getTime())) return String(d);
    //     return dt.toLocaleDateString('en-US', { month: 'short', day: '2-digit', year: 'numeric' });
    //   } catch {
    //     return String(d);
    //   }
    // },
    inspStatusClass(status) {
      const s = String(status || '').toLowerCase();
      if (s.includes('book')) return 'cn-insp-pill--booked';
      if (s.includes('schedul')) return 'cn-insp-pill--scheduled';
      if (s.includes('not start') || s.includes('pending')) return 'cn-insp-pill--muted';
      if (s.includes('complete') || s.includes('pass')) return 'cn-insp-pill--booked';
      return 'cn-insp-pill--neutral';
    },
    AssignedUser(val, users) {
      this.BacklogId = val;
      this.AssigenedUser = users;
      this.IsAssignedUser = true;
    },
  },
};
</script>

