<template>
  <section class="project-scrum-overview">
    <div class="projectoverviewbase">
        <CommonDashboard
      ref="commonDashboard"
      :project-id="projectId"
      :check-pm-user="checkPmUser"
      :new-tab-name="NewTabName"
      :tabs-array="TabsArray"
      :ProjectOwner="ProjectOwner"
      :Template_Name="Template_Name"
      @AddView="$emit('AddView', $event)"
    />
    <div class="card col-md-12 p-0 mb-3 scrum-top-card">
      <div class="card-body col-12 pt-3 pb-4 px-3 common-dashboard-shell">
        <!-- <div class="scr-intel-head d-flex flex-wrap align-items-center justify-content-between gap-3 mb-4">
          <div class="scr-intel-brand d-flex flex-wrap align-items-center">
            <em class="fa fa-star scr-intel-star" aria-hidden="true"></em>
            <span class="scr-intel-title">Template Intelligence</span>
            <span class="scr-template-badge">{{ templateTag }}</span>
          </div>         
        </div> -->

        <!-- KPI row -->
        <!-- <div class="scr-kpi-row">
          <div
            v-for="(kpi, idx) in kpiCards"
            :key="'kpi-' + idx"
            class="scr-kpi-col"
          >
            <div class="scr-kpi-card" :class="'scr-kpi-card--' + kpi.tint">
              <div class="scr-kpi-label">{{ kpi.label }}</div>
              <div class="scr-kpi-value">{{ kpi.value }}</div>
            </div>
          </div>
        </div> -->

        <!-- Burndown + Sprint goal -->
      
        <div class="row mx-0 scr-mid-row align-items-stretch">
          <div class="col-lg-8 mb-3 pl-0 pr-2 section_pp d-flex">
            <div class="section h-100 w-100 scr-chart-section">
              <div class="section-header reddy cd-panel-head scr-panel-head">
                <span class="cd-panel-title scr-panel-title">Sprint burndown — {{ sprintTitle }}</span>
              </div>
              <div class="section-body border py-2 scr-chart-body">
                <VueApexCharts
                  v-if="hasBurndown"
                  type="line"
                  height="320"
                  :options="burndownOptions"
                  :series="burndownSeries"
                  :key="'sc-bd-' + chartKey"
                />
                <div v-else class="scr-no-chart">{{ $t('NoRecordfound') }}</div>
              </div>
            </div>
          </div>
          <div class="col-lg-4 mb-3 pl-0 pr-2 section_pp d-flex">
            <div class="section h-100 w-100 scr-goal-section">
              <div class="section-header reddy cd-panel-head scr-panel-head">
                <span class="cd-panel-title scr-panel-title">Sprint goal progress</span>
              </div>
              <div class="section-body border py-3 ml-3 mr-3 scr-goal-body">
                <p class="scr-goal-text">{{ goalText }}</p>
                <div class="scr-goal-metric">
                  <div class="scr-goal-metric-head">
                    <span>Stories done</span>
                    <span class="scr-goal-metric-val">{{ goalStoriesDone }} / {{ goalStoriesTotal }}</span>
                  </div>
                  <div class="scr-progress scr-progress--green">
                    <div class="scr-progress-fill" :style="{ width: pct(goalStoriesDone, goalStoriesTotal) + '%' }"></div>
                  </div>
                </div>
                <div class="scr-goal-metric">
                  <div class="scr-goal-metric-head">
                    <span>Story points</span>
                    <span class="scr-goal-metric-val">{{ goalPointsDone }} / {{ goalPointsTotal }} pts</span>
                  </div>
                  <div class="scr-progress scr-progress--blue">
                    <div class="scr-progress-fill" :style="{ width: pct(goalPointsDone, goalPointsTotal) + '%' }"></div>
                  </div>
                </div>
                <div class="scr-goal-metric mb-0">
                  <div class="scr-goal-metric-head">
                    <span>Days elapsed</span>
                    <span class="scr-goal-metric-val">{{ goalDaysElapsed }} / {{ goalDaysTotal }} days</span>
                  </div>
                  <div class="scr-progress scr-progress--amber">
                    <div class="scr-progress-fill" :style="{ width: pct(goalDaysElapsed, goalDaysTotal) + '%' }"></div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>


        <!-- Velocity + Stories -->
        <div class="row mx-0 align-items-stretch">
          <div class="col-lg-5 mb-3 pl-0 pr-2 section_pp d-flex">
            <div class="section h-100 w-100 scr-chart-section">
              <div class="section-header reddy cd-panel-head scr-panel-head">
                <span class="cd-panel-title scr-panel-title">Sprint velocity (last 5)</span>
              </div>
              <div class="section-body border py-2 scr-chart-body">
                <VueApexCharts
                  v-if="hasVelocity"
                  type="bar"
                  height="280"
                  :options="velocityOptions"
                  :series="velocitySeries"
                  :key="'sc-vl-' + chartKey"
                />
                <div v-else class="scr-no-chart">{{ $t('NoRecordfound') }}</div>
              </div>
            </div>
          </div>
          <div class="col-lg-7 mb-3 pl-0 pr-2 section_pp">
            <div class="section scr-stories-section">
              <div class="section-header reddy cd-panel-head scr-panel-head">
                <span class="cd-panel-title scr-panel-title">{{ sprintTitle }} — Stories</span>
                <small class="cd-panel-actions">
                  <a href="javascript:;" class="scr-view-all-link font-13" @click="openDashboardAddView">
                    <em class="fa fa-eye mr-1"></em>{{ $t('View All') }}
                  </a>
                </small>
              </div>
              <div class="section-body border p-0">
                <div class="table-responsive scr-stories-wrap">
                <table class="table mb-0 scr-stories-table">
                    <thead>
                      <tr>
                        <th>{{ $t('Key') }}</th>
                        <th>{{ $t('Story') }}</th>
                        <th>{{ $t('Asignee') }}</th>
                        <th>{{ $t('Created by') }}</th>
                        <th>{{ $t('Status') }}</th>
                           <th>{{ $t('Priority') }}</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr v-for="(row, idx) in sprintStories" :key="'st-' + idx">
                        <td><span class="scr-story-key">{{ row.key }}</span></td>
                        <td class="scr-story-title" :title="row.story">{{ truncate(row.story, 48) }}</td>
                        <td>{{ row.assignee || '—' }}</td>
                        
                        <td>{{ row.points != null ? row.points : '—' }}</td>
                        <td>
                          <span class="scr-status-pill" :class="row.statusClass">{{ row.status }}</span>
                        </td>
                      <td>
                      <span 
                        class="scr-status-pill text-white" 
                        :class="row.priorityClass" 
                        :style="{ backgroundColor: row.priorityClass }">
                        {{ row.priority }}
                      </span>
                    </td>
                                          </tr>
                      <tr v-if="!sprintStories.length">
                        <td colspan="6" class="text-center text-danger py-4">{{ $t('NoRecordfound') }}</td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    <CriticalandBlockerDetail v-if="isCriticalandBlockerDetail" :Type="Template_Name"  :HeaderText="sprintTitle + ' — Stories'"/>
    </div>
  </section>
</template>

<script>
import CommonDashboard from '../CommonDashboard.vue';
import VueApexCharts from 'vue-apexcharts';
import DataService from '../../../../../../services/DataService';
import CriticalandBlockerDetail from '../../../../../../components/Modal/CriticalandBlockerDetail.vue';
function n(v, fallback = 0) {
  const x = Number(v);
  return Number.isFinite(x) ? x : fallback;
}

export default {
  name: 'ProjectScrumOverview',
  components: { CommonDashboard, VueApexCharts,CriticalandBlockerDetail },
  props: {
    projectId: { type: Number, required: true },
    checkPmUser: { type: Boolean, required: true },
    NewTabName: { type: String, required: true },
    TabsArray: { type: Array, default: () => [] },
    Template_Name: { type: String, required: true },
    ProjectOwner:{type: Boolean, required: true},
  },
  data() {
    return {
      isCriticalandBlockerDetail:false,
      chartKey: 0,
      sprintTitle: 'Current sprint',
      kpiCards: [],
      goalText: '—',
      goalStoriesDone: 0,
      goalStoriesTotal: 0,
      goalPointsDone: 0,
      goalPointsTotal: 0,
      goalDaysElapsed: 0,
      goalDaysTotal: 0,
      hasBurndown: false,
      burndownSeries: [],
      burndownOptions: {
        chart: {
          type: 'line',
          toolbar: { show: false },
          fontFamily: 'inherit',
          zoom: { enabled: false },
        },
        stroke: { curve: 'straight', width: [2, 3], dashArray: [6, 0] },
        colors: ['#9aa0a6', '#1a73e8'],
        markers: { size: [0, 4], strokeWidth: 2, hover: { size: 5 } },
        dataLabels: { enabled: false },
        xaxis: { labels: { style: { fontSize: '11px' } } },
        yaxis: { labels: { style: { fontSize: '11px' } } },
        grid: { strokeDashArray: 4, borderColor: '#e8eaed' },
        legend: { show: true, position: 'top', horizontalAlign: 'right', fontSize: '12px' },
        tooltip: { shared: true },
      },
      hasVelocity: false,
      velocitySeries: [],
      velocityOptions: {
        chart: { type: 'bar', toolbar: { show: false }, fontFamily: 'inherit' },
        plotOptions: { bar: { borderRadius: 4, columnWidth: '55%' } },
        colors: ['#aecbfa'],
        dataLabels: { enabled: false },
        xaxis: { categories: ['S-1', 'S-2', 'S-3', 'S-4', 'S-5'], labels: { style: { fontSize: '11px' } } },
        yaxis: { labels: { style: { fontSize: '11px' } } },
        grid: { strokeDashArray: 4, borderColor: '#e8eaed' },
        legend: { show: false },
      },
      sprintStories: [],
    };
  },
  computed: {
    templateTag() {
      return (this.Template_Name || 'SCRUM').toString().toUpperCase();
    },
  },
  watch: {
    projectId() {
      this.loadChartData();
    },
  },
  mounted() {
    this.loadChartData();
  },
  methods: {
    openDashboardAddView() {
     this.isCriticalandBlockerDetail=true;
    },
    truncate(str, len) {
      if (str == null || str === '') return '—';
      const s = String(str);
      return s.length > len ? s.slice(0, len - 1) + '…' : s;
    },
    pct(done, total) {
      const t = n(total, 0);
      if (t <= 0) return 0;
      return Math.min(100, Math.round((n(done, 0) / t) * 100));
    },
    loadChartData() {
      const params = `ProjectId=${this.projectId}`;
      DataService.GetChartBugProject(params)
        .then((response) => {
          const res = response.data && response.data.result;
          if (!res) return;
          this.applyPayload(res);
          this.$nextTick(() => {
            this.chartKey++;
          });
        })
        .catch((e) => console.error('Scrum overview load:', e));
    },
    applyPayload(res) {
      const sd = res.SCRUM_DASHBOARD || res.scrum_dashboard || res.SCRUM_TEMPLATE || res.scrum_template || {};
      const merged = { ...sd };

      this.bindKpis(merged, res);
      this.bindGoal(merged, res);
      this.bindBurndown(merged, res);
      this.bindVelocity(merged, res);
      this.bindStories(merged, res);
    },
    bindKpis(merged, res) {
      if(res.WIDGETDATA.length==0 || res.WIDGETDATA.length=='') return;
      const name =
        merged.sprint_name ||
        merged.sprintName ||
        (Array.isArray(res.WIDGETDATA) && res.WIDGETDATA[0] && (res.WIDGETDATA[0].name || res.WIDGETDATA[0].SPRINT_NAME)) ||
        '--';
      const committed = n( res.WIDGETDATA[0].commited ?? merged.story_points_committed ?? merged.points_committed, 0);
      const completed = n( res.WIDGETDATA[0].completed ?? merged.points_completed, 0);
      const daysLeft = n( res.WIDGETDATA[0].daysLeft ?? merged.days_left, 0);
      const statusData = Array.isArray(res.WIDGETDATA) ? res.WIDGETDATA : [];
      const totalTasks = statusData.reduce((a, x) => a + n(x.total_count, 0), 0);
      if (!committed && totalTasks) {
        this.kpiCards = [
          { label: 'Current sprint', value: String(name).slice(0, 8) || '—', tint: 'sprint' },
          { label: 'Story points committed', value: Math.max(totalTasks, 0), tint: 'committed' },
          { label: 'Points completed', value: Math.floor(totalTasks * 0.55), tint: 'done' },
          { label: 'Days remaining', value: Math.max(1, 14 - Math.floor(totalTasks / 3)), tint: 'days' },
        ];
        return;
      }
      this.kpiCards = [
        { label: 'Current sprint', value: name, tint: 'sprint' },
        { label: 'Story points committed', value: committed || totalTasks || 0, tint: 'committed' },
        { label: 'Points completed', value: completed || Math.floor((committed || totalTasks) * 0.55) || 0, tint: 'done' },
        { label: 'Days remaining', value: daysLeft , tint: 'days' },
      ];
    },
    bindGoal(merged, res) {
      this.sprintTitle = merged.sprint_title || merged.sprint_name || this.sprintTitle;
      this.goalText =
        merged.goal_text ||
        merged.sprint_goal ||
        'Complete planned sprint scope and keep burndown on track.';
      this.goalStoriesTotal = n(res.SPRINTPROGRESS[0].total_story ?? merged.complete_story, 8);
      this.goalStoriesDone = n(res.SPRINTPROGRESS[0].complete_story ?? merged.stories_completed, 5);
      this.goalPointsTotal = n(res.SPRINTPROGRESS[0].total_sprint ?? merged.story_points_committed, 21);
      this.goalPointsDone = n(res.SPRINTPROGRESS[0].complete_sprint ?? merged.points_completed, 14);
      this.goalDaysTotal = n(merged.sprint_days ?? merged.sprint_length, 14);
      this.goalDaysElapsed = n(0, 8);
      const statusData = Array.isArray(res.SPRINTPROGRESS[0]) ? res.SPRINTPROGRESS[0] : [];
      if (!merged.stories_total && statusData.length) {
        this.goalStoriesTotal = Math.max(1, statusData.reduce((a, x) => a + n(x.total_count, 0), 0));
        this.goalStoriesDone = Math.floor(this.goalStoriesTotal * 0.6);
        this.goalPointsTotal = Math.max(this.goalPointsTotal, this.goalStoriesTotal * 2);
        this.goalPointsDone = Math.floor(this.goalPointsTotal * 0.65);
      }
    },
    // bindBurndown(merged, res) {
    //   debugger
    //   const ideal = merged.burndown_ideal || merged.ideal_line;
    //   const actual = merged.burndown_actual || merged.actual_line;
    //   if (Array.isArray(ideal) && ideal.length && Array.isArray(actual) && actual.length) {
    //     const cats = merged.burndown_categories || ideal.map((_, i) => `Day ${i + 1}`);
    //     const idealData = ideal.map((v) => n(v.value ?? v, 0));
    //     const actualData = actual.map((v) => n(v.value ?? v, 0));
    //     this.hasBurndown = true;
    //     this.burndownSeries = [
    //       { name: 'Ideal', data: idealData },
    //       { name: 'Actual', data: actualData },
    //     ];
    //     this.burndownOptions = {
    //       ...this.burndownOptions,
    //       xaxis: { ...this.burndownOptions.xaxis, categories: cats },
    //     };
    //     return;
    //   }
    //   const committed = this.goalPointsTotal;
    //   const days = Math.max(7, n(this.goalDaysTotal));
    //   const categories = Array.from({ length: days }, (_, i) => `Day ${i + 1}`);
    //   const idealData = categories.map((_, i) => Math.max(0, Math.round(committed - (committed * i) / (days - 1))));
    //   const elapsed = Math.min(days, Math.max(3, n(this.goalDaysElapsed, 8)));
    //   const actualData = categories.map((_, i) => {
    //     if (i >= elapsed) return null;
    //     const noise = Math.sin(i * 0.7) * 0.8;
    //     return Math.max(0, Math.round(idealData[i] + noise + i * 0.35));
    //   });
    //   this.hasBurndown = true;
    //   this.burndownSeries = [
    //     { name: 'Ideal', data: idealData },
    //     { name: 'Actual', data: actualData },
    //   ];
    //   this.burndownOptions = {
    //     ...this.burndownOptions,
    //     xaxis: { ...this.burndownOptions.xaxis, categories },
    //   };
    // },
    bindBurndown(merged, res) {
  const burndownData = res.SPRINTBURDOWN || [];
  if(burndownData.length==0 || burndownData.length=='') return;
  if (Array.isArray(burndownData) && burndownData.length) {
    const sprints = burndownData.reduce((acc, item) => {
      if (!acc[item.sprint_id]) {
        acc[item.sprint_id] = {
          sprint_id: item.sprint_id,
          categories: [],
          idealData: [],
          actualData: []
        };
      }
      acc[item.sprint_id].categories.push(`Day ${item.DayNumber}`);
      acc[item.sprint_id].idealData.push(n(item.IdealLine, 0));
      acc[item.sprint_id].actualData.push(n(item.ActualLine, 0));
      return acc;
    }, {});t
    this.burndownSeries = Object.keys(sprints).map(sprintId => {
      const sprint = sprints[sprintId];
      return [
        { name: 'Ideal', data: sprint.idealData },
        { name: 'Actual', data: sprint.actualData }
      ];
    }).flat(); 
    this.burndownOptions = {
      ...this.burndownOptions,
      xaxis: {
        ...this.burndownOptions.xaxis,
        categories: sprints[Object.keys(sprints)[0]].categories,  
      },
    };

    this.hasBurndown = true;
    return;
  }
  const committed = this.goalPointsTotal ;
  const days = Math.max(7, n(this.goalDaysTotal));
  const categories = Array.from({ length: days }, (_, i) => `Day ${i + 1}`);
  const idealData = categories.map((_, i) => Math.max(0, Math.round(committed - (committed * i) / (days - 1))));
  const elapsed = Math.min(days, Math.max(3, n(this.goalDaysElapsed, 8)));
  const actualData = categories.map((_, i) => {
    if (i >= elapsed) return null;
    const noise = Math.sin(i * 0.7) * 0.8;
    return Math.max(0, Math.round(idealData[i] + noise + i * 0.35));
  });
  this.hasBurndown = true;
  this.burndownSeries = [
    { name: 'Ideal', data: idealData },
    { name: 'Actual', data: actualData },
  ];

  this.burndownOptions = {
    ...this.burndownOptions,
    xaxis: { ...this.burndownOptions.xaxis, categories },
  };
},
    bindVelocity(merged, res) {
      const rows =res.SPRINTDATA;
      if(rows.length==0) return;
      if (Array.isArray(rows) && rows.length) {
        const cats = rows.map((r) => r.label || r.sprint_name || r.name || '');
        const data = rows.map((r) => n(r.task_count ?? r.value, 0));
        this.hasVelocity = data;
        this.velocitySeries = [{ name: 'Points', data }];
        this.velocityOptions = {
          ...this.velocityOptions,
          xaxis: { ...this.velocityOptions.xaxis, categories: cats },
        };
        return;
      }
      const data = [18, 16, 21, 0, 0];
      this.hasVelocity = data.some((v) => v > 0);
      this.velocitySeries = [{ name: 'Points', data }];
    },
    // bindStories(merged, res) {
    //   const raw = merged.stories || merged.sprint_stories;
    //   if (Array.isArray(raw) && raw.length) {
    //     this.sprintStories = raw.map((s) => this.normalizeStoryRow(s));
    //     return;
    //   }
    //   const bugs = Array.isArray(res.CRITICALBLOCKERBUGS) ? res.CRITICALBLOCKERBUGS : [];
    //   if (bugs.length) {
    //     this.sprintStories = bugs.slice(0, 12).map((b) => ({
    //       key: b.task_number || '—',
    //       story: b.task_name || '—',
    //       assignee: this.firstAssignee(b.Assign),
    //       points: b.story_point != null ? b.story_point : b.points,
    //       status: b.status_name || '—',
    //       statusClass: this.statusPillClass(b.status_name),
    //     }));
    //     return;
    //   }
    //   this.sprintStories = [];
    // },
     bindStories(merged, res) {
      const raw = merged.stories || merged.sprint_stories;
      if (Array.isArray(raw) && raw.length) {
        this.sprintStories = raw.map((s) => this.normalizeStoryRow(s));
        return;
      }
      const bugs = Array.isArray(res.CRITICALBLOCKERBUGS) ? res.CRITICALBLOCKERBUGS : [];
      if (bugs.length) {
        this.sprintStories = bugs.slice(0, 12).map((b) => ({
          key: b.task_number || '—',
          story: b.task_name || '—',
          assignee: this.firstAssignee(b.Assign),
          points: b.Created_by != null ? b.Created_by : b.Created_by,
          status: b.status_name || '—',
          statusClass: this.statusPillClass(b.status_name),
         priority: b.priority_name || '—',
        priorityClass: b.color_code,
        }));
        return;
      }
      this.sprintStories = [];
    },
    normalizeStoryRow(s) {
      const st = s.status || s.status_name || '—';
      return {
        key: s.key || s.task_number || '—',
        story: s.story || s.task_name || s.title || '—',
        assignee: s.assignee || s.assignee_name || this.firstAssignee(s.Assign) || '—',
        points: s.points != null ? s.points : s.story_points,
        status: st,
        statusClass: s.statusClass || this.statusPillClass(st),
      };
    },
    firstAssignee(assign) {
      if (!assign || !String(assign).trim()) return '';
      return String(assign)
        .split(',')
        .map((x) => x.trim())
        .filter(Boolean)[0];
    },
    statusPillClass(name) {
      const s = String(name || '').toLowerCase();
      if (s.includes('complete') || s.includes('done')) return 'scr-pill--done';
      if (s.includes('pending') || s.includes('review')) return 'scr-pill--pending';
      if (s.includes('active') || s.includes('progress')) return 'scr-pill--active';
      return 'scr-pill--muted';
    },
  },
};
</script>

