<template>
    <div class="col-md-12 p-0 mt-2">
        <loader :is-visible="isLoading"></loader>

        <tg-ganttChart ref="ganttChart" :isHeaderVisible="isHeaderVisible" :options="options" :tasks="tasks"
            @tasks-changed="tasksUpdate" @options-changed="optionsUpdate" @dynamic-style-changed="styleUpdate"
            @task-updated="handleTaskUpdated" :projectName="projectName" :header-left-side-labels="headerLeftSideLabels"
            :header-legend-config="headerLegendConfig"></tg-ganttChart>

        <div class="add-backlog-btn border bg-light float-left w-100" v-if="isCreateEpic">
            <a v-if="!IsAddEpic" class="p-3 w-100 text-dark float-left" @click="AddEpic" type="button">
                <em class="fa fa-plus pr-2"></em>{{ $t('Create') }} {{ $t('Epic') }}
            </a>
            <div class="input-group w-100 pb-3 px-3 pt-3" v-if="IsAddEpic">
                <div class="input-group-prepend border-right-0">
                    <span class="input-group-text bg-white px-2" id="basic-addon1">
                        <em class="fa-solid fa-bolt epic-task"></em>
                    </span>
                </div>
                <input type="text" @keydown.enter="SaveEpic" v-model="txtEpicTitle"
                    class="form-control px-1 bg-white border-left-0" placeholder="What needs to be done..?"
                    aria-label="" aria-describedby="basic-addon1" />
                <div class="col-sm-1 pt-1">
                    <a class="actions-onclick" title="Save" @click="SaveEpic"><em
                            class="fa fa-save action-icon text-success"></em></a>
                    <a @click="IsHideAddEpic" class="actions-onclick"><em
                            class="fa fa-close action-icon text-danger"></em></a>
                </div>
            </div>
        </div>

        <AddEditEpic v-if="IsAddEditEpic" :EpicDeatils="EpicDeatils" @close="handleCloseModal"
            @ReloadTimeline="ReloadTimeline" :key="reloadkey" />
        <EditTask v-if="IsEditTask" :projectdata="taskDetail" @callbackfunction="ReloadTimeline" :key="reloadkey"
            :isHideSprint="isHideSprint" :NewTabName="NewTabName" :TabsArray="TabsArray" />
        <AddMilestone v-if="MilestoneListingSchema" :ProjectName="projectName" :MilestoneID="MileStoneId"
            :projectId="projectId" :NewTabName="NewTabName" :TabsArray="TabsArray" :key="reloadkey"
            :projectCurrency="projectCurrency" />
        <AddProjectPhaseAssociate v-if="PhaseAssociate" :NewTabName="NewTabName" :EditPhaseId="EditPhaseId"
            :TabsArray="TabsArray" :key="reloadkey" />
        <AddAssociateStage v-if="IsAddAssociateStage" :NewTabName="NewTabName" :TabsArray="TabsArray"
            :ProjectIndusrtyType="ProjectIndusrtyType" :EditStageId="EditStageId" :key="reloadkey">
        </AddAssociateStage>
        <AddProject v-if="IsAddProject" :ProjectId="ProjectId" :Type="Type" @callbackfunction="CloseProjectModal"
            :key="reloadkey" />
        <CreateSprint v-if="IsCreateSprint" :TabsArray="TabsArray" :IsSprintTabType="IsSprintTabType"
            :SprintData="SprintData" :projectdata="GetProjectData" :NewTabName="NewTabName"></CreateSprint>
    </div>
</template>
<script>
import DataService from "../../../../services/DataService";
import dayjs from "dayjs";
import isoWeek from 'dayjs/plugin/weekOfYear';
import quarterOfYear from 'dayjs/plugin/quarterOfYear';
import AddEditEpic from "../../../../components/Modal/AddEditEpic.vue";
import EditTask from '../../../../components/Modal/EditTask.vue'
import AddMilestone from "../../../../components/Modal/AddMilestone.vue";
import AddProjectPhaseAssociate from "../../../../components/Modal/AddProjectPhaseAssociate.vue";
import AddAssociateStage from "../../../../components/Modal/AddAssociateStage.vue";
import AddProject from "../../../../components/Modal/AddProject.vue";
import CreateSprint from "../../../../components/Modal/CreateSprint.vue";
dayjs.extend(isoWeek);
dayjs.extend(quarterOfYear);

/** Stops duplicate delete/edit: tg-ganttchart used to $emit twice; multiple $root.$on also stack. */
const _timelineActionCoalesce = { sig: '', t: 0 };
const TIMELINE_ACTION_DEBOUNCE_MS = 800;
function timelineConsumeActionOnce(action, task) {
    const sig = `${action}|${task && task.id}|${task && task.type}`;
    const now = Date.now();
    if (_timelineActionCoalesce.sig === sig && now - _timelineActionCoalesce.t < TIMELINE_ACTION_DEBOUNCE_MS) {
        return false;
    }
    _timelineActionCoalesce.sig = sig;
    _timelineActionCoalesce.t = now;
    return true;
}

export default {
    name: 'GanttChart',
    components: {
        AddEditEpic, EditTask, AddMilestone, AddProjectPhaseAssociate, AddAssociateStage, AddProject, CreateSprint
    },
    props: {
        checkPmUser: {
            type: Boolean,
            required: true
        },
        NewTabName: {
            type: String,
            require: true
        },
        TabsArray: {
            type: Array
        },
        projectCurrency: {
            type: String
        },
        ProjectOwner: {
            type: String
        }
    },
    data() {
        return {
            GetProjectData: null,
            SprintData: null,
            IsSprintTabType: '',
            IsCreateSprint: false,
            isCreateEpic: false,
            reloadkey: 0,
            isHideSprint: true,
            IsEditTask: false,
            PhaseAssociate: false,
            IsAddAssociateStage: false,
            isHeaderVisible: false,
            IsAddEpic: false,
            MilestoneListingSchema: false,
            isEpicData: false,
            isManageDetails: false,
            ProjectIndusrtyType: '',
            EpicData: [],
            taskDetail: [],
            EditPhaseId: 0,
            headerLeftSideLabels: ['Timeline'],
            headerLegendConfig:  [
        {
          type: 'project',
          label: 'Project',
          color: '#2563EB'
        },
        {
          type: 'phase',
          label: 'Phase',
          color: '#7C2D12'
        },
        {
          type: 'stage',
          label: 'Stage',
          color: '#ec4899'
        },
        {
          type: 'epic',
          label: 'Epic',
          color: '#9333EA'
        },
        {
          type: 'sprint',
          label: 'Sprint',
          color: '#F59E0B'
        },
        {
          type: 'story',
          label: 'Story',
          color: '#A3E635'
        },
        {
          type: 'subtask',
          label: 'Subtask',
          color: '#0EA5E9'
        },
        {
          type: 'task',
          label: 'Task',
          color: '#10B981'
        },
        {
          type: 'bug',
          label: 'Bug',
          color: '#EF4444'
        },
        {
          type: 'milestone',
          label: 'Milestone',
          color: '#14B8A6'
        }
      ],
            tasks: [],
            options: {
                taskMapping: {
                    progress: "percent"
                },
                maxRows: 100,
                maxHeight: 500,
                title: {
                    label: "Your project title as html (link or whatever...)",
                    html: true
                },
                row: {
                    height: 24
                },
                calendar: {
                    viewMode: 'day',
                    hour: { height: 20, display: false },
                    day: { height: 30, display: true },
                    week: { height: 24, display: true },
                    month: { height: 30, display: true },
                    quarter: {
                        height: 30,
                        display: true,
                    }
                },
                chart: {
                    progress: {
                        bar: false
                    },
                    expander: {
                        display: true
                    }
                },
                taskList: {
                    expander: {
                        straight: false
                    },
                    actionButtons: {
                        display: true,
                        buttons: {
                            edit: {
                                display: true,
                                condition: function (task) {
                                    return true;
                                }
                            },
                            delete: {
                                display: true,
                                condition: function (task) {
                                    if (!task || !task.type) return false;
                                    if (task.type === 'project') {
                                        return false;
                                    }
                                    if (task.allChildren && task.allChildren.length > 0) {
                                        return true;
                                    }
                                    return true;
                                }
                            },
                            view: {
                                display: true,
                                condition: function (task) {
                                    return false;
                                }
                            }
                        }
                    },
                    columns: [
                        {
                            id: 2,
                            label: "Description",
                            value: "label",
                            width: 130,
                            expander: true,
                            html: true,
                            events: {
                                click: function ({ data }) {
                                    this.OpenAddEditEpic(data);
                                }.bind(this)
                            }
                        },
                        {
                            id: 3,
                            label: "Assigned to",
                            value: "user",
                            width: 100,
                            html: true
                        },
                        {
                            id: 3,
                            label: "Start Date",
                            value: task => dayjs(task.start).format("MM/DD/YYYY"),
                            width: 100
                        },
                        {
                            id: 4,
                            label: "End Date",
                            value: task => dayjs(task.end).format("MM/DD/YYYY"),
                            width: 100
                        },
                        {
                            id: 6,
                            label: "Actions",
                            width: 120,
                            html: true,
                            value: function (task) {
                                const buttons = this.buttons || [];
                                if (!task || !Array.isArray(buttons) || buttons.length === 0) {
                                    return '';
                                }
                                const visibleButtons = buttons.filter(btn => btn.show !== false);
                                return visibleButtons.map(btn => {
                                    const icon = btn.icon || '';
                                    const btnClass = btn.class || '';
                                    const btnLabel = btn.label || '';
                                    const action = btn.action || '';
                                    const btnId = btn.id || '';
                                    const iconHtml = icon ? `<i class="${icon}"></i>` : '';
                                    return `<a 
                                        href="javascript:void(0);"
                                        class="action-btn ${btnClass}" 
                                        data-task-id="${task.id}" 
                                        data-action="${action}"
                                        data-button-id="${btnId}"
                                        title="${btnLabel}"
                                        style="cursor: pointer; margin: 0 2px; display: inline-block; text-decoration: none;color:${btn.iconColor};  font-size: 16px; padding: 4px; vertical-align: middle;">
                                        ${iconHtml}
                                        </a>`;
                                }).join('');
                            },
                            buttons: [
                                {
                                    id: 'edit',
                                    label: 'Edit',
                                    icon: 'fa fa-pencil',
                                    class: 'text-success',
                                    action: 'edit',
                                    iconColor: '#10B981',
                                    show: true
                                },
                                {
                                    id: 'delete',
                                    label: 'Delete',
                                    icon: 'fa fa-trash-o',
                                    class: 'text-danger',
                                    action: 'delete',
                                    iconColor: '#EF4444',
                                    show: true
                                },
                                {
                                    id: 'view',
                                    label: 'View',
                                    icon: 'fa fa-eye',
                                    class: 'text-primary',
                                    action: 'view',
                                    iconColor: '#3B82F6',
                                    show: true
                                }
                            ],
                            style: {
                                "task-list-header-label": {
                                    "text-align": "center",
                                    width: "100%"
                                },
                                "task-list-item-value-container": {
                                    "text-align": "center",
                                    width: "100%"
                                }
                            }
                        },
                    ]
                },
                locale: {
                    name: "en",
                    Now: "Now",
                    "X-Scale": "Zoom-X",
                    "Y-Scale": "Zoom-Y",
                    "Task list width": "Task list",
                    "Before/After": "Expand",
                    "Display task list": "Task list"
                }
            },
            dynamicStyle: {},
            lastId: 16,
            projectName: '',
            isLoading: false,
            projectId: '',
            IsAddEditEpic: false,
            EpicDeatils: {},
            txtEpicTitle: '',
            isDeleting: false,
            isEditing: false,
            isViewing: false,
            _syncingTasksFromServer: false,
            MileStoneData: [],
            MileStoneId: 0,
            IsAddProject: 0,
            ProjectId: 0,
            Type: ''
        };
    },    
    async created() {
        var vm = this;
        vm.projectId = this.$route.params.projectId;
        vm.ProjectId = this.$route.params.projectId;
        vm.projectName = this.$route.params.project_name;
        vm.GetCreateEpicPrivilege();
        await vm.ProjectOverview();
        this.GetEpicDeatils(0);
    },
    mounted() {    
        this.$root.$off('action-button-clicked');
        this.$root.$on('action-button-clicked', this.handleActionButtonClick);
    },
    beforeUnmount() {
        this.$root.$off('action-button-clicked', this.handleActionButtonClick);
    },
    methods: {
        async GetCreateEpicPrivilege() {
            var ths = this;
            var url = 'controller=Project&action=AddUpdateEpic'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data  || ths.checkPmUser || ths.ProjectOwner) {
                    ths.isCreateEpic = true;
                }
                else {
                    ths.isCreateEpic = false;
                }
            });
        },
        CloseProjectModal() {
            this.reloadkey++;
            this.IsAddProject = false;
            $(".modal-backdrop").remove();
            this.GetEpicDeatils(0);
        },
        ProjectOverview: async function () {
            var vm = this;
            var params = `projectId=${vm.ProjectId}`;
            await DataService.GetProjectDetails(params).then(function (response) {
                if (response.data != null > 0) {
                    var ProjectDetailData = response.data.result.PROJECTOVERVIEW[0];
                    vm.ProjectIndusrtyType = ProjectDetailData.IndustryType_Name;
                }
            });
        },
        handleActionButtonClick(payload) {
            const { action, task } = payload;
            if (!timelineConsumeActionOnce(action, task)) {
                return;
            }
            if (action === 'delete' && this.isDeleting) {
                return;
            }
            if (action === 'edit' && this.isEditing) {
                return;
            }
            if (action === 'view' && this.isViewing) {
                return;
            }
            switch (action) {
                case 'edit':
                    this.handleEdit(task);
                    break;
                case 'delete':
                    this.handleDelete(task);
                    break;
                case 'view':
                    this.handleView(task);
                    break;
                default:
                    
            }
        },
        FetchTaskList() { this.GetEpicDeatils(0); this.reloadkey++; },

        async handleEdit(data) {
            this.isEditing = true;
            var ths = this;
            try {
                if (data.type === 'epic') {
                    var url = 'controller=Project&action=AddUpdateEpic'
                    await DataService.CheckPrivilege(url).then(async function (response) {
                        if (response.data  || ths.checkPmUser || ths.ProjectOwner) {
                            ths.IsAddEditEpic = true;
                            ths.EpicDeatils = data;
                            setTimeout(() => {
                                $("#modalEditTask").modal("show");
                                ths.isEditing = false;
                            }, 1000);
                        } else {
                            ths.ShowAlert(ths.$t('NotAuthorizedSection'), "failure", true, "Alert");
                        }
                    });
                }
                else if (data.type === 'task' || data.type === 'story' || data.type === 'Bug') {
                    const url = `id=${data.id}`;
                    const response = await DataService.GetEpicStoryTaskDetails(url);
                    if (response.data.result.Data.length > 0) {
                        this.IsAddEditEpic = false;
                        this.taskDetail = response.data.result.Data[0];
                        this.taskDetail.child = [];
                        this.IsEditTask = true;
                        this.reloadkey++;
                        setTimeout(() => {
                            $("#modalEditTask").modal("show");
                            this.isEditing = false;
                        }, 1000);
                    } else {
                        this.isEditing = false;
                    }
                }
                else if (data.type === 'phase') {
                    this.EditPhaseId = data.id;
                    this.PhaseAssociate = true;
                    this.reloadkey++;
                    this.isEditing = false;
                }
                else if (data.type === 'stage') {
                    this.EditStageId = data.id;
                    this.IsAddAssociateStage = true;
                    this.isEditing = false;
                }
                else if (data.type === 'milestone') {
                    this.MileStoneId = data.id;
                    this.MilestoneListingSchema = true;
                    this.reloadkey++;
                    this.isEditing = false;
                }
                else if (data.type === 'project') {
                    this.Type = 'OverView';
                    this.ProjectId = data.id;
                    this.IsAddProject = true;
                    this.reloadkey++;
                    setTimeout(function () {
                        $("#modalAddProject").modal("show");
                    }, 1000);
                    this.isEditing = false;
                }
                else if (data.type === 'Sprint') {                    
                    this.IsCreateSprint = true;
                    this.IsSprintTabType = 'Sprint';
                    this.SprintData = {
                        sprint_id: data.id,
                        sprint_name: (data.label || "").replace(/<[^>]*>/g, "").trim(),
                        duration: this.formatDuration(data.duration || 0),
                        STARTDATE: data.start,
                        ENDATE: data.end,
                        descripton: (data.description || '').replace(/<[^>]*>/g, '').trim(),
                    };
                    this.reloadkey++;
                    this.isEditing = false;
                }
                else {
                    this.isEditing = false;
                }
            } catch (error) {
                console.error('Error in handleEdit:', error);
                this.isEditing = false;
                this.MilestoneListingSchema = false;
                this.PhaseAssociate = false;
            }
        },
        formatDuration(ms) {
            if (!ms) return "00:00:00";
            const totalSeconds = Math.floor(ms / 1000);
            const hours = Math.floor(totalSeconds / 3600);            
            return [
                String(hours).padStart(2, "0")
            ].join(":");
        },
        async handleDelete(data) {
            const vm = this;
            if (vm.isDeleting) {
                return;
            }
            if (data.type == 'epic') {
                var url = 'controller=Project&action=DeleteEpic';
                await DataService.CheckPrivilege(url).then(async function (response) {
                    if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                        vm.isDeleting = true;
                        if (data.id != null && data.id != "") {
                            vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Epic")), () => {
                                var postJSON = {
                                    ids: data.id,
                                    moduleName: "PROJECT",
                                    subModuleCode: "PROJECT_DETAIL",
                                    refCode: 'Project_Epic'
                                };
                                var objectPostString = JSON.stringify(postJSON);
                                DataService.CommonCommonDelete(objectPostString).then((response) => {
                                    vm.isLoading = false;
                                    if (response.status == 200) {
                                        vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Epic')]), "success", true, vm.$t("Alert"));
                                        vm.ReloadTimeline();
                                    }
                                    else {
                                        vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Epic')]), "Success", true, vm.$t("Alert"));
                                    }
                                    vm.isDeleting = false;
                                }).catch((error) => {
                                    console.error('Delete error:', error);
                                    vm.isDeleting = false;
                                });
                            }, () => {
                                vm.isDeleting = false;
                            });
                        } else {
                            vm.isDeleting = false;
                        }
                    }
                    else {
                        vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                    }
                });
            }
            else if (data.type == 'task' || data.type == 'story') {
                var url = 'controller=Task&action=Delete'
                await DataService.CheckPrivilege(url).then(async function (response) {
                    if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                        vm.isDeleting = true;
                        vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Task")), () => {
                            var postJSON = {
                                ids: data.id,
                                moduleName: "PROJECT",
                                refCode: "TALYGEN_GLOBAL_TASK"
                            };
                            var objectPostString = JSON.stringify(postJSON);
                            DataService.CommonCommonDelete(objectPostString).then(function (response) {
                                vm.isLoading = false;
                                if (response.data.length > 0) {
                                    if (response.data[0].Status == 'Success') {
                                        if (response.data[0].Code == 'TASK_ASSIGN') {
                                            vm.ShowAlert(vm.$t('proceedingwithdeletion', [vm.$t(data.type)]), "failure", true, vm.$t("Alert"));
                                        } else {
                                            vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t(data.type)]), "success", true, vm.$t("Alert"));
                                            vm.ReloadTimeline();
                                        }
                                    }
                                    else {
                                        vm.ShowAlert(vm.$t('DeletedError', [vm.$t(data.type)]), "failure", true, vm.$t("Alert"));
                                    }
                                }
                                else {
                                    vm.ShowAlert(vm.$t('DeletedError', [vm.$t(data.type)]), "failure", true, vm.$t("Alert"));
                                }
                                vm.isDeleting = false;
                            }).catch(() => {
                                vm.ShowAlert(vm.$t('DeletedError', [vm.$t(data.type)]), "failure", true, vm.$t("Alert"));
                                vm.isDeleting = false;
                            });
                        }, () => {
                            vm.isDeleting = false;
                        });
                    } else {
                        vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                    }
                });

            }
            else if (data.type == 'milestone') {
                var url = 'controller=Milestone&action=DeleteMilestone'
                await DataService.CheckPrivilege(url).then(async function (response) {
                    if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                        vm.isDeleting = true;
                        vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Milestone")), () => {
                            var postJSON = {
                                ids: data.id,
                                moduleName: "PROJECT",
                                refCode: "TALYGEN_milestone"
                            };
                            var objectPostString = JSON.stringify(postJSON);
                            DataService.CommonCommonDelete(objectPostString).then(function (response) {
                                if (response.status == 200) {
                                    vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Milestone')]), "success", true, vm.$t("Alert"));
                                    vm.FetchTaskList();
                                }
                                else {
                                    vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Milestone')]), "Success", true, vm.$t("Alert"));
                                }
                                vm.isDeleting = false;
                            }).catch(() => {
                                vm.isDeleting = false;
                            });
                        }, () => {
                            vm.isDeleting = false;
                        });
                    } else {
                        vm.isLoading = false;
                        vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                    }
                });
            }
            else if (data.type == 'phase') {
                var url = 'controller=Project&action=DeletePhase'
                await DataService.CheckPrivilege(url).then(async function (response) {
                    if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                        vm.isDeleting = true;
                        vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Phase")), () => {
                            var obj = {
                                ProjectId: vm.projectId,
                                PhaseIds: data.id
                            };
                            var objectPostString = JSON.stringify(obj)
                            DataService.DeletePhase(objectPostString).then(function (response) {
                                if (response.data.result.DATA[0].VALUE == 'SUCCESS') {
                                    vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Phase')]), "success", true, vm.$t("Alert"));
                                    vm.FetchProjectPhaseList();
                                }
                                else {
                                    vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Phase')]), "failure", true, vm.$t("Alert"));
                                }
                                vm.isDeleting = false;
                            }).catch(() => {
                                vm.isDeleting = false;
                            });
                        }, () => {
                            vm.isDeleting = false;
                        });
                    } else {
                        vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                    }
                });
            }
            else if (data.type == 'stage') {
                var url = `controller=Stage&action=Delete`;
                await DataService.CheckPrivilege(url).then(async function (response) {
                    if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                        vm.isDeleting = true;
                        vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Stage")), () => {
                            var obj = {
                                ProjectId: vm.projectId,
                                StageIds: data.id
                            };
                            var objectPostString = JSON.stringify(obj)
                            DataService.DeleteStage(objectPostString).then(function (response) {
                                if (response.data.result.DATA[0].VALUE == 'SUCCESS') {
                                    vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Stage')]), "success", true, vm.$t("Alert"));
                                    vm.FetchProjectStageListing();
                                }
                                else {
                                    vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Stage')]), "failure", true, vm.$t("Alert"));
                                }
                                vm.isDeleting = false;
                            }).catch(() => {
                                vm.isDeleting = false;
                            });
                        }, () => {
                            vm.isDeleting = false;
                        });
                    } else {
                        vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                    }
                }).catch(() => {
                    vm.isDeleting = false;
                });
            }
            else if (data.type == 'Sprint') {
                var url = 'controller=Project&action=DeleteSprint';
                try {
                    const response = await DataService.CheckPrivilege(url);

                    if (response.data || vm.checkPmUser || vm.ProjectOwner) {

                        vm.isDeleting = true;

                        vm.confirmR(
                            vm.$t("ConfirmDelete"),
                            true,
                            vm.$t("Delete") + " " + vm.$t("Group"),
                            function () {

                                var postJSON = {
                                    ids: data.id,
                                    moduleName: "PROJECT",
                                    refCode: "TALYGEN_sprint"
                                };

                                var objectPostString = JSON.stringify(postJSON);

                                DataService.CommonCommonDelete(objectPostString)
                                    .then(function (response) {
                                        vm.isLoading = false;

                                        if (response.status == 200) {
                                            vm.ShowAlert(
                                                vm.$t('DeletedSuccess', [vm.$t(vm.NewTabName)]),
                                                "success",
                                                true,
                                                vm.$t("Alert")
                                            );
                                            vm.FetchProjectStageListing();
                                        } else {
                                            vm.ShowAlert(
                                                vm.$t('DeletedError', [vm.$t(vm.NewTabName)]),
                                                "warning",
                                                true,
                                                vm.$t("Alert")
                                            );
                                        }
                                    });

                            }
                        );

                    } else {
                        vm.ShowAlert(vm.$t("Selectanyrecordtodelete"));
                    }

                } catch (error) {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            }
