        async handleView(data) {
            if (this.isViewing) {
                return;
            }
            var vm = this;
            this.isViewing = true;
            try {
                if (data.type == 'epic') {
                    this.IsAddEditEpic = true;
                    this.EpicDeatils = data;
                    setTimeout(() => {
                        $("#modalEditTask").modal("show");
                        vm.isViewing = false;
                    }, 1000);
                }
                else if (data.type == 'task' || data.type == 'story') {
                    var url = `id=${data.id}`;
                    await DataService.GetEpicStoryTaskDetails(url).then(response => {
                        if (response.data.result.Data.length > 0) {
                            vm.IsAddEditEpic = false;
                            vm.taskDetail = response.data.result.Data[0];
                            vm.taskDetail.child = [];
                            vm.IsEditTask = true;
                            setTimeout(() => {
                                $("#modalEditTask").modal("show");
                                vm.isViewing = false;
                            }, 1000);
                        }
                        else {
                            vm.isViewing = false;
                        }
                    }).catch((error) => {
                        console.error('Error fetching task details:', error);
                        vm.isViewing = false;
                    });
                }
                else if (data.type === 'phase') {
                    this.EditPhaseId = data.id;
                    this.PhaseAssociate = true;
                    this.reloadkey++;
                }
                else if (data.type === 'stage') {
                    this.EditStageId = data.id;
                    this.IsAddAssociateStage = true;
                }
                else if (data.type === 'milestone') {
                    this.MileStoneId = data.id;
                    this.MilestoneListingSchema = true;
                    this.reloadkey++;
                }
                else {
                    this.isViewing = false;
                }
            } catch (error) {
                console.error('Error in handleView:', error);
                this.isViewing = false;
            }
        },
        ReloadTimeline(updatedtaskdata = null) {
    if (!updatedtaskdata) return;
    const id = updatedtaskdata.TaskId || updatedtaskdata.EpicId || updatedtaskdata.milestoneId || updatedtaskdata.SprintId;
    const index = this.tasks.findIndex(t => t.id === id);
    if (index >= 0) {
        const task = this.tasks[index];
        Object.assign(task, {
            label: `<a style="color:#0077c0;"> ${updatedtaskdata.TaskName || updatedtaskdata.EpicTitle || updatedtaskdata.MilestoneName || updatedtaskdata.SprintName}</a>`,
            user: updatedtaskdata.UserId || task.user || null,
            start: updatedtaskdata.StartDate || updatedtaskdata.EpicStart || updatedtaskdata.dueDate || task.start,
            end: updatedtaskdata.EndDate || updatedtaskdata.EpicEnd || updatedtaskdata.dateRecieved || task.end,
            status: updatedtaskdata.StatusId || updatedtaskdata.status || task.status,
            descripton: (updatedtaskdata.BackLogDescription || updatedtaskdata.EpicDescription || updatedtaskdata.MilestoneDescription || updatedtaskdata.SprintDescription || task.descripton || '').replace(/<[^>]*>/g, '').trim(),
            name: updatedtaskdata.TaskName || updatedtaskdata.EpicTitle || updatedtaskdata.MilestoneName || updatedtaskdata.SprintName,
        });
    } else {
        this.tasks.push({
            id: id,
            label: `<a style="color:#0077c0;"> ${updatedtaskdata.TaskName || updatedtaskdata.EpicTitle || updatedtaskdata.MilestoneName || updatedtaskdata.SprintName}</a>`,
            user: updatedtaskdata.UserId || null,
            start: updatedtaskdata.StartDate || updatedtaskdata.EpicStart || updatedtaskdata.dueDate,
            end: updatedtaskdata.EndDate || updatedtaskdata.EpicEnd || updatedtaskdata.dateRecieved,
            duration: 0,
            percent: 0,
            type: 'task',
            icon: null,
            collapsed: 1,
            status: updatedtaskdata.StatusId || updatedtaskdata.status,
            descripton: (updatedtaskdata.BackLogDescription || updatedtaskdata.EpicDescription || updatedtaskdata.MilestoneDescription || updatedtaskdata.SprintDescription || '').replace(/<[^>]*>/g, '').trim(),
            name: updatedtaskdata.TaskName || updatedtaskdata.EpicTitle || updatedtaskdata.MilestoneName || updatedtaskdata.SprintName,
        });
       }
       this.reloadkey++;
        },
        handleCloseModal() {
            this.IsAddEditEpic = false;
            this.IsEditTask = false;
            this.EpicDeatils = null;
            this.taskDetail = null;
            this.MilestoneListingSchema = false;
        },
        FetchProjectStageListing() { this.reloadkey++; this.GetEpicDeatils(0) },
        FetchProjectPhaseList() { this.reloadkey++; this.GetEpicDeatils(0) },
