        async OpenAddEditEpic(data) {
            if (data.type == 'epic') {
                this.IsAddEditEpic = true;
                setTimeout(function () {
                    $("#modalEditTask").modal("show");
                }, 1000);
                this.EpicDeatils = data;
            }
            else if (data.type == 'task' || data.type == 'story') {
                var url = `id=${data.id}`;
                await DataService.GetEpicStoryTaskDetails(url).then(response => {
                    if (response.data.result.Data.length > 0) {
                        this.IsAddEditEpic = false;
                        this.taskDetail = response.data.result.Data[0];
