        SaveEpic() {
            var ths = this
            if (ths.txtEpicTitle.trim())
                try {
                    ths.isLoading = true;
                    var obj = {
                        EpicId: 0,
                        Project_id: ths.$route.params.projectId,
                        EpicTitle: ths.txtEpicTitle,
                        EpicDescription: ths.txtEpicDescription,
                        StatusId: 1001
                    }
                    DataService.SaveEpic(JSON.stringify(obj)).then(response => {
                        ths.isLoading = false;
                        if (response.data.result.DATA.length > 0) {
                            this.tasks = [];
                            this.EpicData = [];
                            if (response.data.result.DATA[0].VALUE == 'UPDATE') {
                                ths.ShowAlert(ths.$t('UpdatedSuccess', [ths.$t('Epic')]), "success", true, ths.$t("Alert"));
                            }
                            else if (response.data.result.DATA[0].VALUE == 'EXIST') {
                                ths.ShowAlert(ths.$t('AlreadyExists', [ths.$t('Epic')]), "failure", true, ths.$t("Alert"));
                            }
                            else {
                                ths.ShowAlert(ths.$t('AddedSuccess', [ths.$t('Epic')]), "success", true, ths.$t("Alert"));
