        handleTaskUpdated: async function (updatedTask) {
            
            const taskIndex = this.tasks.findIndex(task => task.id === updatedTask.id);
            if (taskIndex !== -1) {
                this.tasks[taskIndex].start = new Date(updatedTask.startTime);
                this.tasks[taskIndex].end = new Date(updatedTask.endTime);
                this.tasks[taskIndex].duration = updatedTask.duration;
            }
            const details = this.tasks.find(task => task.id == updatedTask.id);
            let obj = {
                type: details.type,
                id: details.id,
                start: new Date(updatedTask.startTime),
                end: new Date(updatedTask.endTime),
                duration: updatedTask.duration,
                projectId:this.$route.params.projectId
            }
            try {
                let response = DataService.UpdatedurationCommon(JSON.stringify(obj));
                if (response) {
                    // this.GetEpicDeatils(1);
                }

            } catch (error) {
                console.error('Error updating task:', error);
            }
