

<template>
    <section>
        <loader :is-visible="isLoading"></loader>
        <full-calendar ref="calendar" :options="calendarOptions" />
    </section>
</template>

<script>
import FullCalendar from '@fullcalendar/vue'
import dayGridPlugin from '@fullcalendar/daygrid'
import interactionPlugin from '@fullcalendar/interaction'
import DataService from '../../../../services/DataService.js';

export default {
    components: {
        FullCalendar
    },
    data() {
        return {
            ProjectId: 0,
            ListingData: [],
            PageSize: 100000,
            PageNumber: 1,
            SortBy: '',
            SortExp: '',
            tasks: [],
            milestoneData: [],
            phaseData: [],
            stageData: [],
            selectedTask: null,
            currentPopover: null,
            topdata: [
                {
                    label: 'Milestone',
                    class: 'legend-milestone'
                },
                {
                    label: 'Stage',
                    class: 'bg-stage'
                },
                {
                    label: 'Phase',
                    class: 'bg-info'
                }
            ],
            calendarOptions: {
                plugins: [dayGridPlugin, interactionPlugin],
                initialView: 'dayGridMonth',
                events: [],
                editable: true,
                droppable: true,
                eventResizableFromStart: true,
                eventClick: this.onEventClick,
                eventMouseEnter: this.onEventMouseEnter,
                eventMouseLeave: this.onEventMouseLeave,
                eventDrop: this.onEventDrop,
                eventResize: this.onEventResize
            },
            isLoading: false
        }
    },
    mounted() {
        this.fetchTasks();
    },
    methods: {
        fetchTasks() {
            
            var ths = this;
            var url = 'controller=Project&action=ProjectCalendar';
        DataService.CheckPrivilege(url).then(async function (response) {
            if (response.data) {
            ths.ProjectId = parseInt(ths.$route.params.projectId);
                    
             var params = `ProjectId=${ths.ProjectId}&name=&priority=&SprintId=&Type=Calendar&BugType=&StatusId=&Assignee=&sortBy=${ths.SortBy}&sortExp=${ths.SortExp}&pageSize=${ths.PageSize}&pageNumber=${ths.PageNumber}&userType=`;
                         
            //var params = `ProjectId=${ths.ProjectId}&SprintId=&Type=Calendar&BugType=&StatusId=0&Assignee=0&sortBy=${ths.SortBy}&sortExp=${ths.SortExp}&pageSize=${ths.PageSize}&pageNumber=${ths.PageNumber}`;
            DataService.GetChildSprint(params).then(function (response) {
                if (response.data.result != null) {
                    ths.tasks = [];
                    var updateArray = response.data.result.Data;
                    ths.milestoneData = response.data.result.MilstoneData;
                    ths.phaseData = response.data.result.PhaseData;
                    ths.stageData = response.data.result.StageData
                    ths.ListingData = updateArray;
                    if (ths.ListingData.length > 0) {
                        ths.ListingData.forEach(itm => {
                            let obj = {
                                id: itm.task_id,
                                type: 'Task',
                                name: itm.task_name,
                                dateFrom: ths.$options.filters.formatDateYMD(itm.planned_start_date),
                                dateTo: ths.$options.filters.formatDateYMD(itm.planned_end_date),
                                color: '#83baec',
                                description: itm.task_description || 'N/A',
                            }
                            ths.tasks.push(obj);
                        });
                    }
                    if (ths.phaseData.length > 0) {
                        ths.phaseData.forEach(itm => {
                            let obj = {
                                id: itm.phase_id,
                                type: 'Phase',
                                name: itm.phase_name,
                                dateFrom: ths.$options.filters.formatDateYMD(itm.start_date),
                                dateTo: ths.$options.filters.formatDateYMD(itm.end_date),
                                color: '#17a2b8',
                                description: itm.phase_desc || 'N/A',
                            }
                            ths.tasks.push(obj);
                        });
                    }
                    if (ths.stageData.length > 0) {
                        ths.stageData.forEach(itm => {
                            let obj = {
                                id: itm.stage_id,
                                type: 'Stage',
                                name: itm.stage_name,
                                dateFrom: ths.$options.filters.formatDateYMD(itm.start_date),
                                dateTo: ths.$options.filters.formatDateYMD(itm.end_date),
                                color: '#CC9752',
                                description: itm.stage_desc || 'N/A',
                            }
                            ths.tasks.push(obj);
                        });
                    }
                    if (ths.milestoneData.length > 0) {
                        ths.milestoneData.forEach(itm => {
                            let obj = {
                                id: itm.milestone_id,
                                type: 'MileStone',
                                name: itm.milestone_name,
                                dateFrom: ths.$options.filters.formatDateYMD(itm.due_date),
                                dateTo: ths.$options.filters.formatDateYMD(itm.date_received),
                                color: '#ff8c3b',
                                description: itm.milestone_desc || 'N/A',
                            }
                            ths.tasks.push(obj);
                        });
                    }
                    ths.updateCalendarEvents();
                }

            });
        } else {
                ths.ShowAlert(ths.$t('NotAuthorizedSection'), "failure", true, "Alert");
            }
        });
        },
        getRandomHexColor() {
            const timestamp = new Date().getTime();
            const randomValue = Math.floor(Math.random() * 16777215);
            const uniqueHexColor = '#' + ((timestamp + randomValue) & 0xFFFFFF).toString(16).padStart(6, '0');
            return uniqueHexColor;
        },
        onEventMouseLeave(info) {
            if (this.currentPopover) {
                $(this.currentPopover).popover('hide');
                this.currentPopover = null;
            }
        },
        updateCalendarEvents() {
            const calendarApi = this.$refs.calendar.getApi();
            calendarApi.removeAllEvents();
            this.tasks.forEach(task => {
                calendarApi.addEvent({
                    id: task.id != null ? String(task.id) : undefined,
                    textColor: task.type,
                    title: task.name,
                    start: task.dateFrom,
                    end: this.addOneDay(task.dateTo),
                    color: task.color,
                    extendedProps: {
                        type: task.type
                    }
                });
            });
        },
        onEventClick(info) {
            this.selectedTask = info.event;
            this.showPopover(info);
        },
        addOneDay(dateStr) {
            const date = new Date(dateStr);
            date.setDate(date.getDate() + 1);
            return date.toISOString().split('T')[0];
        },
        showPopover(info) {
            
            const taskDetails = `
                <strong>Type:</strong> ${info.event.textColor} <br>
                <strong>Name:</strong> ${info.event.title} <br>
                <strong>Start:</strong> ${info.event.startStr} <br>
                <strong>End:</strong> ${info.event.endStr} <br>
                <strong>Description:</strong> ${info.event.extendedProps.description}`;
            this.currentPopover = info.el;
            $(info.el).popover({
                content: taskDetails,
                html: true,
                placement: 'top',
                trigger: 'focus'
            }).popover('show');
        },
        closePopover() {
            this.selectedTask = null;
            if (this.currentPopover) {
                $(this.currentPopover).popover('hide');
                this.currentPopover = null;
            }
        },
        formatLocalDate(date) {
            if (!date) return null;
            const d = new Date(date);
            const now = new Date();
            d.setHours(now.getHours(), now.getMinutes(), now.getSeconds(), now.getMilliseconds());
            const year = d.getFullYear();
            const month = String(d.getMonth() + 1).padStart(2, '0');
            const day = String(d.getDate()).padStart(2, '0');
            const hours = String(d.getHours()).padStart(2, '0');
            const minutes = String(d.getMinutes()).padStart(2, '0');
            const seconds = String(d.getSeconds()).padStart(2, '0');
            return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}`;
        },
        onEventDrop(info) {
            

            var vm = this;
            vm.isLoading = true;

            const startDate = info.event.start;
            let endDate = info.event.end ? new Date(info.event.end.getTime() - 24 * 60 * 60 * 1000) : null; // Adjust for inclusive end

            // For milestones, if end is null, set it to start date (single day event)
            if ((info.event.extendedProps && info.event.extendedProps.type === 'MileStone') && !endDate) {
                endDate = new Date(startDate);
            }

            const updatedData = {
                id: info.event.id,
                type: info.event.extendedProps && info.event.extendedProps.type ? info.event.extendedProps.type : null,
                start: this.formatLocalDate(startDate),
                end: this.formatLocalDate(endDate),
                projectid: parseInt(this.$route.params.projectId)
            };

            var objectPostString = JSON.stringify(updatedData);
            DataService.updateEvent(objectPostString).then(response => {
                if (response.data != null) {
                    vm.isLoading = false;
                    vm.fetchTasks();
                }
                else {

                }


            }).catch(error => {
                console.error('Failed to update event');

            });
        },
        onEventResize(info) {
            
            // Handle event resize
            var vm = this;
            vm.isLoading = true;
            const startDate = info.event.start;
            const endDate = info.event.end ? new Date(info.event.end.getTime() - 24 * 60 * 60 * 1000) : null; // Adjust for inclusive end

            const updatedData = {
                id: info.event.id,
                type: info.event.extendedProps && info.event.extendedProps.type ? info.event.extendedProps.type : null,
                start: this.formatLocalDate(startDate),
                end: this.formatLocalDate(endDate),
                projectid: parseInt(this.$route.params.projectId)
            };

            var objectPostString = JSON.stringify(updatedData);
            DataService.updateEvent(objectPostString).then(response => {
                if (response.data != null) {
                    vm.isLoading = false;
                    vm.fetchTasks();
                }
                else {

                }


            }).catch(error => {
                console.error('Failed to update event');

            });
        }
    }
}
</script>
<style>
@import '~@fullcalendar/common/main.css';
@import '~@fullcalendar/daygrid/main.css';

.task-details {
    margin-top: 20px;
    padding: 15px;
    border: 1px solid #ccc;
    background: #f9f9f9;
    max-width: 300px;
}

.fc-theme-standard th {
    background: #2c3e50;
    line-height: 40px;
}

.fc-theme-standard th a {
    color: #fff;
}
</style>