                <span class="cd-panel-title mcc-chart-title">Campaign Timeline — Phase Progress</span>
                                    </div>
              <div class="section-body border py-2 mcc-chart-body">
                <VueApexCharts
                  v-if="hasPhaseChart"
                  type="bar"
