                                </div>
          <div class="col-lg-4 mb-3 px-2 section_pp d-flex">
            <div class="section h-100 w-100 mcc-chart-section">
              <div class="section-header reddy cd-panel-head mcc-chart-panel-head">
                <span class="cd-panel-title mcc-chart-title">Budget Utilization</span>
                            </div>
              <div class="section-body border py-2 mcc-chart-body mc-donut-wrap">
                <VueApexCharts
                  v-if="hasBudgetDonut"
                  type="donut"
                  height="300"
                  :options="budgetDonutOptions"
                  :series="budgetDonutSeries"
                  :key="'mc-bd-' + chartKey"
                />
                <div v-else class="mcc-no-chart">{{ $t('NoRecordfound') }}</div>
                <div v-if="hasBudgetDonut" class="mc-donut-foot text-center">
                  <div class="mc-donut-pct">{{ budgetUtilizedPct }}%</div>
                  <div class="mc-donut-sub">of {{ totalBudgetLabel }} utilized</div>
                                </div>
                                </div>
                            </div>
                        </div>
                    </div>

        <div class="row mx-0">
          <div class="col-12 px-2 section_pp">
            <div class="section mc-deliverables-section">
              <div class="section-header reddy cd-panel-head mcc-od-head">
                <span class="cd-panel-title mcc-od-title-wrap">
                  <em class="fa fa-calendar mc-dl-icon" aria-hidden="true"></em>
                  <span class="mc-dl-title-main">Upcoming Deliverable Deadlines</span>
                                    </span>
                <small class="cd-panel-actions">
                  <a href="javascript:;" class="mc-view-all-link font-13" @click="openDashboardAddView">
                    <em class="fa fa-eye mr-1"></em>{{ $t('View All') }}
                  </a>
                </small>
                                </div>
              <div class="section-body border p-0">
                <div class="table-responsive mcc-od-wrap">
                  <table class="table mb-0 mcc-od-table">
                    <thead>
                      <tr>
                        <th>Deliverable</th>
                        <th>Owner</th>
                        <th>Due date</th>
                        <th>Stage</th>
                        <th>Status</th>
                        <th>Priority</th>
                                </tr>
                            </thead>
                            <tbody>
                      <tr v-for="(row, idx) in deliverableRows" :key="'dl-' + idx">
                        <td class="mcc-od-title" :title="row.deliverable">{{ truncate(row.deliverable, 48) }}</td>
                        <td :title="row.owner">{{ row.owner || '—' }}</td>
                        <td :title="formatCellDate(row.dueDate)">{{ formatCellDate(row.dueDate) }}</td>
                        <td :title="row.stage">{{ row.stage || '—' }}</td>
                        <td :title="row.status">
                          <span class="mc-status-pill  text-white" :style="{backgroundColor:row.status_color}">{{ row.status || '—' }}</span>
                                    </td>
                                    <td :title="row.priority_name">
                                      <span class="mc-status-pill text-white" :style="{ backgroundColor: row.priority_color }">{{ row.priority_name || '—' }}</span>
                                    </td>
                                </tr>
                      <tr v-if="!deliverableRows.length">
                        <td colspan="6" class="text-center text-danger py-4">{{ $t('NoRecordfound') }}</td>
