</template>

<script>
import CommonDashboard from '../CommonDashboard.vue';
import VueApexCharts from 'vue-apexcharts';
import DataService from '../../../../../../services/DataService';
import CriticalandBlockerDetail from '../../../../../../components/Modal/CriticalandBlockerDetail.vue';
function n(v, fallback = 0) {
  const x = Number(v);
  return Number.isFinite(x) ? x : fallback;
}

/** Optional API: CAMPAIGN_DASHBOARD = { kpis, phase_progress[], budget_breakdown[], total_budget, utilized_pct, upcoming_deliverables[] } */

const DEFAULT_PHASES = [
];

const PHASE_BAR_COLORS = ['#34a853', '#34a853', '#1a73e8', '#f9ab00', '#dadce0', '#dadce0'];

const DEFAULT_DELIVERABLES = [
];

export default {
  name: 'ProjectMarketingCampaginOverView',
  components: { CommonDashboard, VueApexCharts,CriticalandBlockerDetail },
    props: {
    projectId: { type: Number, required: true },
    checkPmUser: { type: Boolean, required: true },
    NewTabName: { type: String, required: true },
    TabsArray: { type: Array, default: () => [] },
    Template_Name: { type: String, required: true },
    ProjectOwner:{type: Boolean, required: true},
    },
    data() {
        return {
          isCriticalandBlockerDetail:false,
            chartKey: 0,
      kpiCards: [],
      hasPhaseChart: false,
      phaseChartSeries: [],
      phaseChartOptions: {
        chart: { type: 'bar', toolbar: { show: false }, fontFamily: 'inherit' },
                plotOptions: {
                    bar: {
                        horizontal: true,
            barHeight: '72%',
                        borderRadius: 4,
            distributed: true,
            dataLabels: { position: 'center' },
          },
                },
                dataLabels: {
          enabled: true,
          formatter: (val) => `${n(val, 0)}%`,
          style: { fontSize: '11px', fontWeight: 600, colors: ['#fff'] },
          dropShadow: { enabled: false },
        },
        colors: [...PHASE_BAR_COLORS],
        xaxis: { max: 100, tickAmount: 5, labels: { style: { fontSize: '11px' } } },
        yaxis: { labels: { style: { fontSize: '11px' } } },
        grid: { strokeDashArray: 4, borderColor: '#e8eaed' },
        legend: { show: false },
        tooltip: { y: { formatter: (val) => `${val}%` } },
      },
      hasBudgetDonut: false,
      budgetDonutSeries: [],
      budgetDonutOptions: {
        chart: { type: 'donut', toolbar: { show: false }, fontFamily: 'inherit' },
                labels: [],
        colors: ['#1a73e8', '#34a853', '#f9ab00', '#ec4899', '#9aa0a6'],
        dataLabels: { enabled: false },
        legend: { position: 'bottom', fontSize: '12px', fontWeight: 600 },
        plotOptions: {
          pie: {
            donut: {
              size: '68%',
              labels: { show: false },
            },
          },
        },
      },
      budgetUtilizedPct: 68,
      totalBudgetLabel: '$120k',
      deliverableRows: [],
      BacklogId: null,
      AssigenedUser: null,
      IsAssignedUser: false,
    };
  },
  computed: {
    templateTag() {
      return (this.Template_Name || 'CAMPAIGN').toString().toUpperCase();
    },
  },
  watch: {
    projectId() {
      this.loadChartData();
    },
  },
  mounted() {
    this.loadChartData();
  },
  methods: {
    openDashboardAddView() {
     this.isCriticalandBlockerDetail=true;
    },
    truncate(str, len) {
      if (str == null || str === '') return '—';
      const s = String(str);
      return s.length > len ? `${s.slice(0, len - 1)}…` : s;
    },
    statusPillClass(status) {
      const s = String(status || '').toLowerCase();
      if (s.includes('pending') || s.includes('approval')) return 'mc-status-pill--pending';
      if (s.includes('progress')) return 'mc-status-pill--progress';
      if (s.includes('approved')) return 'mc-status-pill--approved';
      if (s.includes('review')) return 'mc-status-pill--review';
      return 'mc-status-pill--neutral';
    },
    loadChartData() {
      const params = `ProjectId=${this.projectId}`;
      DataService.GetChartBugProject(params)
        .then((response) => {
          const res = response.data && response.data.result;
          if (!res) {
            this.applyCampaignPayload({});
            return;
          }
          this.applyCampaignPayload(res);
          this.$nextTick(() => {
            this.chartKey += 1;
          });
        })
        .catch((e) => {
          console.error('Marketing campaign overview load:', e);
          this.applyCampaignPayload({});
        });
    },
    applyCampaignPayload(res) {
      const cd = res.CAMPAIGN_DASHBOARD || res.campaign_dashboard || {};

      this.bindKpis(cd, res);
      this.bindPhaseChart(cd, res);
      this.bindBudgetDonut(cd, res);
      this.bindDeliverables(cd, res);
    },
    bindKpis(cd, res) {
      const k = cd.kpis || cd.kpi || {};
      let budget = k.budget_utilized != null ? k.budget_utilized : cd.budget_utilized;
      if (budget == null && Array.isArray(res.EXPENSEDATA) && res.EXPENSEDATA.length) {
        const used = res.EXPENSEDATA.reduce((a, x) => a + n(x.USED_AMOUNT, 0), 0);
        budget = used >= 1000 ? `$${Math.round(used / 1000)}k` : `$${Math.round(used)}`;
      }
      if (budget == null) budget = '$82k';

      let done = k.deliverables_done != null ? k.deliverables_done : cd.deliverables_done;
      if (done == null) {
        const st = Array.isArray(res.TASKSTATUSDATA) ? res.TASKSTATUSDATA : [];
        const doneRow = st.find((x) => String(x.component_name || '').toLowerCase().includes('done') || String(x.component_name || '').toLowerCase().includes('complete'));
        done = doneRow ? n(doneRow.total_count, 18) : 18;
      }
      done = n(done, 18);

      let awaiting = k.awaiting_approval != null ? k.awaiting_approval : cd.awaiting_approval;
      if (awaiting == null) {
        const st = Array.isArray(res.STATUSDATA) ? res.STATUSDATA : [];
        const rev = st.find((x) => String(x.status_name || '').toLowerCase().includes('review') || String(x.status_name || '').toLowerCase().includes('pending'));
        awaiting = rev ? n(rev.total_count, 4) : 4;
      }
      awaiting = n(awaiting, 4);

      let launch = k.launch_date != null ? String(k.launch_date) : cd.launch_date;
      if (!launch) {
        launch = 'Apr 20';
      }

      this.kpiCards = [
        { label: 'Budget utilized', value: budget, tint: 'orange' },
        { label: 'Deliverables done', value: done, tint: 'blue' },
        { label: 'Awaiting approval', value: awaiting, tint: 'purple' },
        { label: 'Launch date', value: launch, tint: 'green' },
      ];
    },
    bindPhaseChart(cd, res) {
      let rows = res.PHASEDATA ||  res.PHASEDATA;
      if (!Array.isArray(rows) || !rows.length) {
        rows = [];
      }
      const categories = rows.map((r) => r.label || r.PHASE_NAME || r.phase || 'Phase');
      const data = rows.map((r) => n(r.pct ?? r.phase_progress ?? r.value, 0));
      const colors = rows.map((_, i) => PHASE_BAR_COLORS[i % PHASE_BAR_COLORS.length]);
      this.hasPhaseChart = categories.length > 0;
      this.phaseChartSeries = [{ name: 'Progress', data }];
      this.phaseChartOptions = {
        ...this.phaseChartOptions,
        colors,
        xaxis: { ...this.phaseChartOptions.xaxis, max: 100, categories },
      };
    },
    bindBudgetDonut(cd, res) {
    let breakdown = cd.budget_breakdown || cd.budget_utilization;
    let labels = [];
    let series = [];
    let totalUsedAmount = 0;
    let totalBudgetAmount = 0;
  
    
    if (Array.isArray(breakdown) && breakdown.length) {
        labels = breakdown.map((x) => x.label || x.name || x.channel || 'Item');
        series = breakdown.map((x) => n(x.value ?? x.amount ?? x.count, 0));
    } 
    else if (Array.isArray(res.EXPENSEDATA) && res.EXPENSEDATA.length) {
        labels = res.EXPENSEDATA.map((x) => x.CATEGORY_NAME || 'Category');
        series = res.EXPENSEDATA.map((x) => n(x.CATEGORY_TOTAL_AMOUNT, 0) || n(x.CATEGORY_TOTAL_AMOUNT, 0));
        totalUsedAmount = res.EXPENSEDATA.reduce((acc, x) => acc + n(x.USED_AMOUNT, 0), 0);
        totalBudgetAmount = res.EXPENSEDATA.reduce((acc, x) => acc + n(x.CATEGORY_TOTAL_AMOUNT, 0), 0);
    }
    if (!series.length || series.every((v) => v === 0)) {
        return;
    }
    let pct = 0;
    if (totalBudgetAmount > 0) {
        pct = Math.round((totalUsedAmount / totalBudgetAmount) * 100);
    }
    this.budgetUtilizedPct = Number.isFinite(pct) ? pct : 0;
    let tb = cd.total_budget_label || cd.total_budget;
    if (tb == null && Array.isArray(res.EXPENSEDATA) && res.EXPENSEDATA.length) {
        const totalBudget = res.EXPENSEDATA.reduce((acc, x) => acc + n(x.CATEGORY_TOTAL_AMOUNT, 0), 0);
        tb = totalBudget >= 1000 ? `$${(totalBudget / 1000)}k` : `$${totalBudget}`;
    }
    this.totalBudgetLabel = tb != null ? String(tb) : '$120k';
    this.hasBudgetDonut = labels.length > 0;
    this.budgetDonutSeries = series;
    this.budgetDonutOptions = {
        ...this.budgetDonutOptions,
        labels,
        colors: this.budgetDonutOptions.colors.slice(0, labels.length).concat(
          Array(Math.max(0, labels.length - this.budgetDonutOptions.colors.length)).fill('#9aa0a6'),
        ),
    };
},
    bindDeliverables(cd, res) {
      let rows = cd.upcoming_deliverables || cd.deliverables;
      if (Array.isArray(rows) && rows.length) {
        this.deliverableRows = rows.map((r) => ({
          deliverable: r.deliverable || r.name || r.title || '—',
          channel: r.channel || r.medium || '—',
          owner: r.owner || r.owner_name || r.Owner || '—',
          dueDate: r.due_date || r.dueDate || r.planned_end_date,
          stage: r.stage || r.current_stage || '—',
          status: r.status || r.status_name || '—',
        }));
        return;
      }
      const bugs = Array.isArray(res.CRITICALBLOCKERBUGS) ? res.CRITICALBLOCKERBUGS : [];
      if (bugs.length) {
        this.deliverableRows = bugs.slice(0, 12).map((item) => ({
          deliverable: [item.task_number, item.task_name].filter(Boolean).join(' ') || '—',
          channel: item.Component || item.Environment || '—',
          owner: item.Created_by || '—',
          dueDate: item.planned_end_date,
          stage: item.stage_name || '—',
          status: item.status_name || '—',
          status_color: item.status_bg_color || '—',
          priority_name:item.priority_name || '--',
           priority_color:item.color_code || '--'
        }));
        return;
      }
      const base = DEFAULT_DELIVERABLES.map((r) => ({ ...r }));
      const offsets = [0, 3, 7, 12];
      const now = new Date();
      base.forEach((r, i) => {
        const d = new Date(now);
        d.setDate(d.getDate() + (offsets[i] || 5));
        r.dueDate = d.toISOString();
      });
      this.deliverableRows = base;
    },
    AssignedUser(val, users) {
      this.BacklogId = val;
      this.AssigenedUser = users;
      this.IsAssignedUser = true;
    },
    formatCellDate(val) {
      if (!val) return '—';
      const f = this.$options.filters && this.$options.filters.formatDate;
      if (typeof f === 'function') return f(val);
      try {
        const d = val instanceof Date ? val : new Date(val);
        if (Number.isNaN(d.getTime())) return '—';
        const mm = String(d.getMonth() + 1).padStart(2, '0');
        const dd = String(d.getDate()).padStart(2, '0');
        const yy = d.getFullYear();
        return `${mm}/${dd}/${yy}`;
      } catch (e) {
        return '—';
      }
    },
  },
};
</script>

