<template>
  <section>
    <div class="row m-0">
      <div class="heading-border"><h5 class="h5"><span>{{ $t('Customer') }} {{ $t('Queries') }}</span></h5></div>
      <div class="listing mt-2">
        <div class="table-responsive">
          <table class="table table-bordered mt-0 w-100">
            <thead class="thead-bg">
              <tr><th>{{ $t('Contact') }} {{ $t('Name') }}</th><th>{{ $t('Email') }}</th><th>{{ $t('Message') }}</th><th>{{ $t('CreatedDate') }}</th></tr>
            </thead>
            <tbody>
              <tr v-if="!list || list.length === 0"><td colspan="4" class="text-center"><span class="text-danger no-record">{{ $t('NoRecordfound') }}</span></td></tr>
              <tr v-for="(item, i) in list" :key="i">
                <td>{{ item.NAME || item.name }}</td>
                <td>{{ item.EMAIL_ADDRESS || item.email }}</td>
                <td>{{ item.MESSAGE || item.message }}</td>
                <td>{{ item.CREATED_AT || item.createdAt }}</td>
              </tr>
            </tbody>
          </table>
        </div>
        <div class="col-12 float-left p-0">
          <Pager :numberofrecords="TotalRecords" :callbackfunction="() => {}" :prev-text="$t('Prev')" :first-text="$t('First')" :last-text="$t('Last')" :next-text="$t('Next')" @SetCurrentPage="onPagerPageChange" />
        </div>
      </div>
    </div>
  </section>
</template>

<script>
import DataService from '@/services/DataService';
import Pager from '@/components/Common/Pager.vue';

export default {
  name: 'ContactOrganizerPortion',
  components: { Pager },
  props: { eventId: { type: [Number, String], required: true } },
  data() { return { list: [], TotalRecords: 0, PageSize: 10, PageNumber: 1 }; },
  created() { this.fetch(); },
  methods: {
    async fetch() {
      try {
        const res = await DataService.GetContactOrganizerByEventId(`eventId=${this.eventId}&pagesize=${this.PageSize}&pagenumber=${this.PageNumber}`);
        this.list = (res.data && res.data.result && res.data.result.data) ? res.data.result.data : (res.data && res.data.result) ? (Array.isArray(res.data.result) ? res.data.result : []) : [];
        this.TotalRecords = (res.data && res.data.result) ? (res.data.result.totalRecords || this.list.length) : 0;
      } catch (_) { this.list = []; this.TotalRecords = 0; }
    },
    onPagerPageChange(p) { if (p) { this.PageNumber = p.PageNumber; this.PageSize = p.PageSize; } this.fetch(); }
  }
};
</script>
