                            <div class="row flex-row-reverse mt-3">
                                <div class="col-md-12 text-right">
                                    <a href="javascript:;" title="Save" v-on:click="SaveView"
                                        class="submitbtn btn btn-success formbtn detailview mr-2">
                                        <i class="fa fa-save pr-2"></i>{{ $t('Save') }}
                                    </a>
                                    <a href="javascript:;" title="Cancel" v-on:click="CloseAddView"
