<template>
    <section>
        <tg-list :IsShowAction="false" :showCheckBox="true" :listType="['List']" :ModuleName="moduleCode"
            :SubModuleCode="subModuleCode" IdentityColumn="USER_ID" :ListData="ListingData" :HeaderData="Headers"
            :HeaderButtons="listheaderbuttons" :TotalRecords="TotalRecords" :RenderRowActionMethod="renderActions"
            :LegendArray="[]" :HeaderText="HeaderText" :IsSearchFieldsOnTop="false" SearchPosition="top"
            :SearchFields="topsearchField" :ListDataCallBackFunction="GetClientsListing"
            v-on:HeaderButtonClick="commonHeaderButtonClick" v-on:PagerButtonClick="pagerMethod"
            v-on:SortdataButtonClick="sortdata" :widgets="[]" :NorecordfoundText="$t('NoRecordfound')" :key="reloadkey">
            <template v-slot:slotdata="{ data }">
                <template v-if="data.column.COLUMN_NAME == 'CLIENTNAME'">
                    <span :title="data.row.CLIENTNAME"
                        style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ data.row.CLIENTNAME }}</span>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'EMAIL_ID'">
                    <span :title="data.row.CLIENTNAME"
                        style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ data.row.EMAIL_ID }}</span>
                </template>
            </template>
        </tg-list>
        <AddAssociate v-if="IsAssociateShow" :projectId="projectId" :ProjectName="ProjectName"></AddAssociate>
    </section>
</template>

<script>
import Schema from "./ClientSchema";
import DataService from '../../../../services/DataService';
import AddAssociate from '../../../../components/Modal/AddAssociate.vue';
export default {
    components: { AddAssociate },
    props: {
        projectId: {
            type: Number,
            required: true
        },
        projectName: {
            type: String,
            required: true
        },
        checkPmUser: {
            type: Boolean,
            required: true
        },
        ProjectOwner: {
            type: Boolean,
            required: true
        }
    },
    data() {
        return {
            HeaderText: '',
            userId: null,
            companyId: null,
            UserType: null,
            moduleCode: 'PROJECT',
            subModuleCode: 'PROJECT_CLIENTS',
            TotalRecords: 0,
            noRecord: false,
            isLoading: false,
            CompanyId: null,
            PageSize: 10,
            PageNumber: 1,
            reloadkey:0,
            isPaged: 1,
            TotalPages: 0,
            Key: 0,
            SortBy: '',
            SortExp: '',
            Headers: Schema.Headers,
            ListingData: [],
            listheaderbuttons: Schema.buttons,
            IsAssociateShow: false,
            ProjectName: '',
            ClientName: '',
            topsearchField: [
                {
                    fieldName: 'Enter Client Name',
                    fieldType: "text",
                    fieldSearchConditionName: '',
                    isSearch: true,
                    value: "",
                    listOptions: []
                },
            ],
        };
    },
    created: function () {
        var vm = this;
        vm.userId = vm.GetUserInfo.ID;
        vm.companyId = vm.GetUserInfo.CompanyId;
        vm.UserType = vm.GetUserInfo.UserType;
        vm.CheckDisabled();
        vm.GetClientsListing();
    },
    methods: {
        CheckDisabled() {
            const type = this.UserType;
            const hasAccess = this.checkPmUser || this.ProjectOwner;
            const isClient = type === 'CL' || type === 'NU';
            const isAdmin = type === 'CA' || type === 'PM';
            const isAllowed = isAdmin || (isClient && hasAccess);
            const buttons = isAdmin ? [true, true, true] : (isClient && hasAccess) ? [true, true, true] : [false, false, true];
            this.listheaderbuttons.forEach((b, i) => b.isvisible = buttons[i]);
            return isAllowed;
        },
        renderActions() { },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.GetClientsListing();
        },
        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.FetchData();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
        commonHeaderButtonClick: async function (event) {
            switch (event.callbackfunction) {
                case "AddAssociate":
                    this.AddAssociate();
                    break;
                case "BackList":
                    this.BackList();
                    break;
                case "DeleteClientData":
                    this.DeleteClientData();
                    break;
            }
        },
        AddAssociate: async function () {
            var vm = this;
            var url = 'controller=Project&action=AddClientInProject';
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    vm.IsAssociateShow = true;
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, vm.$t("Alert"));
                }
            });

        },
        GetClientsListing: function () {
            var ths = this;
            var url = `projectId=${ths.projectId}&clientName=${ths.ClientName}&sortBy=${ths.SortBy}&sortExp=${ths.SortExp}&pageSize=${ths.PageSize}&pageNum=${ths.PageNumber}`;
            DataService.GetClientsDataDetails(url).then((response) => {
                if (response.data.result.data.length > 0) {
                    ths.ListingData = response.data.result.data;
                    ths.ListingData = response.data.result.data.map(item => ({
                        ...item,
                        CLIENTPHONE: item.CLIENTPHONE || '--',
                        COUNTRYNAME: item.COUNTRYNAME || '--',
                        CITYSTATE: item.CITYSTATE || '--',
                    }));
                    ths.TotalRecords = response.data.result.data[0].TOTALRECORDS;
                    ths.TotalPages = Math.ceil(ths.TotalRecords / ths.PageSize);
                    ths.CurrentPage = ths.PageNumber;
                } else {
                    ths.ListingData = [];
                }
            });
        },

        BackList: function () {
            var vm = this;
            vm.$router.push({ name: 'ProjectList' });
        },
        ResetSchema() { 
            this.SortBy = '';
            this.SortExp = '';
            this.PageNumber = 1;
            this.ClientName = '';
            this.topsearchField.forEach(f => f.value = '');
            this.Headers = JSON.parse(JSON.stringify(Schema.Headers));
            this.listheaderbuttons = JSON.parse(JSON.stringify(Schema.buttons));
            const btn = this.listheaderbuttons.find(b => b.title === 'Delete');
            if (btn) btn.isdisabled = true;            
            this.reloadkey++;
        },
        DeleteClientData: async function () {
            var vm = this;
            var val = "";
            var url = 'controller=Project&action=DeleteClient';
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    vm.isLoading = true;
                    $('.chkItems:checkbox:checked').not("[id^='chkAll']").each(function () {
                        if (val.length > 0)
                            val += ',';
                        val += $(this).val();
                    });                                        
                    if (val != null) {
                        vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Project")), function () {
                            var url = `Ids=${val}&ProjectId=${vm.projectId}`;
                            DataService.DeleteClients(url).then(function (response) {
                                if (response.data != null) {
                                    vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Contract')]), "success", true, vm.$t("Alert"));
                                    vm.GetClientsListing();
                                    vm.ResetSchema();                                    
                                }
                                else {
                                    vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Contract')]), "failure", true, vm.$t("Alert"));
                                }
                            });
                        });
                    }
                    else {
                        vm.ShowAlert(vm.$t("Selectanyrecordtodelete"));
                    }
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, vm.$t("Alert"));
                }
            })
        },
    },

}
</script>