<template>
    <section>
        <loader :is-visible="isLoading"></loader>
        <div  class="ticketsmallfix theme-primary partition p-actions-expand " style="overflow: visible;">
            <span class="p-name text-white">{{ $t("List") }}</span>
            <span  class="p-actions float-right"> 
                <a title="Back To List" @click="BackToList" href="javascript:;" class="p-action-btn text-white float-right">
                    <em  class="fa fa-angle-double-left pr-2"></em> <br ><span >{{$t('BacktoList')}}</span>
                </a>                                                                                   
            </span>                            
        </div>
        <div class="d-flex flex-wrap">
            <div class="col-md-12 p-0">
                <div class="row">
                    <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left">
                        <div class="py-2 d-inline-block">
                            <span class="text-primary fa fa-check-square mr-1" ></span>Task 
                            <span class="text-danger fa fa-warning ml-2 mr-1" ></span>Bug 
                            <span class="text-success fa fa-film text-success ml-2 mr-1"></span>Story 
                        </div>
                        <div class="listing mt-2">                            
                                <div class="table-responsive table-fix-header">
                                    <table id="tblPhase" class="table table-bordered dt-responsive nowrap mt-0 mb-0">
                                        <thead class="thead-bg">
                                            <tr>
                                                <th scope="col" class="border-right-0"></th>
                                                <th style="width:340px;"><span href="javascript:;" >{{$t('Sprint Name')}}</span></th>                        
                                                <th style="width:340px;"><span href="javascript:;" >{{$t('Description')}}</span></th>
                                                <th style="width:340px;"><span href="javascript:;" >{{ $t('From Date') }}</span></th>
                                                <th style="width:340px;"><span href="javascript:;" >{{ $t('To Date') }}</span></th>
                                                <th style="width:340px;"><span href="javascript:;" >{{ $t('Status') }}</span></th>                                               
                                            </tr>
                                        </thead>
                                        <tbody  v-for="(item,index) in ListingData" :key="index">                                        
                                            <tr class="item accordion-toggle" v-bind:class="'collapseOne'+ item.sprint_id" data-toggle="collapse" :data-target="'#Sprint'+item.sprint_id">                                               
                                                <td style="width:188px;width:188px;">
                                                    <button class="btn btn-link" v-if="item.TotalTask>0">
                                                        <em :class="['fa', item.isExpanded ? 'fa-chevron-down' : 'fa-chevron-right', 'task-expand']" @click="onExpandChild(item)"></em>                                                       
                                                    </button> 
                                                </td>
                                                <td class="overflow-visible pt-4" style="width:242px;min-width:242px;">
                                                    <a class="task-dec" @click="EditSprint(item)" :title="item.sprint_name">  
                                                        {{ TruncateStr(item.sprint_name,30) }}
                                                    </a>                                               
                                                </td>
                                                <td class="overflow-visible pt-4" style="width:242px;min-width:242px;">
                                                    <span class="text-overflow-dynamic-container" v-bind:title="item.description">{{ TruncateStr(item.description,30) }}</span>
                                                </td>
                                                <td class="overflow-visible pt-4" style="width:242px;min-width:242px;">
                                                    <span class="text-overflow-dynamic-container" v-bind:title="$options.filters.formatDate(item.STARTDATE)">{{item.STARTDATE != '' ? $options.filters.formatDate(item.STARTDATE) : '--'}}</span>
                                                </td>
                                                <td class="overflow-visible pt-4" style="width:242px;min-width:242px;">
                                                    <span class="text-overflow-dynamic-container" v-bind:title="$options.filters.formatDate(item.ENDATE)">{{item.ENDATE != '' ? $options.filters.formatDate(item.ENDATE) : '--'}}</span>
                                                </td>
                                                <td class="overflow-visible pt-4" style="width:242px;min-width:242px;">                                                    
                                                    <listing-status :isfor="'sprint_status'" ref="updatestatus" v-bind:dataid="item.sprint_id"
                                                        data-controller="Task" v-bind:statuslist="StatusList" v-bind:item="item" v-bind:parentid="item.sprint_id"
                                                        data-action="index" v-bind:dataselected="item.status_name" dataController="Project" dataAction="SprintStatusUpdate"
                                                        v-bind:callbackfunction="FetchGetSprintList" v-bind:isselectedvaluestring="true">
                                                    </listing-status>
                                                </td>                                                                                                   
                                            </tr> 
                                            <tr v-if="item.isExpanded">
                                                <td  colspan="6">
                                                    <table id="tblPhase" class="table table-bordered dt-responsive nowrap mt-0 mb-0 border">
                                                        <thead class="thead-bg">
                                                            <tr>                                                               
                                                                <th style="width:340px;"><span href="javascript:;" >{{$t('Key / Task Name')}}</span></th>                        
                                                                <th style="width:340px;"><span href="javascript:;" >{{$t('Plan Start Date')}}</span></th>
                                                                <th style="width:340px;"><span href="javascript:;" >{{ $t('Plan End Date') }}</span></th>
                                                                <th style="width:340px;"><span href="javascript:;" >{{ $t('Priority') }}</span></th>
                                                                <th style="width:340px;"><span href="javascript:;" >{{ $t('Status') }}</span></th>  
                                                                <th style="width:340px;"><span href="javascript:;" >{{ $t('Team') }}</span></th>  
                                                                <th style="width:340px;"><span href="javascript:;" >{{ $t('Description') }}</span></th>                                           
                                                            </tr>
                                                        </thead>
                                                        <tbody v-for="(stem,sitndex) in item.tasks" :key="sitndex">
                                                            <tr v-if="item.tasks.length>0">
                                                                <td>
                                                                    <span title="Task" class="fa fa-check-square mr-1 text-primary" v-if="stem.task_type == 'T'"></span>
                                                                    <span title="Bug"  class="fa fa-warning mr-1 text-danger" v-if="stem.task_type == 'B'"></span>
                                                                    <span title="Story" class="fa fa-film mr-1 text-success" v-if="stem.task_type == 'S'"></span>
                                                                    <a class="task-dec" @click="ParentTask(stem)" :title="stem.task_name">                                                                       
                                                                        
                                                                         {{ stem.task_number }} {{ TruncateStr(stem.task_name,25) }}
                                                                    </a>
                                                                </td>
                                                                <td> {{ stem.planned_start_date==null?'N/A':$options.filters.formatDate(stem.planned_start_date) }}</td>
                                                                <td>{{ stem.planned_end_date==null?'N/A':$options.filters.formatDate(stem.planned_end_date) }}</td>
                                                                <td>
                                                                    <a class="inactive-disabled" v-if="stem.priority_name != null"> 
                                                                        <span v-bind:style="{ backgroundColor: stem.color_code }" class="text-center text-white d-block">
                                                                            {{ stem.priority_name}}
                                                                        </span>
                                                                    </a>    
                                                                    <span class="text-center d-block" v-else>N/A</span> 
                                                                </td>
                                                                <td>
                                                                    <listing-status :isfor="'TASKLISTING'" ref="updatestatus" v-bind:dataid="stem.task_id"
                                                                         v-bind:statuslist="StatusList" v-bind:item="stem" v-bind:parentid="stem.task_id"
                                                                         v-bind:dataselected="stem.status_name" dataController="Task" dataAction="TaskStatusUpdate"
                                                                        v-bind:callbackfunction="FetchGetSprintList" v-bind:isselectedvaluestring="true">
                                                                    </listing-status>
                                                                </td>
                                                                <td>
                                                                    <span v-if="stem.Number ==0">
                                                                        <a @click="OpenAssignedUser(stem.task_id)" class="text-dark single-action">
                                                                            <em class="fa fa-user-plus"></em>                                
                                                                        </a>
                                                                    </span> 
                                                                    <span v-else> 
                                                                        <a   @click="OpenAssignedUser(stem.task_id)" class="text-dark single-action">
                                                                            <em class="fa fa-user"></em>
                                                                            <span class="noti-circle noti-green" @mouseover="showAssignUser(stem)" @mouseleave="hideAssignUser(stem)" >{{ stem.Number }}</span>                            
                                                                        </a>
                                                                    </span>                       
                                                                    <div class="viewmoretagsbase_ptl showTags" v-if="stem.ispopover">
                                                                        <div class="popover-arrowss_ptl"></div>
                                                                        <div class="viewmoretags_ptl">
                                                                        <span class="head" title="Prashant shukla QA">Team Users</span>
                                                                        <div class="outerbase">
                                                                                <span v-for="(item,index) in stem.AssignUser" :key="index" title="test">{{index +1}}. {{TruncateStr(item,15)}}</span>
                                                                        </div>
                                                                        
                                                                        </div>
                                                                    </div>
                                                                </td>
                                                                <td> {{ stem.task_description==null || stem.task_description=='' ?'N/A':TruncateStr(stripHtmlTags(stem.task_description),25) }}</td>
                                                            </tr>
                                                            <tr v-else>
                                                                <td colspan="6">
                                                                    <div class="text-center text-danger d-flex align-items-center justify-content-center norecs no-record">
                                                                        {{$t('NoRecordfound')}}
                                                                    </div>
                                                                </td>
                                                            </tr>
                                                        </tbody>
                                                    </table>
                                                </td>
                                            </tr>                                                                                           
                                        </tbody>
                                        <tbody>
                                            <tr v-if="ListingData.length==0">
                                                <td colspan="20">
                                                    <div class="text-center text-danger d-flex align-items-center justify-content-center norecs no-record">
                                                        {{$t('NoRecordfound')}}
                                                    </div>
                                                </td>
                                            </tr>  
                                        </tbody>
                                    </table>
                                </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
        <CreateSprint v-if="IsCreateSprint" :IsSprintTabType="IsSprintTabType" :SprintData="SprintData"></CreateSprint>
        <EditTask v-if="IsEditTask" :projectdata="projectdata" @callbackfunction="UpdateTask" :isHideSprint="isHideSprint"></EditTask>
        <AddTeam v-if="IsAssignedUser" :ProjectId="ProjectId" :TaskId="ParentTaskId" :Type="'Task'"
        :ProjectName="ProjectName" @close="IsAssignedUser = false;" @callbackfunction="FetchGetSprintList"></AddTeam>
    </section>
</template>
<script>
import DataService from '../../../../services/DataService';
import CreateSprint from '../../../../components/Modal/CreateSprint.vue'
import EditTask from '../../../../components/Modal/EditTask.vue'
import AddTeam from '../../../../components/Modal/AddTeam.vue'
export default {
    components:{CreateSprint,EditTask,AddTeam},
      props: {       
        isHideSprint: {
            type: Boolean,
            required: true
        }
    },
    data(){
        return{
            isLoading:false,
            IsEditTask:false,
            ListingData:[],
            projectdata:null,
            TotalRecords:0,
            noRecord:false,
            PageSize: 10,
            PageNumber: 1,
            isPaged: 1,
            TotalPages: 0,
            SortBy: '',
            SortExp: '',
            ProjectId:0,
            CompanyId:null,
            IsCreateSprint:false,
            StatusList:[],
            IsAssignedUser:false,
            ParentTaskId:0,
            ProjectName:'',

        }
    },
    async created(){
        var ths=this;       
        ths.CompanyId = ths.GetUserInfo.CompanyId;
        ths.ProjectId=ths.$route.params.projectId;
        ths.StatusDropdown();
        await ths.FetchGetSprintList();
    },
    methods:{
        ParentTask(ths){                        
            this.$emit('EditTask',ths); 
            this.projectdata=ths;
            this.IsEditTask = true;
            setTimeout(function () {
                $("#modalEditTask").modal("show");
            }, 1000);
        },
        UpdateTask(val){          
            var vm =this;
            val.isExpanded=false;
            vm.onExpandChild(val);            
        },
        showAssignUser(row){             
            var vm=this;
            row.ispopover = true;
            this.updateRowData(row);
        },
        hideAssignUser(row) {
            row.ispopover = false;
            this.updateRowData(row);  
        },
        updateRowData(updatedRow) {
            const index = this.ListingData.findIndex(row => row.task_id === updatedRow.task_id);
            if (index !== -1) {
                this.$set(this.ListingData, index, updatedRow);
            }
        },
        stripHtmlTags(str) {
            return str.replace(/<[^>]*>/g, '');
        },
        StatusDropdown:function(){            
            var vm= this;
            var url=`langCode=en&companyId=${vm.CompanyId}&statusType=Project&hasGlobal=true`
            DataService.StatusListing(url).then((response)=>{                
                if (response.data != null && response.data != "") {
                    vm.StatusList = response.data.result.data;                  
                }
            });
        },
        BackToList:function(){
            var ths = this;
            ths.$router.push({ name: 'ProjectList' });
        },
        OpenAssignedUser(TaskId) {
            var vm = this;
            vm.ParentTaskId = TaskId;
            vm.IsAssignedUser = true;
        },
        EditSprint(itm){
            this.IsCreateSprint=true;
            this.IsSprintTabType='Sprint';
            this.SprintData=itm;
        },
        async FetchGetSprintList(){
            var vueObj=this;
            vueObj.isLoading=true;
            var url=`ProjectId=${vueObj.ProjectId}&sortBy=${vueObj.SortBy}&sortExp=${vueObj.SortExp}&pageSize=${vueObj.PageSize}&pageNumber=${vueObj.PageNumber}`;
            await DataService.FetchGetSprintList(url).then((response)=>{
                vueObj.isLoading=false;
                if(response.data.result.DATA.length>0){                    
                    vueObj.ListingData = response.data.result.DATA;                   
                    
                }else{
                    vueObj.ListingData=[];
                }
            })
        },
        onExpandChild:function(item){                        
            var vueObj=this;
            item.isExpanded= !item.isExpanded;
            var url = `ProjectId=${vueObj.ProjectId}&name=&priority=&SprintId=${item.sprint_id}&Type=Lists&BugType=&StatusId=&Assignee=&sortBy=&sortExp=&pageSize=${vueObj.PageSize}&pageNumber=${vueObj.PageNumber}&userType=`;
          
           // var url=`ProjectId=${vueObj.ProjectId}&SprintId=${item.sprint_id}&Type=List&pageSize=${vueObj.PageSize}&pageNumber=${vueObj.PageNumber}`;
            DataService.GetChildSprint(url).then((response)=>{
                if(response.data.result.Data.length>0){ 
                    item.tasks = response.data.result.Data;
                     item.tasks.forEach(x => {
                        x.ispopover=false;
                        x.AssignUser=x.Assign != null?x.Assign.split(','):'';
                     });                  
                    const index = vueObj.ListingData.findIndex(i => i.sprint_id === item.sprint_id);
                    if (index !== -1) {
                        vueObj.$set(vueObj.ListingData, index, { ...item });
                    }                    
                    vueObj.isLoading=false;  
                }
                else {
                    item.tasks = [];
                    vueObj.isLoading=false; 
                } 
            });
        },
    }
}
</script>
<style scoped>
.task-dec{color: #007bff !important;text-decoration: none;background-color: transparent;}
.viewmoretags_ptl {box-sizing: border-box;float: left;}
.viewmoretagsbase_ptl {position: absolute;z-index: 99;box-sizing: border-box;left: 43px;top: 2px;width:150px; border:1px solid #bcbcbc; border-radius: 10px}
.popover-arrowss_ptl {left: -9px;width: 10px;height: 20px;border: none !important;top: 24px;position: absolute;transform: rotate(180deg);}
.viewmoretags_ptl span.head {
    float: left;
    background-color: #f7f7f7!important; color:#303030;
    padding: 4px 10px;
    margin: 0px;
    border-bottom: 1px solid #e6e6e6 !important;
    width: 100%;
    max-width: 100% !important; border-radius:10px 10px 0px 0px; font-weight: 600;
}
.viewmoretags_ptl div.outerbase {
  float: left;
  background-color: #fff !important;
  padding:2px 0px 7px 0px;
  width: 100%;
  max-width: 100% !important; border-radius:0px 0px 10px 10px;    max-height: 105px;
  overflow-y: auto;
}
.viewmoretags_ptl span {
  float: left;
  background-color: #fff !important;
  padding:1px 10px;
  width: 100%;
  max-width: 100% !important; font-size: 12px;
}
.popover-arrowss_ptl::after, .popover-arrowss_ptl::before {
    position: absolute;
    display: block;
    content: "";
    border-color: transparent;
    border-right-color: transparent;
    border-style: solid;
}
.popover-arrowss_ptl::after {
    right: 1px;
    border-width: .5rem 0 .5rem .5rem;
    border-left-color: #fff !important;
}
.popover-arrowss_ptl::after, .popover-arrowss::before {
    position: absolute;
    display: block;
    content: "";
    border-color: transparent;
    border-right-color: transparent;
    border-style: solid;
}
.popover-arrowss_ptl::before {
    right: 0;
    border-width: .5rem 0 .5rem .5rem;
    border-left-color: #d7d7d7 !important;
}
.listing .table-responsive .table td:not(.overflow-visible):not(.mobile-action):not(.details-control) {
    text-overflow: ellipsis;
    overflow: visible!important;
}
</style>