        vm.UserName = vm.GetUserInfo.Name;
        vm.logged_usertype = vm.GetUserInfo.UserType;  
        await vm.CheckProjectMangerUser();
        await vm.ProjectOverview(); 
        if (vm.projectId) {
            const queryTab = vm.$route.query.tab;
            if (queryTab) {
                vm.LeftTAbID = queryTab;
                vm.currentTab = queryTab;
            } else {
