        });       
        vm.GetWidgetTemplateProject();
    },
    methods: {        
        getTabDisplayName(tabFeature) {
            let tabname = '';
            if (this.ProjectIndusrtyType === 'Construction') {
                if (tabFeature === 'Project Phase') {
                    tabname = 'Phase';
                } else if (tabFeature === 'Project Stage') {
                    tabname = 'Stage';
                } else if (tabFeature === 'Milestones') {
                    tabname = 'Milestone';
                    this.MileStoneTab = tabname;
                } else if (tabFeature === 'Team') {
                    tabname = 'WorkCrew';
                    this.TeamTab = tabname;
                } else if (tabFeature === 'Files') {
                    tabname = 'Documents';
                    this.FileTab = tabname;
                }
            }
            // Marketing industry type mappings
            else if (this.ProjectIndusrtyType === 'Marketing') {
                if (tabFeature === 'BackLog') {
                    tabname = 'campaignplan';
                } else if (tabFeature === 'Sprint') {
                    tabname = 'CampaignCycle';
                } else if (tabFeature === 'Project Phase') {
                    tabname = 'CampaignPhase';
                } else if (tabFeature === 'Project Stage') {
                    tabname = 'CampaignStep';
                } else if (tabFeature === 'Tasks') {
                    tabname = 'campaigntask';
                    this.TaskTab = tabname;
                } else if (tabFeature === 'Milestones') {
                    tabname = 'campaignmilestone';
                    this.MileStoneTab = tabname;
                } else if (tabFeature === 'Team') {
                    tabname = 'marketingteam';
                    this.TeamTab = tabname;
                }
            }
            else if (this.ProjectIndusrtyType === 'Design') {
                if (tabFeature === 'BackLog') {
                    tabname = 'DesignBacklog';
                } else if (tabFeature === 'Sprint') {
                    tabname = 'UXSprint';
                }
                else if (tabFeature === 'Project Phase') {
                    tabname = 'UIDesignPhase';
                } else if (tabFeature === 'Project Stage') {
                    tabname = 'UXStage';
                } else if (tabFeature === 'Tasks') {
                    tabname = 'DesignTask';
                    this.TaskTab = tabname;
                } else if (tabFeature === 'Milestones') {
                    tabname = 'DesignMilestone';
                    this.MileStoneTab = tabname;
                } else if (tabFeature === 'Team') {
                    tabname = 'UIDesignTeam';
                    this.TeamTab = tabname;
                }
            }

            else if (this.ProjectIndusrtyType === 'Sales') {
                if (tabFeature === 'BackLog') {
                    tabname = 'DealBacklog';
                } else if (tabFeature === 'Sprint') {
                    tabname = 'SalesCycle';
                }
                else if (tabFeature === 'Project Phase') {
                    tabname = 'PipelinePhase';
                } else if (tabFeature === 'Project Stage') {
                    tabname = 'DealStage';
                } else if (tabFeature === 'Tasks') {
                    tabname = 'SalesTask';
                    this.TaskTab = tabname;
                } else if (tabFeature === 'Milestones') {
                    tabname = 'DealMilestone';
                    this.MileStoneTab = tabname;
                } else if (tabFeature === 'Team') {
                    tabname = 'SalesTeam';
                    this.TeamTab = tabname;
                }
            }


            return tabname !== '' ? tabname : tabFeature;
        },
        // Populate tasbArray with all tab display names (renamed tab names)
        populateTabsArray() {
            if (!this.LeftTablistingdata || !Array.isArray(this.LeftTablistingdata) || this.LeftTablistingdata.length === 0) {
                return;
            }
            this.tasbArray = [];
            this.LeftTablistingdata.forEach(tab => {
                if (tab.isVisible !== false) {
                    const displayName = this.getTabDisplayName(tab.FEATURE);
                    const displayCode = this.getTabDisplayName(tab.FEATURE_CODE);
                    if (displayName && !this.tasbArray.includes(displayName)) {
                        var Obj={
                                displayName:displayName,
                                displayCode:displayCode
                        };
                        this.tasbArray.push(Obj);
                    }
                }
            });
        },
        getStoredTab() {
            try {
                const storageKey = `projectTab_${this.projectId}`;
                const storedTab = localStorage.getItem(storageKey);
                return storedTab || null;
            } catch (error) {
                console.error('Error reading from localStorage:', error);
                return null;
            }
        },
        saveSelectedTab(tabName) {
            try {
                const storageKey = `projectTab_${this.projectId}`;
                localStorage.setItem(storageKey, tabName);
            } catch (error) {
                console.error('Error saving to localStorage:', error);
            }
        },
        restoreSelectedTab() {
            const storedTab = this.getStoredTab();
            if (storedTab && this.LeftTablistingdata && this.LeftTablistingdata.length > 0) {
                const tabExists = this.LeftTablistingdata.some(tab =>
                    tab.FEATURE === storedTab && (tab.isVisible !== false)
                );
                if (tabExists && this.LeftTAbID !== storedTab) {
                    this.LeftTAbID = storedTab;
                    this.currentTab = storedTab;
                } else if (!tabExists && storedTab !== 'Overview') {
                    if (this.LeftTAbID === 'Overview') {
                        return;
                    }
                }
            } else if (!storedTab && this.LeftTablistingdata && this.LeftTablistingdata.length > 0) {
                const currentTabExists = this.LeftTablistingdata.some(tab =>
                    tab.FEATURE === this.LeftTAbID && (tab.isVisible !== false)
                );
                if (!currentTabExists && this.LeftTAbID !== 'Overview') {
                    this.LeftTAbID = 'Overview';
                    this.currentTab = 'Overview';
                }
            }
        },
        preserveTabState(callback) {
            const currentTab = this.LeftTAbID;
            if (currentTab && this.projectId) {
                this.saveSelectedTab(currentTab);
            }
            if (typeof callback === 'function') {
                try {
                    const result = callback();
                    if (result && typeof result.then === 'function') {
                        return result.then(() => {

                            this.$nextTick(() => {
                                if (currentTab && this.projectId) {
                                    this.restoreSelectedTab();
                                }
                            });
                        }).catch((error) => {
                            this.$nextTick(() => {
                                if (currentTab && this.projectId) {
                                    this.restoreSelectedTab();
                                }
                            });
                            throw error;
                        });
                    } else {
                        this.$nextTick(() => {
                            if (currentTab && this.projectId) {
                                this.restoreSelectedTab();
                            }
                        });
                        return result;
                    }
                } catch (error) {
                    this.$nextTick(() => {
                        if (currentTab && this.projectId) {
                            this.restoreSelectedTab();
                        }
                    });
                    throw error;
                }
            }
        },
        CheckDisabled() {
            const isClientOrNU = this.logged_usertype === 'CL' || this.logged_usertype === 'NU';
            const isAdminOrPM = this.logged_usertype === 'CA' || this.logged_usertype === 'PM';
            const hasPmAccess = this.checkPmUser || this.ProjectOwnerId;

            return (isClientOrNU && hasPmAccess) || isAdminOrPM;
        },
        SetCurrentTab: function (moduleName) {
            this.currentTab = moduleName;
            this.gotoPage(moduleName, null);
        },
        async checkTabPrivilege(url) {
            const cacheKey = `${this.projectId}::${url}`;
            if (this.tabPrivilegeCache[cacheKey] !== undefined) {
                return this.tabPrivilegeCache[cacheKey];
            }
            try {
                const response = await DataService.CheckPrivilege(url);
                const allowed = !!response.data;
                this.tabPrivilegeCache[cacheKey] = allowed;
                return allowed;
            } catch (error) {
                console.error('CheckPrivilege failed:', error);
                return false;
            }
        },
        CheckProjectMangerUser: async function () {
            var vm = this;
            var params = `ProjectId=${vm.projectId}`;
            await DataService.CheckProjectMangerUser(params).then(function (response) {
