        GetTabListing: async function () {
            return this.preserveTabState(async () => {
                const vm = this;
                const params = `projectId=${vm.projectId}`;
                try {
                    const response = await DataService.GetTabListingdata(params);
                    if (response.data.result) {
                        vm.LeftTablistingdata = response.data.result.TABLIST;
                        const restrictedUserTypes = ['NU', 'CL'];
                        const tabsToHide = ['Project Phase', 'Budget', 'Client', 'Sprint', 'BackLog', 'RoadMap', 'Construction Board', 'TimeLine', 'Virtual User Configuration', 'Quotes', 'Board', 'Expense Limit', 'Qoutes', 'Raise a Request', 'Queues',
                            'BackLog', 'List', 'Project Stage', 'Board', 'Expense Limit', 'Stage', 'Qoutes', 'Raise a Request', 'Queues', 'Milestones', 'Call Details','Environment','Component'];
                        if (restrictedUserTypes.includes(vm.logged_usertype)) {
                            vm.LeftTablistingdata = vm.LeftTablistingdata.map(tab => {
                                if (tabsToHide.includes(tab.FEATURE) && !vm.checkPmUser) {
                                    tab.isVisible = false;
                                } else {
                                    tab.isVisible = true;
                                }
                                return tab;
                            });
                        }
                        else {
                            vm.LeftTablistingdata = vm.LeftTablistingdata.map(tab => {
                                tab.isVisible = true;
                                return tab;
                            });
                        }
                        vm.LeftTablistingdata.forEach(tab => {
                            const featureName = tab.FEATURE.toLowerCase();
                            const searchValue = vm.moduleSearchElement.toLowerCase();
                            tab.isVisible = tab.isVisible && featureName.includes(searchValue);
                        });

                        const sprintTabs = vm.LeftTablistingdata.filter(x => x.FEATURE_CODE === 'PROJECT_SPRINT');
                        const constructionTabs = vm.LeftTablistingdata.filter(x => x.FEATURE_CODE === 'PROJECT_CONSTRUCTION_BOARD');

                        vm.isHideSprint = sprintTabs.length > 0;
                        vm.isHideConstruction = constructionTabs.length > 0;
                        
                        vm.$nextTick(() => {
                            vm.populateTabsArray();
                        });
                    }
                } catch (error) {
                    console.error("Error fetching tab listing:", error);
                }
            });
        },
        DashboardWidgetsClick(type) {
            this.preserveTabState(() => {
                this.gotoPage(type, null);
            });
        },
        SelectAllSearch() {
            var vm = this;
            vm.GetSelectedValue = window.getSelection().toString()
        },
        ListFiltering() {
            const input = document.getElementById('searchinput');
            let filterInput = input.value;
            if (this.GetSelectedValue) {
                filterInput = filterInput.replaceAll(this.GetSelectedValue, '');
                this.GetSelectedValue = '';
            }
            const filterLower = filterInput.replace(/\W/g, "").toLowerCase();
            this.searchColumnfilter = this.LeftTablistingdata.filter(item => {
                const displayMainColname = this.$t(item.FEATURE);
                return displayMainColname.replace(/\W/g, "").toLowerCase().includes(filterLower);
            });
        },
        
        AddView(data) {
            this.TemplateIndustryTypeId = data;
            this.isView = true;
            this.$emit('AddView', data);
            setTimeout(function () {
                $("#modalAddView").modal("show");
            }, 1000);
        
        },
        CloseAddView() {
            this.isView = false;
            this.tabPrivilegeCache = {};
            this.GetTabListing();
        },
        GetWidgetTemplateProject: async function () {
            var vm = this;
            var params = `ProjectId=${vm.projectId}`;
            await DataService.GetWidgetTemplateProject(params).then(function (response) {
                if (response.data.result != '') {                    
                    var JsonData = JSON.parse(response.data.result);
                    if (JsonData.DATA.length > 0) {
                        vm.DynamicWidegetData = JsonData.DATA;
                    }

                }
            });
        },
    }
}
