            var vm = this;
            var url = 'controller=Project&action=AddUpdatePhase'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    vm.IsAddPhase = true;
                    vm.GetStatusList();
                    vm.FormSchema[0].Data[0].label = vm.$t(vm.NewTabName);
                    vm.FormSchema[0].Data[0].placeholder = `Enter ${vm.$t(vm.NewTabName)}`;  
