        },
        onEndDateChanged(item, val) {
            item.END_DATE = val;
            if (val) {
                this.$set(item, 'ECheckdate', false);
            }
        },
        PhaseCheckAll(event) {
            const isChecked = event.target.checked;
            this.AddPhaseListing = this.AddPhaseListing.map(item => {
                if (!item.DateDisabled) {
                    return { ...item, selected: isChecked };
                }
                return item;
            });
            this.selectAll = isChecked;
            // Trigger form validation to show required field messages
            this.$nextTick(() => {
                this.$refs.form.validate();
            });
        },

        PhaseChange(item) {
            const allSelected = this.AddPhaseListing.filter(it => !it.DateDisabled).every(it => it.selected);
            this.selectAll = allSelected;
        },

        isDisabled(id) {
            this.selectedStage = this.stageList.some(p => p.PHASE_ID === id);
            return this.phaseList.some(p => p.PHASE_ID === id);
        },
