        SavePhase: function (evt) {
    var vm = this;
    vm.$refs.form.validate().then((result) => {
        if (result) {
            const hasDatesWithoutSelection = vm.AddPhaseListing.some(item => !item.selected && !item.DateDisabled && (item.START_DATE || item.END_DATE));
            if (hasDatesWithoutSelection) {
                vm.ShowAlert("Please select the checkbox for rows where dates are entered", "warning", true, vm.$t("Alert"));
                return false;
            }
            const invalidDates = vm.AddPhaseListing.some(item => {
                return item.START_DATE && item.END_DATE && new Date(item.END_DATE) < new Date(item.START_DATE);
            });

            if (invalidDates) {
                vm.ShowAlert(vm.$t('Enddatecannotbeearlierthanstartdate'), "warning", true, vm.$t("Alert"));
                return false; 
            }
            vm.isLoading = true;
            var postString = [];
            const selecteddata = vm.AddPhaseListing.filter(
                it => it.selected
            );

            var filteredArray = vm.AddPhaseListing.filter(item => item.selected || item.DateDisabled);
            if (selecteddata.length === 0 && filteredArray.length === 0) {
                vm.isLoading = false;
                vm.ShowAlert("Please check at least one checkbox", "warning", true, vm.$t("Alert"));
                return false; 
            }

            $.each(filteredArray, function (idx, item) {
                var obj = {
                    PhaseId: item.PHASE_ID,
                    ProjectId: vm.ProjectId,
                    SD: item.START_DATE,
                    ED: item.END_DATE,
                    PhaseName: item.PHASE_NAME
                }
                postString.push(obj);
            });

            let clashDates = false;
            if (postString.length > 0) {
                $.each(postString, function (idx, item) {
                    if (idx > 0) {
                        var chkData = $.grep(postString, function (element) {
                            return (
                                (new Date(element.SD).setHours(0, 0, 0, 0) >= new Date(item.SD).setHours(0, 0, 0, 0) &&
                                    new Date(element.SD).setHours(0, 0, 0, 0) <= new Date(item.ED).setHours(0, 0, 0, 0)) ||
                                (new Date(element.SD).setHours(0, 0, 0, 0) <= new Date(item.SD).setHours(0, 0, 0, 0) &&
                                    new Date(element.ED).setHours(0, 0, 0, 0) >= new Date(item.ED).setHours(0, 0, 0, 0)) ||
                                (new Date(element.ED).setHours(0, 0, 0, 0) >= new Date(item.SD).setHours(0, 0, 0, 0) &&
                                    new Date(element.ED).setHours(0, 0, 0, 0) <= new Date(item.ED).setHours(0, 0, 0, 0))
                            );
                        });
                        if (chkData.length > 1) {
                            clashDates = true;
                        }
                    }
                });

                if (!clashDates) {
                    var objectPostString = JSON.stringify(postString);
                    DataService.SavePhase(objectPostString).then((response) => {
                        if (response.data.result == 'success' && response.data != null) {
                            
                            vm.isLoading = false;
                            vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
                            vm.CloseAssociste();
                            vm.$parent.FetchProjectPhaseList();
                           
                        }
                        else if (response.data.result == 'duplicate') {
                            vm.isLoading = false;
                            vm.ShowAlert(vm.$t('duplicate phase name it should be different!'), "warning", true, vm.$t("Alert"));
                        }
                        else {
                            vm.isLoading = false;
                            vm.CloseAssociste();
                            vm.ShowAlert(vm.$t('AddedError', [vm.$t(vm.NewTabName)]), "failure", true, vm.$t("Alert"));
                        }
                    })
                } else {
                    vm.isLoading = false;
                    vm.ShowAlert(vm.$t('DateValidationOnStage'), "warning", true, vm.$t("Alert"));
                }
            }
        }
    })
},
       
        ClosePhase: function () {
         this.FormSchema[0].Data[0].value='';
         this.FormSchema[0].Data[2].value='1001';
         this.FormSchema[1].Data[0].value='';
            this.IsAddPhase = false;
        },
        async GetStatusList() {
            try {
                this.FormSchema[0].Data[2].config.options=[];
                const params = `statusType=Project&hasglobal=false`;
                const response = await DataService.GetStatusList(params);
                response.data.forEach((itm) => {
                    (this.FormSchema)[0].Data[2].config.options.push({
                        name: itm.STATUS,
                        value: itm.STATUS_ID,
                    })
                });

                const statusField = this.FormSchema[0].Data[2];
                const activeOption = statusField.config.options.find(o => o.name.toLowerCase() === "active");
                if (activeOption) {
                    statusField.value = activeOption.value;
                } else if (statusField.config.options.length > 0) {
                    statusField.value = statusField.config.options[0].value;
                }
                this.$refs.AssignTagForm.UpdateKeyValue();
            }
            catch (err) {
                //console.error("Error fetching status list:", err);
            }
        },
        OnSubmit: function () {
            var vm = this;

            var data = {
                PHASEID: 0,
                PhaseName: vm.FormSchema[0].Data[0].value,
                StatusId: vm.FormSchema[0].Data[2].value,
                PhaseDescription: vm.FormSchema[1].Data[0].value
            }
            var objectPostString = JSON.stringify(data);
            DataService.AddSavePhase(objectPostString).then((response) => {
                if (response.data.result.DATA.length > 0) {
                    if (response.data.result.DATA[0].VALUE =="RECORD EXISTS") {
                         vm.ShowAlert(vm.$t('AlreadyExists', [vm.$t(vm.NewTabName)]), "warning", true, vm.$t("Alert"));
                    }
                    else if (response.data.result.DATA[0].VALUE !=0) {
                        vm.AddPhaseId = response.data.result.DATA[0].VALUE;
                        vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
                        vm.ClosePhase();
                        vm.openAddPhaseDetailModel()
                    } else if (response.data.result.DATA[0].VALUE == 'UPDATE') {
                        vm.ShowAlert(vm.$t('UpdateSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
                        vm.ClosePhase();
                    }
                    else {
                        vm.ShowAlert(vm.$t('AlreadyExists', [vm.$t(vm.NewTabName)]), "warning", true, vm.$t("Alert"));
                    }
                }
            });
        },
    }
}
</script>
