<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title"> {{ SprintData == null ? $t('Create') + ' ' + $t(NewTabName) : $t('Edit') + ' ' + $t(NewTabName) }}</h4>

                        <button type="button" class="close" v-on:click="CloseSprint">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>                        
                    </div>
                    <div class="modal-body">
                        <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema" ref="AssignTagForm" :mandatorytext='MandatoryString'
                            v-on:OnSubmit="OnSubmit">
                            

                        </dynamic-form>
                    </div>   
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import DataService from '../../services/DataService';
export default{
    props:{
        IsSprintTabType:{
            type:String,
            required:true
        },
        SprintData:{
            type:Object,
            required:true
        },
        projectdata:{
            type:Object,
            required:true
        },
        NewTabName: {
            type: String,
            require: true
        },
        TabsArray:{
            type:Array
        }
    },
    data(){
        return{
            isLoading:false,
            SprintId:0,
            MandatoryString:'Fields marked with an asterisk (*) are mandatory.',
            FormSchema: [               
                {
                    layoutType: "double",
                    Data: [
                        {
                            astype: "TextField",                                                
                            label: this.$t('Sprint Name'),
                            name: "PhaseName",
                            value: "",                            
                            placeholder: this.$t('Enter Sprint Name'),
                            validationRules: { "required": true, max: 100 },
                        },
                        {
                            astype: "NumericField",                                                
                            label: this.$t('DurationInHours'),
                            // disabled: true,
                            name: "Tag",
                            value: "0",                                                      
                            placeholder: this.$t('Duration'),
                            validationRules: { "required": false, max: 100 },
                        },
                        {
                            astype: "DateField",
                            label: this.$t("Start Date"),
                            disabled: false,
                            name: "StartDate",
                            value: "",
                            placeholder: this.$t("StartDate"),
                            validationRules: {
                                required: true,
                            },
                            config: { mode: "date", format: "M/D/YYYY", 
                            minDate:'', maxDate: '',
                            onChange:this.checkEndMinDate
                            },
                        }, 
                        {
                            astype: "DateField",
                            label: this.$t("End Date"),
                            disabled: false,
                            name: "EndDate",
                            value: "",
                            placeholder: this.$t("EndDate"),
                            validationRules: {
                                required: true,
                            },
                            config: { mode: "date", format: "M/D/YYYY",   minDate: '', maxDate: '',  onChange:this.calculateDuration},
                        },                       
                    ]
                },
                {
                    layoutType: "single",
                    Data: [
                        {
                            astype: "TextAreaField",                 
                            label: this.$t('Description'),
                            name: "Description",
                            value: "",  
                            validationRules: { "required": false, max: 4000 },
                            config: {
                                rows:3
                            }
                        }
                    ]
                }
            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                    isVisible:true
                },            
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.CloseSprint,
                },
            ],
            ProjectStartDate:'',
            ProjectEndDate:'',
            durationHours:0,
        }
    },
    created:function(){                        
        var vm=this; 
        vm.NewTabName=vm.TabsArray.find(t => t.displayCode === "PROJECT_SPRINT")?.displayName || 'Sprint';
        vm.FormSchema[0].Data[0].label=vm.$t(vm.NewTabName);
        vm.FormSchema[0].Data[0].placeholder=`${vm.$t('Enter')} ${vm.$t(vm.NewTabName)} ${vm.$t('Name')}`;
        vm.ProjectOverview();
        if(vm.SprintData != null){
            vm.BindSprintDetails();
        }       
    },
    methods:{
        ProjectOverview: async function () {
            var vm = this;            
            var params = `projectId=${vm.$route.params.projectId}`;
            await DataService.ProjectOverview(params).then(function (response) {
                if (response.data != null > 0) {                    
                    vm.ProjectStartDate = response.data.planneD_START_DATE;
                    vm.ProjectEndDate = response.data.planneD_END_DATE;
                    vm.FormSchema[0].Data[2].config.minDate= vm.ProjectStartDate;
                    vm.FormSchema[0].Data[2].config.maxDate= vm.ProjectEndDate;
                    vm.FormSchema[0].Data[3].config.minDate= vm.ProjectStartDate;
                    vm.FormSchema[0].Data[3].config.maxDate= vm.ProjectEndDate;
                }
            });
        },
        checkEndMinDate()
        {
            var vm=this;
            var  selectedDate= vm.FormSchema[0].Data[2].value;
            vm.FormSchema[0].Data[3].config.minDate=selectedDate;
            vm.FormSchema[0].Data[2].config.minDate=selectedDate;
            vm.calculateDuration();
        },
        calculateDuration() {            
            const startDate = new Date(this.FormSchema[0].Data[2].value); 
            const endDate = new Date(this.FormSchema[0].Data[3].value);  
            if (isNaN(startDate) || isNaN(endDate)) {
            return;
            }
            const diffInMilliseconds = endDate - startDate;
            const durationInHours = diffInMilliseconds / (1000 * 60 * 60); 
            if(durationInHours < 0)
            {
                durationInHours=0;
            }
            this.FormSchema[0].Data[1].value = Math.floor(durationInHours);
        },
        CloseSprint(){
            this.$parent.IsCreateSprint=false;
        },
        BindSprintDetails(){            
            var ths= this;
            ths.SprintId=ths.SprintData.sprint_id;
            ths.FormSchema[0].Data[0].value=ths.SprintData.sprint_name;
            ths.FormSchema[0].Data[1].value=ths.SprintData.duration;
            ths.FormSchema[0].Data[2].value=ths.SprintData.STARTDATE;
            ths.FormSchema[0].Data[3].value=ths.SprintData.ENDATE;
            ths.FormSchema[1].Data[0].value=ths.SprintData.description;
        },
        OnSubmit:async function(){
            var ths = this;
            var obj = {
                SprintId: ths.SprintId,
                SprintName:ths.FormSchema[0].Data[0].value,
                Duration:ths.FormSchema[0].Data[1].value,
                StartDate:ths.FormSchema[0].Data[2].value,
                EndDate:ths.FormSchema[0].Data[3].value,
                SprintDescription:ths.FormSchema[1].Data[0].value,
                StatusId:1001,
                Project_id:ths.$route.params.projectId,
            }
            if (obj.StartDate && obj.EndDate) {
                const start = new Date(obj.StartDate);
                const end = new Date(obj.EndDate);
                start.setHours(0, 0, 0, 0);
                end.setHours(0, 0, 0, 0);
                if (start > end) {
                    ths.ShowAlert(ths.$t('Enddatecannot'), "failure", true, ths.$t("Alert"));
                    return;
                }
            }
            ths.isLoading=true;
            await DataService.SaveSprint(JSON.stringify(obj)).then(function (response) {
                ths.isLoading=false;
                if(response.data.result.DATA.length>0){  
                    if(response.data.result.DATA[0].VALUE=='EXIST')
                        {
                          ths.ShowAlert(ths.$t('AlreadyExists',[ths.$t(ths.NewTabName)]),"failure", true, ths.$t("Alert"));  
                        }
                   else if(response.data.result.DATA[0].VALUE=='UPDATE'){
                        ths.ShowAlert(ths.$t('UpdatedSuccess',[ths.$t(ths.NewTabName)]),"success", true, ths.$t("Alert"));
                    }else{
                        ths.ShowAlert(ths.$t('AddedSuccess',[ths.$t(ths.NewTabName)]), "success", true,  ths.$t("Alert"));
                    }  
                    ths.CloseSprint();
                    if(ths.IsSprintTabType=='Sprint'){
                        ths.$parent.ReloadTimeline(obj);
                    }
                }else{
                    ths.ShowAlert(ths.$t("UnknownErrorOccur"), "failure", true, ths.$t('Alert'));
                }
            })
        }
    }
}
</script>