<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full d-flex">
                        <h4 class="modal-title">{{ $t('projectactivity') }}</h4>
                        <button type="button" class="close" v-on:click="CloseAssociste()">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>
                    <div class="modal-body">
                        <div class="card mb-3 probx">
                            <div class="card-header">
                                <h2>{{ $t("projectactivity") }} </h2>
                                <div class="col-md-6 text-right pr-0 bottom_filter_button pt-0">
                                    <a @click="toggleCollapse" id="ancActivityExpandAllCollapseAll" title=""
                                        data-toggle-tooltip="tooltip" class="position-relative" style="z-index: 999;">{{
                                            $t('ExpandAllCollapseAll') }}</a>
                                </div>
                            </div>
                            <div class="card-body">
                                <div class="row">
                                    <div class="col-md-12 mbspc">
                                        <div class="activity-tab">
                                            <div
                                                v-if="groupedActivityData && Object.keys(groupedActivityData).length > 0">
                                                <div v-for="(activities, activityDate) in groupedActivityData"
                                                    :key="activityDate">
                                                    <div class="card dark_bgcontrol">
                                                        <div class="card-header">
                                                            <a data-toggle="collapse"
                                                                :href="'#collapseOne' + activityDate"
                                                                style="color: rgb(0, 0, 0);" class="card-link"
                                                                aria-expanded="true">
                                                                <div class="conversation-date heading-border">
                                                                    <span>
                                                                        <i aria-hidden="true"
                                                                            class="fa fa-angle-down rotate-icon pr-1"></i>
                                                                        {{ activityDate }}
                                                                    </span>
                                                                </div>
                                                            </a>
                                                        </div>
                                                        <div :id="'collapseOne' + activityDate"
                                                            v-bind:class="{ 'collapse': true, 'show': activityDate === Object.keys(groupedActivityData)[0], 'show': activityDate === Object.keys(groupedActivityData)[0] || isCollapsed }">
                                                            <div class="card-body">

                                                                <div v-for="(childItem, childIndex) in activities"
                                                                    :key="childIndex"
                                                                    :title="childItem.MESSAGE + ' by ' + childItem.CREATED_BY_NAME"
                                                                    class="row">
                                                                    <div class="col-5 d-flex align-items-center">
                                                                        <div class="iconplus mr-2">
                                                                            <i class="fa fa-check-circle"></i>
                                                                        </div>
                                                                        <div class="circle-oicon mr-2">
                                                                            <i
                                                                                :class="['fa ', childItem.ICON_CODES]"></i>
                                                                        </div>
                                                                        <div>
                                                                            {{ childItem.MESSAGE }} by {{
                                                                                childItem.CREATED_BY_NAME }}
                                                                        </div>
                                                                    </div>

                                                                    <div class="col-5 d-flex justify-content-between">
                                                                        <div class="cont_start"
                                                                            :title="childItem.CREATED_BY_NAME + ' ' + childItem.MONTH_YEAR">
                                                                            <em class="fa fa-envelope-o mr-2"></em>
                                                                            <span class="blue-time">{{
                                                                                childItem.CREATED_BY_NAME
                                                                            }}</span>
                                                                            {{ childItem.MONTH_YEAR }}
                                                                        </div>

                                                                    </div>
                                                                    <div :title="childItem.CREATED_TIME" class="col-1  text-right">
                                                                        <p>{{ childItem.CREATED_TIME }}
                                                                        </p>
                                                                    </div>
                                                                </div>
                                                            </div>



                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div class="clearfix"></div>
                        <div class="row flex-row-reverse mt-3">
                            <div class="col-lg-6 text-right">
                                <a href="javascript:;" class="submitbtn btn btn-danger formbtn"
                                    v-on:click="CancelClient()" title="Cancel">
                                    <i class="fa fa-close pr-2"></i>{{ $t('Cancel') }}
                                </a>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>




<script>
import DataService from "../../services/DataService";
import moment from 'moment';

export default {
    data() {
        return {
            isLoading: false,
            ActivityData: [],
            projectId: 0,
            isCollapsed: false,
            TimeZone: null
        };
    },
    created: async function () {
        var vm = this;
        vm.TimeZone = vm.GetUserInfo.TimeZone;
        vm.projectId = parseInt(vm.$route.params.projectId);
        await vm.UpdateOverView();
    },
    computed: {
        collapseIcon() {
            return this.isCollapsed ? 'fa-angle-down' : 'fa-angle-up';
        },
        groupedActivityData() {
            return this.ActivityData.reduce((groups, activity) => {
                const activityDate = activity.CREATED_DATE;
                if (!groups[activityDate]) {
                    groups[activityDate] = [];
                }
                groups[activityDate].push(activity);
                return groups;
            }, {});
        },
        sortedActivityData() {
            return [...this.ActivityData].sort((a, b) => {
                const dateA = new Date(`${a.CREATED_DATE} ${a.CREATED_TIME}`);
                const dateB = new Date(`${b.CREATED_DATE} ${b.CREATED_TIME}`);
                return dateB - dateA;
            }).slice(0, 5);
        }
    },
    methods: {
        toggleCollapse() {
            this.isCollapsed = !this.isCollapsed;
        },
        UpdateOverView: async function () {
            var vm = this;
            var params = `projectId=${vm.projectId}&subModuleCode=PROJECT_DETAIL`;
            await DataService.GetActivityDatalisting(params).then(function (response) {
                if (response.data.result.DATA.length > 0) {
                    vm.ActivityData = response.data.result.DATA;
                    vm.ActivityData.forEach((item) => {
                        if (item.CREATED_TIME != null && item.CREATED_TIME !== '') {
                            item.CREATED_TIME = vm.addTimeWithOffset(item.CREATED_TIME, vm.TimeZone);
                        }
                    });
                } else {
                    vm.ActivityData = [];
                }
            });
        },
        addTimeWithOffset(time, offset) {
            if (!time || !offset) return time;
            let [hours, minutes] = time.split(":").map(Number);
            let [sign, offH, offM] = offset.match(/([+-])(\d{2}):(\d{2})/).slice(1);
            let totalMinutes = hours * 60 + minutes;
            let offsetMinutes = parseInt(offH) * 60 + parseInt(offM);
            if (sign === "-") offsetMinutes *= -1;
            totalMinutes += offsetMinutes;
            totalMinutes = ((totalMinutes % (12 * 60)) + 12 * 60) % (12 * 60);
            let hh = String(Math.floor(totalMinutes / 60)).padStart(2, "0");
            let mm = String(totalMinutes % 60).padStart(2, "0");
            return `${hh}:${mm}`;
        },
        CloseAssociste: function () {
            this.$emit('closeActivity');
            this.$parent.isViewAllActivity=false;
        },
        CancelClient: function () {
            this.$emit('closeActivity');
            this.$parent.isViewAllActivity=false;
        },
        getFormattedTime() {
            const completeTime = '2025-04-25T14:58:40.5';
            const formattedTime = moment(completeTime).format('hh:mm A');
            return formattedTime;
        },
    }
};
</script>
