<template>  
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title" > {{ ProjectBackLogId>0 ? $t('Edit'): $t('Add') }} {{ $t(NewTabName) }} </h4>                                              
                        <button type="button" class="close" v-on:click="CloseAddBacklog">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>                        
                    </div>
                    <div class="modal-body">
                        <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema" ref="AssignTagForm" :mandatorytext='MandatoryString'
                            v-on:OnSubmit="OnSubmit"></dynamic-form>
                    </div>   
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import DataService from '../../services/DataService';
export default{
    props:{
        BacklogId:{
            type:Number,
            Required:true
        },
        NewTabName:{
            type:String,
            require: true
        },
        AssignTabTabName:{
            type:String,
            require: true
        },
        AssignSprintTab:{
            type:String,
            require: true
        } 
    },
    data(){
        return{
            isLoading:false,
            ProjectBackLogId:0,
            MandatoryString:'Fields marked with an asterisk (*) are mandatory.',
            FormSchema: [               
                {
                    layoutType: "double",
                    Data: [
                    {
                            astype: "TextField",                                                
                            label: this.$t('Subject'),
                            name: "Subject",
                            value: "",               
                            placeholder: this.$t('Enter Subject'),
                            validationRules: { "required": true},
                        },
                        {
                            astype: "SelectField",                                                
                            label: this.$t('Issue Type'),
                            name: "IssueType",
                            value: "",  
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Select Issue Type'),
                            validationRules: { "required": true },
                        },
                        {
                            astype: "SelectField",                                                
                            label: this.$t('ChooseSprint'),
                            name: "ChooseSprint",
                            value: "", 
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Sprint'),
                            validationRules: { "required": false},
                        },
                        {
                            astype: "SelectField",                                                
                            label: this.$t('Priority'),
                            name: "Priority",
                            value: "",  
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Select Priority'),
                            validationRules: { "required": true },
                        },
                        {
                            astype: "SelectField",                                                
                            label: this.$t('Status'),
                            name: "Status",
                            value: "1001",  
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Select Status'),
                            validationRules: { "required": true },
                        },
                        {
                            astype: "MultiSelectField",                                                
                            label: this.$t('User'),
                            mode: "tag",
                            name: "User",
                            value: "",  
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Select User'),
                            validationRules: { "required": false },
                        }                                            
                    ]
                },
                {
                    layoutType: "single",
                    Data: [
                    {
                            astype: "FileField",
                            label: this.$t('Attachment'),
                            name: "attachments",
                            value: "",
                            visibility: false,
                            placeholder: "Select",
                            FieldIndex: 0,
                            config: {
                                maxSize: 5,
                                accept: [{ fileType: 'jpg', iconClass: 'fa-file-image-o' },
                                    { fileType: 'jpeg', iconClass: 'fa-file-image-o' },
                                    { fileType: 'png', iconClass: 'fa-file-image-o' },
                                    { fileType: 'pdf', iconClass: 'fa-file-archive-o' },
                                    { fileType: 'mp4', iconClass: 'fa-video-camera' },
                                    { fileType: 'doc', iconClass: 'fa-file-text-o' },
                                    { fileType: 'docx', iconClass: 'fa-file-text-o' },
                                    { fileType: 'xlsx', iconClass: 'fa-file-excel-o' },
                                    { fileType: 'txt', iconClass: 'fa-file-text-o' },
                                    { fileType: 'xls', iconClass: 'fa-file-excel-o' }
                                ],
                                showSelectedFiles: [],
                                onChange: this.GetBase64String,
                                onDeleteSelectedFiles:this.onDeleteSelectedFiles,
                                options: [],
                                multiple: true
                            },
                            validationRules: {
                                "required": false
                            }
                        }
                    ]
                },
                {
                    layoutType: "single",
                    Data: [
                        {
                            astype: "TextAreaField",                 
                            label: this.$t('Description'),
                            name: "Description",
                            value: "",  
                            validationRules: { "required": false, max: 4000 },
                            config: {
                                rows:3
                            }
                        }
                    ]
                }
            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                    isVisible:true
                },            
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.CloseAddBacklog,
                },
            ],
            projectId:null,
            TeamMemberData:[],
            fileMulitpleData:[],
            oldFiles:[],
            deletedFileId:'',
        }
    },
    created:function(){ 
        var vm = this;
        vm.projectId = parseInt(vm.$route.params.projectId);
        vm.FormSchema[0].Data[2].label=vm.$t(vm.AssignSprintTab);
        vm.FormSchema[0].Data[5].label=vm.$t(vm.AssignTabTabName);
        vm.FormSchema[0].Data[5].placeholder=`${vm.$t('Select')} ${vm.$t(vm.AssignTabTabName)}`
        vm.GetUsers();
        vm.GetProjectSprint();
        vm.GetProjectPriority();
        vm.GetProjectStatus();    
        vm.ProjectBackLogId=vm.BacklogId;
        vm.GetProjectBacklogType();
        if(vm.ProjectBackLogId>0){
            setTimeout(function () {
                vm.FetchBackLogDetails();
            }, 1000);            
        }
        vm.isLoading=false;
    },
    methods:{
        async GetProjectBacklogMoveType(){
            var vm=this;
            var url = `id=&moduleName=PROJECT&type=PROJECT_BACKLOG_MOVE_TYPE&search=&refId=`;
            await DataService.GetDDLData(url).then((response)=>{                 
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) { 
                            response.data.DATA.forEach(item=>{                                
                                let obj={
                                    value:item.value,
                                    name:item.name
                                };
                                vm.FormSchema[0].Data[0].config.options.push(obj);
                            })  
                            vm.$refs.AssignTagForm.UpdateKeyValue();                           
                        }
                    }
                }
            })
        },
        GetProjectBacklogType(){
            var vm=this;
            var url = `id=&moduleName=PROJECT&type=PROJECT_BACKLOG&search=&refId=`;
            DataService.GetDDLData(url).then((response)=>{ 
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) { 
                            response.data.DATA.forEach(item=>{
                                let obj={
                                    value:item.value,
                                    name:item.name
                                };
                                vm.FormSchema[0].Data[1].config.options.push(obj);
                            }) 
                            vm.$refs.AssignTagForm.UpdateKeyValue();                             
                        }
                    }
                }
            })
        },
        FetchBackLogDetails(){
            var vm=this;
            vm.isLoading=true;
            var url = `BackLogId=${vm.ProjectBackLogId}`;
            DataService.FetchBackLogDetails(url).then((response)=>{                 
                if (response.data.result.DATA.length > 0) {                     
                    var BackLogData=response.data.result.DATA; 
                    vm.ProjectBackLogId = BackLogData[0].task_id;
                    vm.FormSchema[0].Data[0].value =  BackLogData[0].task_name;
                    vm.FormSchema[0].Data[1].value =  BackLogData[0].task_type != null ? BackLogData[0].task_type : '';
                    vm.FormSchema[0].Data[2].value =  BackLogData[0].sprint_id != null ? BackLogData[0].sprint_id : '';
                    vm.FormSchema[0].Data[3].value =  BackLogData[0].priority_id !=null ? BackLogData[0].priority_id : '';
                    vm.FormSchema[0].Data[4].value =  BackLogData[0].status_id != null ? BackLogData[0].status_id : '';                   
                    vm.FormSchema[2].Data[0].value = BackLogData[0].task_description;
                    if (BackLogData[0].USER_ID != null && BackLogData[0].USER_ID != '') {
                        const userIdArray = BackLogData[0].USER_ID.split(',').map(id => parseInt(id, 10));
                        const filteredData = vm.TeamMemberData.filter(member => userIdArray.includes(parseInt(member.value, 10)));
                        var UserData=[];
                        if(filteredData.length>0){
                            filteredData.forEach((element)=>{
                                let obj={
                                    value:element.value,
                                    label:element.name
                                }
                                UserData.push(obj);
                            })
                            vm.FormSchema[0].Data[5].value=UserData;
                        }
                    }              
                    if(BackLogData[0].AttachmentData !=null){
                        BackLogData[0].AttachmentData.forEach((element)=>{
                            var Obj = {
                                attachmentId:element.file_version_id,                          
                                attachmentName: element.file_name,
                                attachmentPath: element.file_path,
                                file_id:element.file_id
                            };
                            vm.oldFiles.push(element);
                            vm.FormSchema[1].Data[0].config.showSelectedFiles.push(Obj);                       
                        })                      
                    }
                    vm.$refs.AssignTagForm.UpdateKeyValue();
                }  
                vm.isLoading=false;        
            })
        },
        GetUsers(){
            var vm=this;  
            vm.isLoading=true;     
            var url = `id=${this.projectId}&moduleName=PROJECT&type=PROJECT_USERS&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            vm.TeamMemberData = response.data.DATA;
                            response.data.DATA.forEach(element => {
                                var obj = {
                                    value: element.value,
                                    name: element.name
                                }
                                vm.FormSchema[0].Data[5].config.options.push(obj);
                            })
                        }
                        else {
                            vm.$refs.AssignTagForm.UpdateKeyValue();  
                        }
                    }
                }
                vm.isLoading=false;
            });            
        },
        GetProjectStatus(){
            var vm = this;
            vm.isLoading=true;
            var url=`langCode=en&companyId=${vm.CompanyId}&statusType=Project&hasGlobal=true`
            DataService.StatusListing(url).then((response)=>{                
                if (response.data != null && response.data != "") { 
                    var StatusList = response.data.result.data; 
                    StatusList.forEach((element)=>{
                        let obj={
                            value:element.STATUS_ID,
                            name:element.STATUS
                        }
                        vm.FormSchema[0].Data[4].config.options.push(obj);
                    }); 
                    vm.$refs.AssignTagForm.UpdateKeyValue();                
                }
                vm.isLoading=false;
            });
        },
        GetProjectPriority(){
            this.isLoading=true;
            var url = `id=&moduleName=PROJECT&type=PRIORITY&search=&refId=`;
            DataService.GetDDLData(url).then((response)=>{ 
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) { 
                            var PriorityData=response.data.DATA;
                            PriorityData.forEach(element => {
                                let obj={
                                    name:element.name,
                                    value:element.value
                                }
                                this.FormSchema[0].Data[3].config.options.push(obj);
                            });
                            this.$refs.AssignTagForm.UpdateKeyValue();
                        }
                    }
                }
                this.isLoading=false;
            })
        },
        GetProjectSprint(){
            var vm =this;
            vm.isLoading=true;
            var url = `id=&moduleName=PROJECT&type=PROJECT_SPRINT&search=&refId=${vm.projectId}`;            
            DataService.GetDDLData(url).then((response)=>{ 
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) { 
                            var SprintData=response.data.DATA;
                            SprintData.forEach(element => {
                                let obj={
                                    name:element.name,
                                    value:element.value
                                }
                                this.FormSchema[0].Data[2].config.options.push(obj);
                            });
                            this.$refs.AssignTagForm.UpdateKeyValue();
                        }
                    }
                }
                vm.isLoading=false;
            })
        },
        CloseAddBacklog(){
            this.$parent.IsAddBacklog=false;
        },
        GetBase64String: function (evt) {
            try {
                var vm = this;
                for (var i = 0; i < evt.target.files.length; i++) {
                    var f = evt.target.files[i];
                    var reader = new FileReader();
                    let fileObj = {};              
                    reader.onload = (function (theFile) {
                        return function (e) {
                            var binaryData = e.target.result;
                            var base64StringEncoded = window.btoa(binaryData);
                            var fileName = f.name;
                            vm.fileName = fileName;
                            var n = fileName.lastIndexOf(".");
                            var extensionName = fileName.substring(n + 1, fileName.length);
                            vm.fileExt += "." + extensionName;
                            var attachemnetMime = '{"ContentType":"' + f.type + '","Size":"' + f.size + '","Extension":"' + extensionName + '"}';
                            var fileSize = f.size;
                            vm.fileSize = fileSize;
                            fileObj.attachement_mime = attachemnetMime,
                            fileObj.fileName = fileName,
                            fileObj.base64String = base64StringEncoded,
                            fileObj.fileSize = f.size,
                            fileObj.contentType = f.type,
                            fileObj.ModuleName = 'PROJECT',
                            fileObj.SubModuleCode = 'PROJECT_DEATIL'
                            vm.fileMulitpleData.push(fileObj);
                        };
                    })(f);
                    reader.readAsBinaryString(f);
                }
            } catch (ex) {
                console.error("Error processing attachments:", ex);
            }
        },
        onDeleteSelectedFiles(index){
            var vm = this;
            vm.deletedFileId += (vm.deletedFileId ? ',' : '') + index.file_id;           
            if (vm.FormSchema[1].Data[0].config.showSelectedFiles.length>0) {                
                  const updatedFiles = vm.FormSchema[1].Data[0].config.showSelectedFiles.filter(
                    file => file.attachmentId !== index.attachmentId
                );
                this.$set(vm.FormSchema[1].Data[0].config, 'showSelectedFiles', updatedFiles);                
            }
        },
        OnSubmit:async function(){
            var ths = this;
            var val = "";           
            ths.FormSchema[0].Data[5].value.forEach((itm)=>{                               
                val += itm.value;
                val += ',';
            });             
            var obj = {
                BackLogId: ths.ProjectBackLogId,
                Project_id:ths.projectId,
                Subject:ths.FormSchema[0].Data[0].value,
                IssueTypeId:ths.FormSchema[0].Data[1].value,
                SprintId:ths.FormSchema[0].Data[2].value,
                PriorityId:ths.FormSchema[0].Data[3].value,
                StatusId:ths.FormSchema[0].Data[4].value,
                UserId:val,
                BackLogDescription:ths.FormSchema[2].Data[0].value,
                IsBacklog:true,
                EpicId:null,
                ParentId:null,
                attachmentData:ths.fileMulitpleData.length > 0 ? ths.fileMulitpleData : null,
                deletedIds:ths.deletedFileId,
                  type:'Backlog'
            } 
            await DataService.SaveBackLog(JSON.stringify(obj)).then(function (response) {
                if(response.data.result.DATA.length>0){ 
                    if(response.data.result.DATA[0].VALUE=='UPDATE') {
                        ths.ShowAlert(ths.$t('UpdatedSuccess',[ths.$t(ths.NewTabName)]),"success", true, ths.$t("Alert"));
                    }
                    else if(response.data.result.DATA[0].VALUE=='EXISTS') {
                        ths.ShowAlert(ths.$t('AlreadyExists',[ths.$t(ths.NewTabName)]),"failure", true, ths.$t("Alert"));
                    }
                    else{
                        ths.ShowAlert(ths.$t('AddedSuccess',[ths.$t(ths.NewTabName)]), "success", true,  ths.$t("Alert"));
                    } 
                    ths.CloseAddBacklog();
                    ths.$parent.FetchBacklogListing();
                }else{
                    ths.ShowAlert(ths.$t("UnknownErrorOccur"), "failure", true, ths.$t('Alert'));
                }
            })
        }
    }
}
</script>