<template>
    <div class="cd-ai-panel">
        <div v-if="loading" class="cd-ai-loading">
            <p class="cd-ai-loading-text">Analyzing project data... Please wait.</p>
            <div class="cd-ai-spinner-wrap" role="status" aria-live="polite">
                <span class="cd-ai-spinner" aria-hidden="true"></span>
                <span class="sr-only">Loading...</span>
            </div>
        </div>
        <div v-if="error" class="cd-ai-error">
            <strong>Error! </strong>
            <span>{{ error }}</span>
        </div>
        <div v-if="analysisResult" class="cd-ai-results">
            <div class="cd-ai-intro">
                <div class="cd-ai-intro-icon" aria-hidden="true">
                    <em class="fa fa-info-circle"></em>
                </div>
                <div class="cd-ai-intro-copy">
                    <strong class="cd-ai-intro-title">AI Analysis Complete..!</strong>
                    <p class="cd-ai-intro-desc mb-0">Below are the insights and recommendations for your project.</p>
                </div>
            </div>
            <div class="cd-ai-analysis-content">
                <div
                    class="cd-ai-html"
                    :class="{ 'cd-ai-html--expanded-scroll': isAnalysisExpanded }"
                    v-html="displayAnalysisHtml"
                ></div>
                <div v-if="showAnalysisToggle" class="cd-ai-toggle">
                    <a href="javascript:void(0)" @click="toggleAnalysisView" class="mr-2">
                        {{ isAnalysisExpanded ? 'Show Less...' : 'Show More...' }}
                    </a>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import DataService from "@/services/DataService";

export default {
    name: "AIAnalysisPanel",
    props: {
        projectId: {
            type: Number,
            required: true
        },
        AIAnalysis: {
            type: String,
            default: '',
        },
    },
    data() {
        return {
            analysisResult: null,
            loading: true,
            error: null,
            SortBy: '',
            SortExp: '',
            PageSize: 100,
            PageNumber: 1,
            ProjectId: 0,
            ListingData: [],
            ProjectDetailData: [],
            projectData: { name: '', status: '', tasks: [] },
            isAnalysisExpanded: false,
        };
    },
    computed: {
        formattedAnalysisFull() {
            if (!this.analysisResult) return '';
            return this.formatAnalysisResult(this.analysisResult);
        },
        analysisDisplayParts() {
            return this.splitFormattedAnalysis(this.formattedAnalysisFull);
        },
        /** Collapsed: critical items only. Expanded: full formatted HTML (all severities). */
        displayAnalysisHtml() {
            if (!this.analysisResult) return '';
            if (this.isAnalysisExpanded) return this.formattedAnalysisFull;
            return this.analysisDisplayParts.criticalWrap;
        },
        /** Show More only when there are non-critical insights (warning, strength, etc.). */
        showAnalysisToggle() {
            if (!this.analysisResult || !String(this.analysisResult).trim()) return false;
            return this.analysisDisplayParts.hasRest;
        },
    },
    watch: {
        AIAnalysis: {
            handler(val) {
                if (!this.isSavedAnalysisFromBackend(val)) return;
                this.analysisResult = val;
                this.loading = false;
                this.error = null;
                this.isAnalysisExpanded = false;
            },
            immediate: true,
        },
    },
    created: async function () {
        var ths = this;
        ths.ProjectId = ths.projectId;        
        await ths.initializePanelData();
    },
    methods: {
        /** Non-empty saved HTML/text from API; exclude placeholder rows. */
        isSavedAnalysisFromBackend(val) {
            if (val == null) return false;
            const s = String(val).trim();
            if (!s) return false;
            if (/^no analysis$/i.test(s)) return false;
            return true;
        },
        initializePanelData: async function () {
            await this.FetchTaskList();
            await this.GetProjectDetails();
        },

        FetchTaskList: async function () {
            var vueObj = this;
            var params = `ProjectId=${vueObj.ProjectId}&name=&priority=&SprintId=&Type=&BugType=&StatusId=&Assignee=&sortBy=${vueObj.SortBy}&sortExp=${vueObj.SortExp}&pageSize=${vueObj.PageSize}&pageNumber=${vueObj.PageNumber}&userType=`; 
            await DataService.GetChildSprint(params).then(function (response) {
                if (response.data.result.Data.length > 0) {
                    var updateArray = response.data.result.Data;
                    updateArray.forEach((x) => {
                        var Obj = {
                            name: x.task_name,
                            status: x.status_name,
                            assignedTo: x.Assign != null ? x.Assign : 'Not Assigned',
                            dueDate: x.planned_end_date ? new Date(x.planned_end_date).toISOString().split("T")[0] : 'Not set',
                            notes: x.task_description
                        };
                        vueObj.ListingData.push(Obj);
                    });
                    vueObj.$set(vueObj.projectData, "tasks", vueObj.ListingData);
                } else {
                    vueObj.ListingData = [];
                    vueObj.$set(vueObj.projectData, "tasks", []);
                }
            });
        },
        GetProjectDetails: async function () {
            var vm = this;
            var params = `projectId=${vm.projectId}`;
            await DataService.GetProjectDetails(params).then(function (response) {
                if (response.data.result != null && response.data.result != '') {
                    const overview = response.data.result.PROJECTOVERVIEW[0];
                    vm.ProjectDetailData = [overview];
                    vm.projectData.name = overview.PROJECT_NAME;
                    vm.projectData.status = overview.STATUS_NAME;
                    vm.$set(vm.projectData, "tasks", Array.isArray(vm.ListingData) ? vm.ListingData : []);
                    if (vm.isSavedAnalysisFromBackend(vm.AIAnalysis)) {
                        vm.analysisResult = vm.AIAnalysis;
                        vm.loading = false;
                        vm.isAnalysisExpanded = false;
                    } else if (!vm.analysisResult) {
                        vm.getAIAnalysis();
                    } else {
                        vm.loading = false;
                    }
                } else {
                    vm.loading = false;
                }
            });
        },
        async getAIAnalysis() {
            this.loading = true;
            this.analysisResult = null;
            this.error = null;
            const apiKey = process.env.VUE_APP_GROQ_API_KEY;
            if (!apiKey) {
                this.error = "Groq API key is missing. Add it to your .env file.";
                this.loading = false;
                return;
            }
            const taskDetails = (this.projectData.tasks || [])
                .map(task => `
                - Task: ${task.name || "Untitled"}
                Status: ${task.status || "Unknown"}
                Assigned to: ${task.assignedTo || "Not assigned"}
                Due Date: ${task.dueDate || "Not set"}
                Notes: ${task.notes || "None"}
            `).join("\n") || "No tasks available.";
            const systemPrompt = `You are an expert Project Management AI analyst.`;
            const userPrompt = `Analyze the following project and return ONLY bullet points following these rules:
                - Each bullet must start with one of these emojis:
                ❌ for Critical issues
                ⚠️ for Warnings
                ✅ for Strengths
                💡 for Recommendations (include priority P1/P2/P3 inside parentheses)
                - Format exactly like:
                ❌ Critical: [short headline]. [brief explanation]
                ⚠️ Warning: [short headline]. [brief explanation]
                ✅ Strength: [short headline]. [brief explanation]
                💡 Recommendation (P1): [short headline]. [brief explanation]
                - Do not use any other markdown or grouping.
                Project: ${this.projectData.name || "Unnamed"}
                Overall Status: ${this.projectData.status || "Unknown"}
                --- TASKS ---
                ${taskDetails}`;

            try {
                const response = await fetch("https://api.groq.com/openai/v1/chat/completions", {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                        "Authorization": `Bearer ${apiKey}`
                    },
                    body: JSON.stringify({
                        model: "llama-3.3-70b-versatile", // or any Groq model
                        messages: [
                            { role: "system", content: systemPrompt },
                            { role: "user", content: userPrompt }
                        ],
                        temperature: 0.3,
                        max_tokens: 1024
                    })
                });
                const result = await response.json();

                if (!response.ok) {
                    const errorMsg = result?.error?.message || result?.message || `HTTP ${response.status}`;
                    throw new Error(`Groq API error: ${errorMsg}`);
                }

                const rawAnalysis = result?.choices?.[0]?.message?.content || "No analysis returned.";
                const formatted = this.formatAnalysisResult(rawAnalysis);
                this.analysisResult = formatted;
                this.isAnalysisExpanded = false;

                if (!this.isSavedAnalysisFromBackend(this.AIAnalysis)) {
                    this.SaveAlAnalysis(formatted);
                }
            } catch (error) {
                console.error("AI Analysis failed:", error);
                this.error = error.message || "Failed to get AI analysis. Please try again.";
            } finally {
                this.loading = false;
            }
        },
        restoreEmojiMarkers(text) {
            if (!text) return '';
            return text
                // Recover saved HTML icon spans where DB replaced emoji with ? / ??.
                .replace(/(<span[^>]*text-red-500[^>]*>)[^<]*(<\/span>\s*<span>\s*<strong>\s*Critical:)/gim, '$1❌$2')
                .replace(/(<span[^>]*text-yellow-500[^>]*>)[^<]*(<\/span>\s*<span>\s*<strong>\s*Warning:)/gim, '$1⚠️$2')
                .replace(/(<span[^>]*text-green-500[^>]*>)[^<]*(<\/span>\s*<span>\s*<strong>\s*Strength:)/gim, '$1✅$2')
                .replace(/(<span[^>]*text-purple-500[^>]*>)[^<]*(<\/span>\s*<span>\s*<strong>\s*Recommendation\s*\(P[1-3]\):)/gim, '$1💡$2')
                // Recover plain-text markers.
                .replace(/(?:\?\?|\?)\s*Critical:/gim, '❌ Critical:')
                .replace(/(?:\?\?|\?)\s*Warning:/gim, '⚠️ Warning:')
                .replace(/(?:\?\?|\?)\s*Strength:/gim, '✅ Strength:')
                .replace(/(?:\?\?|\?)\s*Recommendation\s*\((P[1-3])\):/gim, '💡 Recommendation ($1):')
                // Line-start ? when emoji was stripped entirely
                .replace(/^\?\s*Critical:/gim, '❌ Critical:')
                .replace(/^\?\s*Warning:/gim, '⚠️ Warning:')
                .replace(/^\?\s*Strength:/gim, '✅ Strength:')
                .replace(/^\?\s*Recommendation\s*\((P[1-3])\):/gim, '💡 Recommendation ($1):');
        },
        /** Replace emoji / broken ? placeholders in saved HTML with Font Awesome (DB-safe). */
        injectFontAwesomeAiIcons(html) {
            if (!html || typeof html !== 'string') return html;
            const pairs = [
                ['cd-ai-item--critical', 'fa-times-circle'],
                ['cd-ai-item--warning', 'fa-exclamation-triangle'],
                ['cd-ai-item--strength', 'fa-check-circle'],
                ['cd-ai-item--recommend', 'fa-lightbulb-o'],
                ['cd-ai-item--neutral', 'fa-minus-circle'],
            ];
            let h = html;
            pairs.forEach(([type, fa]) => {
                const re = new RegExp(
                    `(<div[^>]*\\b${type}\\b[^>]*>)\\s*<span class="cd-ai-item-icon[^"]*"[^>]*>[\\s\\S]*?<\\/span>`,
                    'gi'
                );
                h = h.replace(
                    re,
                    `$1<span class="cd-ai-item-icon" aria-hidden="true"><i class="fa ${fa}"></i></span>`
                );
            });
            return h;
        },
        toggleAnalysisView() {
            this.isAnalysisExpanded = !this.isAnalysisExpanded;
        },
        /**
         * Split formatted HTML into critical-only vs other blocks.
         * Uses DOMParser so nested <div class="cd-ai-item-body">…</div> does not break extraction
         * (regex [\s\S]*?</div> wrongly closed at the inner </div>).
         */
        splitFormattedAnalysis(html) {
            const empty = '<div class="cd-ai-items"></div>';
            if (!html || typeof html !== 'string') {
                return { criticalWrap: empty, hasRest: false };
            }
            let trimmed = html.trim();
            const hasItemsWrapper = /<div[^>]*\bcd-ai-items\b/i.test(trimmed);
            const hasItem = /<div[^>]*\bcd-ai-item\b/i.test(trimmed);
            if (!hasItemsWrapper && hasItem) {
                trimmed = `<div class="cd-ai-items">${trimmed}</div>`;
            }
            if (typeof DOMParser === 'undefined') {
                return { criticalWrap: empty, hasRest: !!trimmed };
            }
            let doc;
            try {
                doc = new DOMParser().parseFromString(trimmed, 'text/html');
            } catch (e) {
                return { criticalWrap: empty, hasRest: !!trimmed };
            }
            let container = doc.querySelector('.cd-ai-items');
            while (
                container &&
                container.children.length === 1 &&
                container.firstElementChild &&
                container.firstElementChild.classList &&
                container.firstElementChild.classList.contains('cd-ai-items')
            ) {
                container = container.firstElementChild;
            }
            if (!container) {
                return { criticalWrap: empty, hasRest: !!trimmed };
            }
            const directItems = Array.from(container.children).filter(
                (el) =>
                    el.tagName === 'DIV' &&
                    el.classList &&
                    el.classList.contains('cd-ai-item')
            );
            const criticalHtml = [];
            const otherHtml = [];
            directItems.forEach((el) => {
                if (el.classList.contains('cd-ai-item--critical')) {
                    criticalHtml.push(el.outerHTML);
                } else {
                    otherHtml.push(el.outerHTML);
                }
            });
            return {
                criticalWrap: criticalHtml.length ? `<div class="cd-ai-items">${criticalHtml.join('')}</div>` : empty,
                hasRest: otherHtml.length > 0,
            };
        },
        /** Re-wrap only direct .cd-ai-item nodes (fixes nested wrappers / bad saves). */
        flattenAnalysisItemsHtml(html) {
            if (!html || typeof html !== 'string' || typeof DOMParser === 'undefined') {
                return html;
            }
            try {
                const doc = new DOMParser().parseFromString(html.trim(), 'text/html');
                let root = doc.querySelector('.cd-ai-items');
                if (!root) return html;
                while (
                    root.children.length === 1 &&
                    root.firstElementChild &&
                    root.firstElementChild.classList &&
                    root.firstElementChild.classList.contains('cd-ai-items')
                ) {
                    root = root.firstElementChild;
                }
                const items = Array.from(root.children).filter(
                    (el) => el.tagName === 'DIV' && el.classList && el.classList.contains('cd-ai-item')
                );
                if (!items.length) return html;
                return `<div class="cd-ai-items">${items.map((i) => i.outerHTML).join('')}</div>`;
            } catch (e) {
                return html;
            }
        },
        formatAnalysisResult(text) {
            if (!text) return '';
            const normalizedText = this.restoreEmojiMarkers(text);
            // Saved HTML from API/DB: fix ?/?? icons and ensure FA icons
            if (/<[a-z][\s\S]*>/i.test(normalizedText)) {
                const injected = this.injectFontAwesomeAiIcons(normalizedText);
                return this.flattenAnalysisItemsHtml(injected);
            }
            let cleanedText = normalizedText.replace(/\*/g, '').replace(/^• /gm, '');
            let formattedText = cleanedText
                .replace(/^❌ ([^:]+): (.*)$/gim,
                    '<div class="cd-ai-item cd-ai-item--critical"><span class="cd-ai-item-icon" aria-hidden="true"><i class="fa fa-times-circle"></i></span><div class="cd-ai-item-body"><strong>$1:</strong> $2</div></div>')
                .replace(/^⚠️ ([^:]+): (.*)$/gim,
                    '<div class="cd-ai-item cd-ai-item--warning"><span class="cd-ai-item-icon" aria-hidden="true"><i class="fa fa-exclamation-triangle"></i></span><div class="cd-ai-item-body"><strong>$1:</strong> $2</div></div>')
                .replace(/^✅ ([^:]+): (.*)$/gim,
                    '<div class="cd-ai-item cd-ai-item--strength"><span class="cd-ai-item-icon" aria-hidden="true"><i class="fa fa-check-circle"></i></span><div class="cd-ai-item-body"><strong>$1:</strong> $2</div></div>')
                .replace(/^💡 Recommendation \((P[1-3])\): (.*)$/gim,
                    '<div class="cd-ai-item cd-ai-item--recommend"><span class="cd-ai-item-icon" aria-hidden="true"><i class="fa fa-lightbulb-o"></i></span><div class="cd-ai-item-body"><strong>Recommendation ($1):</strong> $2</div></div>')
                .replace(/^- (.*)$/gim,
                    '<div class="cd-ai-item cd-ai-item--neutral"><span class="cd-ai-item-icon" aria-hidden="true"><i class="fa fa-minus-circle"></i></span><div class="cd-ai-item-body">$1</div></div>');

            formattedText = `<div class="cd-ai-items">${formattedText}</div>`;
            return this.flattenAnalysisItemsHtml(this.injectFontAwesomeAiIcons(formattedText));
        },
        SaveAlAnalysis(text) {
            var vm = this;
            var Obj = {
                ProjectId: vm.projectId,
                ProjectAnalysis: text
            };
            var objectPostString = JSON.stringify(Obj);
            DataService.SaveAlAnalysis(objectPostString)
                .then(() => {
                    vm.$emit('analysis-saved', text);
                })
                .catch((err) => {
                    console.error("Failed to save analysis:", err);
                });
        }
    }
}
</script>

<style scoped>
