<template>
    <div>
      <apexchart type="pie" :options="chartOptions" :series="chartData" :key="chartKey" />
    </div>
  </template>
  
  <script>
  import VueApexCharts from 'vue-apexcharts';
  
  export default {
    props:{
        options:{
            type:Array
        },
        Checktype:{
          type:String
        }
    },
    components: {
      apexchart: VueApexCharts
    },
    data() {
      return {   
        chartKey:0,    
        chartData: [],
        chartLabel:[],
        chartOptions: {}
      };
    },
    created:function(){
        var vm= this;
        if(vm.Checktype=='Budget'){
          vm.BudgetChart();
        }else{
          vm.ExpenseChart();
        }        
    },
    methods:{
      ExpenseChart(){
        this.options.forEach((item)=>{
            this.chartData.push(item[1]);
            this.chartLabel.push(item[0]);
        })
        this.chartOptions={
              chart: {
                  width: '380',
                  type: 'pie'
              },
              labels:this.chartLabel,
              responsive: [{
              breakpoint: 480,
              options: {
                chart: {
                  width: '350'
                },
                legend: {
                  position: 'bottom'
                }
              }
            }]
          }
          this.chartKey++;
      },
      BudgetChart(){
          this.options.forEach((item)=>{
              this.chartData.push(item[1]);
              this.chartLabel.push(item[0]);
          });
          this.chartOptions={
              chart: {
                  width: '380',
                  type: 'pie'
              },
              labels:this.chartLabel,
              responsive: [{
              breakpoint: 480,
              options: {
                chart: {
                  width: '350'
                },
                legend: {
                  position: 'bottom'
                }
              }
            }]
          }
          this.chartKey++;
        }
    }
  };
  </script>
  