<template>
  <section>
    <loader :is-visible="isLoading"></loader>
    <div class="ticketsmallfix theme-primary partition p-actions-expand mt-2" style="overflow: visible;">
      <span class="p-name text-white">{{ $t('Environment') }}</span>
      <span class="p-actions float-right">
        <a title="Add" href="javascript:;" class="p-action-btn text-white" @click="openAddModal">
          <em class="fa fa-plus"></em> <br>
          <span>{{ $t('Add') }}</span>
        </a>
        <a title="Delete" href="javascript:;" class="p-action-btn text-white" @click="deleteSelected(null)">
          <em class="fa fa-trash-o pr-2"></em> <br>
          <span>{{ $t('Delete') }}</span>
        </a>
        <a title="Back to list" href="javascript:;" class="p-action-btn text-white" @click="goBackToList">
          <em class="fa fa-angle-double-left pr-2"></em> <br>
          <span>{{ $t('BacktoList') }}</span>
        </a>
      </span>
    </div>
    <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left p-0 top-menu-tab border p-3">
      <div class="row p-0 pt-2 colcontrol">
        <div class="col float-left">
          <div class="form-group mb-2">
            <input class="form-control" :placeholder="dynamicPlaceholder" v-model="envirementNameFilter"
              @keyup.enter="SearchByEnvirementName">
          </div>
        </div>
        <div class="col float-left">
          <div class="form-group mb-2">
            <Treeselect v-model="selectedStatus" :options="statusOptions" :placeholder="$t('Status')" :multiple="true"
              :limit="1" :limitText="getFilterLimitText"
              v-on:input="FetchData(selectedStatus, 'ENVIRONMENT_BY_STATUS')" />
          </div>
        </div>
        <div class="col float-left">
          <div class="background-0 text-left form-check-inline">
            <a href="javascript:void(0);" class="btn btn-danger clearsearchtext px-4" @click="clearFilters">
              <em class="fa fa-refresh"></em>{{ $t('Clear') }}
            </a>
          </div>
        </div>
      </div>
    </div>

    <tg-list ref="tgList" :listType="['List']" :IsShowAction="true" :showCheckBox="true" ModuleName="PROJECT"
      SubModuleCode="ProjectEnvirement" IdentityColumn="environment_id" :ListData="fullList" :HeaderData="Headers"
      :widgets="widgets" :TotalRecords="TotalRecords" :SearchFields="false" :LegendArray="legendArray"
      :PageSize="pageSize" :CurrentPageNumber="pageNum" :SortExp="SortExp" :SortBy="SortBy"
      :RenderRowActionMethod="renderActions" :NorecordfoundText="$t('NoRecordfound')"
      :ListDataCallBackFunction="listDataCallback" v-on:ActionButtonClick="actionButtonClick"
      v-on:SortdataButtonClick="sortdata" v-on:PagerButtonClick="pagerMethod">
      <template v-slot:slotdata="{ data }">
        <template v-if="data.column.COLUMN_NAME == 'environment_name'">
          <a @click="Edit(data.row)" class="text-primary" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
            {{ data.row.environment_name }}
          </a>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'environment_desc'">
          <span :title="data.row.environment_desc" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
            {{ data.row.environment_desc }}
          </span>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'TOTAL_COUNT'">
          <div class="user-count-wrapper">
            <span>
              <a @click="OpenTaskModel(data.row.environment_id)" class="text-dark single-action" href="javascript:;">
                <em class="fa fa-tasks"></em>
                <span class="noti-circle noti-green">{{ data.row.TaskCount }}</span>
              </a>
            </span>
          </div>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'status_name'">
          <listing-status :isfor="'PROJECTENVIREOMENT'" ref="updatestatus" v-bind:dataid="rowIdentity(data.row)"
            data-controller="Task" v-bind:statuslist="StatusList" v-bind:item="data"
            v-bind:parentid="rowIdentity(data.row)" dataController="Project" dataAction="BacklogStatusUpdate"
            v-bind:dataselected="data.row.status_name" v-bind:callbackfunction="listDataCallback"
            v-bind:isselectedvaluestring="true" />
        </template>
      </template>
    </tg-list>
    <AddEnvironmentModal v-if="isAddEnvironmentModal" :EnvireomentData="EnvireomentData" @close="onCloseAddModal" />
    <TaskDetailModel v-if="isTaskModal" :Id="EnvironmentId" :Type="type" @close="onCloseAddModal" />
  </section>
</template>

<script>
import DataService from '../../../../services/DataService'
import AddEnvironmentModal from '../../../../components/Modal/AddEnvironmentModal.vue'
import TaskDetailModel from '../../../../components/Modal/TaskDetailModel.vue'
import Treeselect from '@riophae/vue-treeselect'
import '@riophae/vue-treeselect/dist/vue-treeselect.css'

export default {
  components: { Treeselect, AddEnvironmentModal, TaskDetailModel },
  props: {
    checkPmUser: {
      type: Boolean,
      required: true
    },
    ProjectOwner: {
      type: Boolean,
      required: true
    },
    NewTabName: {
      type: String,
      require: true
    },
    TabsArray: {
      type: Array
    }
  },
  computed: {
    dynamicPlaceholder() {
      return `${this.$t('Environment')} ${this.$t('Name')}...`
    }
  },
  data() {
    return {
      EnvironmentId: 0,
      isTaskModal: false,
      type: 'Environment',
      legendArray: [],
      searchFieldsEmpty: [],
      EnvireomentData: null,
      isLoading: false,
      widgets: [],
      envirementNameFilter: '',
      selectedStatus: null,
      isAddEnvironmentModal: false,
      statusOptions: [],
      StatusList: [],
      fullList: [],
      TotalRecords: 0,
      CompanyId: null,
      _fetchInProgress: false,
      _pendingFetch: false,
      listActions: [{
        title: 'Edit',
        callbackfunction: 'Edit',
        icon: 'fa fa-pencil action-icon',
        additionalSpan: ''
      }, {
        title: 'Delete',
        callbackfunction: 'Delete',
        icon: 'fa fa-trash-o text-danger',
        additionalSpan: ''
      }],
      Headers: [
        {
          COLUMN_NAME: 'environment_name',
          DATA_TYPE: 'string',
          SORTABLE: false,
          VISIBLE: true,
          DISPLAY_NAME: 'Environment Name',
          DISPLAY_ORDER: 1,
          settings: {
            isInSlot: true,
            isValueTruncate: false
          }
        },
        {
          COLUMN_NAME: 'environment_desc',
          DATA_TYPE: 'string',
          SORTABLE: false,
          VISIBLE: true,
          DISPLAY_NAME: 'Environment Description',
          DISPLAY_ORDER: 4,
          settings: {
            isInSlot: true,
            isValueTruncate: false
          }
        },
        {
          COLUMN_NAME: 'status_name',
          DATA_TYPE: 'string',
          SORTABLE: true,
          VISIBLE: true,
          DISPLAY_NAME: 'Status',
          DISPLAY_ORDER: 2,
          settings: {
            isInSlot: true
          }
        },
        {
          COLUMN_NAME: 'TOTAL_COUNT',
          DATA_TYPE: 'number',
          SORTABLE: false,
          VISIBLE: true,
          DISPLAY_NAME: 'Total Count',
          DISPLAY_ORDER: 3,
          settings: {
            isInSlot: true
          }
        }

      ],
      headerButtons: [],
      pageSize: 10,
      pageNum: 1,
      SortBy: '',
      SortExp: '',
      ProjectId: 0
    }
  },
  created() {
    if (this.GetUserInfo && this.GetUserInfo.CompanyId != null) {
      this.CompanyId = this.GetUserInfo.CompanyId
    }
    this.ProjectId = this.$route.params.projectId;
    this.FetchData()
    this.bindStatusOptions()
  },
  methods: {
    OpenTaskModel(id) {
      this.EnvironmentId = id;
      this.isTaskModal = true;
    },
    rowIdentity(row) {
      if (!row) return 0
      var id = row.environment_id != null ? row.environment_id : row.ENVIRONMENT_ID != null ? row.ENVIRONMENT_ID : row.ID != null ? row.ID : row.id
      var n = Number(id)
      return isNaN(n) ? 0 : n
    },
    listDataCallback() {
      this.FetchData()
    },
    getFilterLimitText(count) {
      return `+${count}`
    },
    statusIdsCsv(val) {
      var ids = this.normalizeSelectIds(val)
      return ids.length ? ids.join(',') : ''
    },
    normalizeSelectIds(value) {
      if (value == null) return []
      var arr = Array.isArray(value) ? value : [value]
      return arr
        .map(function (v) {
          if (v == null) return null
          if (typeof v === 'object') return v.value != null ? v.value : (v.id != null ? v.id : null)
          return v
        })
        .filter(function (v) { return v !== null && v !== '' })
    },
    renderActions: function (row) {
      var self = this;
      let rtnActionArray = [];
      self.listActions.forEach(actionItem => {
        let action = { ...actionItem };
        switch (action.title) {
          case 'Edit':
            action.isVisible = true;
            break;
          default: {
            action.isVisible = true;
          }
        }
        rtnActionArray.push(action);
      });
      return rtnActionArray;
    },
    pagerMethod: function (value) {
      if (!value) return
      this.pageSize = value.PageSize != null ? value.PageSize : this.pageSize
      this.pageNum = value.PageNumber != null ? value.PageNumber : this.pageNum
      this.FetchData()
    },
    actionButtonClick: function (callbackfunction, item) {
      switch (callbackfunction) {
        case 'Delete':
          this.deleteSelected(this.rowIdentity(item));
          break;
        case 'Edit':
          this.Edit(item);
          break;
      }
    },
    async Edit(item) {
      var vm = this;
      vm.isLoading = true;
      var url = 'controller=Project&action=AddUpdateEnvironment';
      await DataService.CheckPrivilege(url).then(async function (response) {
        vm.isLoading = false;
        if (response.data || vm.checkPmUser || vm.ProjectOwner) {          
          vm.EnvireomentData = item;
          vm.isAddEnvironmentModal = true;
        }
        else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, vm.$t("Alert"));
        }
      })

    },
    sortdata: function (s) {
      var SortDir = "sort tb_headerSortDown";
      this.pageNum = 1
      this.SortBy = s;
      if (s === this.SortBy) {
        if (this.SortExp == "") {
          this.SortExp = "ASC";
          SortDir = "sort tb_headerSortDown";
        }
        else if (this.SortExp == "ASC") {
          this.SortExp = "DESC";
          SortDir = "sort tb_headerSortUp";
        }
        else {
          this.SortExp = "ASC";
          SortDir = "sort tb_headerSortDown";
        }
      }
      this.FetchData();
      $("#" + s + '  span:first-child').attr("class", SortDir);
    },
    SearchByEnvirementName() {
      this.pageNum = 1
      this.FetchData()
    },
    FetchData(searchValue = null, searchType = null) {
      var ths = this
      if (searchType === 'ENVIRONMENT_BY_STATUS') {
        ths.selectedStatus = searchValue
        ths.pageNum = 1
      }
      if (ths._fetchInProgress) {
        ths._pendingFetch = true
        return
      }
      ths._fetchInProgress = true
      ths.isLoading = true
      const taskName = (ths.envirementNameFilter || '').trim()
      const statusParam = ths.statusIdsCsv(ths.selectedStatus)
      const params =
        `projectId=${ths.ProjectId}&taskName=${encodeURIComponent(taskName)}&status=${statusParam}` +
        `&sortBy=${ths.SortBy}&sortExp=${ths.SortExp}&pageSize=${ths.pageSize}&pageNum=${ths.pageNum}&type=Envirement`
      DataService.GetComponetAndEnvirementListing(params).then((response) => {
        var rows = response && response.data && response.data.result && response.data.result.DATA
        if (rows && rows.length > 0) {
          ths.fullList = rows
          ths.TotalRecords = rows[0].TotalRecords != null ? rows[0].TotalRecords : rows.length
        } else {
          ths.fullList = []
          ths.TotalRecords = 0
        }
      }).catch(() => {
        ths.fullList = []
        ths.TotalRecords = 0
      }).finally(() => {
        ths.isLoading = false
        ths._fetchInProgress = false
        if (ths._pendingFetch) {
          ths._pendingFetch = false
          ths.FetchData()
        }
      })
    },
    bindStatusOptions: function () {
      var vm = this
      if (vm.CompanyId == null && vm.GetUserInfo && vm.GetUserInfo.CompanyId != null) {
        vm.CompanyId = vm.GetUserInfo.CompanyId
      }
      var url = `langCode=en&companyId=${vm.CompanyId}&statusType=Project&hasGlobal=true`
      DataService.StatusListing(url).then((response) => {
        if (response.data != null && response.data !== '') {
          vm.StatusList = response.data.result.data
          vm.statusOptions = []
          vm.StatusList.forEach(function (item) {
            vm.statusOptions.push({
              id: item.STATUS_ID,
              label: item.STATUS
            })
          })
        }
      })
    },
    clearFilters() {
      this.envirementNameFilter = ''
      this.selectedStatus = null
      this.pageNum = 1
      this.FetchData()
    },
    async openAddModal() {
      var vm = this;
       vm.isLoading = true;
      var url = 'controller=Project&action=AddUpdateEnvironment';
      await DataService.CheckPrivilege(url).then(async function (response) {
         vm.isLoading = false;
        if (response.data || vm.checkPmUser || vm.ProjectOwner) {                   
          vm.EnvireomentData = null
          vm.isAddEnvironmentModal = true
        }
        else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, vm.$t("Alert"));
        }
      })

    },
    onCloseAddModal() {
      this.isAddEnvironmentModal = false
      this.EnvireomentData = null;
      this.Id = null;
      this.isTaskModal = false;
    },
    goBackToList() {
      this.$router.push({ name: 'ProjectList' })
    },
    deleteSelected: async function (id) {
      var val = ''
      var vm = this
      var url = 'controller=Project&action=DeleteEnvironment';
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data || vm.checkPmUser || vm.ProjectOwner) {
          if (id == null || id === '') {
            $('.chkItems:checkbox:checked').not("[id^='chkAll_0']").each(function () {
              if (val.length > 0) val += ','
              val += $(this).val()
            })
          } else {
            val = String(id)
          }
          if (val != null && val !== '') {
            vm.confirmR(vm.$t('ConfirmDelete'), true, (vm.$t('Delete') + '  ' + vm.$t('Group')), function () {
              vm.isLoading = true
              var postJSON = {
                ids: val,
                moduleName: 'PROJECT',
                refCode: 'TALYGEN_ENVIROMENT'
              }
              var objectPostString = JSON.stringify(postJSON)
              DataService.CommonCommonDelete(objectPostString).then(function (response) {
                vm.isLoading = false
                if (response.data.length > 0) {
                  if (response.data[0].Status === 'Success') {
                    vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Enviroment')]), 'success', true, vm.$t('Alert'))
                    vm.FetchData()
                  } else {
                    vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Enviroment')]), 'failure', true, vm.$t('Alert'))
                  }
                } else {
                  vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Enviroment')]), 'failure', true, vm.$t('Alert'))
                }
              }).catch(function () {
                vm.isLoading = false
                vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Enviroment')]), 'failure', true, vm.$t('Alert'))
              })
            })
          } else {
            vm.ShowAlert(vm.$t('Selectanyrecordtodelete'), 'failure', true, vm.$t('Alert'))
          }
        }
        else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, vm.$t("Alert"));
        }
      })

    }
  }
}
</script>