<template>
    <section>
        <tg-list ref="tgList" :listType="['List']" :IsShowAction="true" :showCheckBox="false" ModuleName="Event"
            SubModuleCode="Client" IdentityColumn="wish_list_id" :HeaderText="$t('WishList')" :ListData="ListingData"
            :HeaderData="Headers" :HeaderButtons="Buttons" :TotalRecords="TotalRecords"
            :RenderRowActionMethod="renderActions" :ListDataCallBackFunction="FetchWishList" :SortExp="SortExp"
            :SortBy="SortBy" :NorecordfoundText="$t('NoRecordfound')" v-on:ActionButtonClick="actionButtonClick"
            v-on:PagerButtonClick="pagerMethod" v-on:HeaderButtonClick="commonHeaderButtonClick"
            v-on:SortdataButtonClick="sortdata">
            <template v-slot:slotdata="{ data }">
                <template v-if="data.column.COLUMN_NAME == 'item_type'">
                    <a @click="AddWishList(data.row)" class="task-dec" :title="data.row.item_type"
                        style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ data.row.item_type }}
                    </a>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'description'">
                    <span :title="data.row.description"
                        style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ data.row.description }}
                    </span>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'online_url'">
                    <a v-on:click="OpenLinkUrl(data.row.online_url)" class="text-info" :title="data.row.online_url"
                        style="cursor: pointer; white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ data.row.online_url }}
                    </a>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'attachement_path'">
                    <span :title="data.row.attachement_path"
                        style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ data.row.attachement_path == null ? 'N/A' : data.row.attachement_path }}
                    </span>
                </template>
            </template>
        </tg-list>
        <AddEditWishList v-if="Iswishlist" :projectId="eventid" :wishListData="wishListData" />
    </section>
</template>
<script>
import Schema from './WishPortionSchema';
import DataService from '../../../../services/DataService';
import AddEditWishList from '../../../../components/Modal/AddEditWishList.vue';
export default {
    components: { AddEditWishList },
    props: {
        eventid: {
            type: Number,
            required: true
        },
        projectCurrency: {
            type: String
        }
    },
    data() {
        return {
            TotalRecords: 0,
            noRecord: false,
            isLoading: false,
            CompanyId: null,
            PageSize: 10,
            MilestoneID: null,
            milestoneName: '',
            milestoneDesc: '',
            statusId: '',
            PageNumber: 1,
            StatusList: [],
            isPaged: 1,
            TotalPages: 0,
            widgets: [],
            SortBy: '',
            SortExp: '',
            ProjectName: '',
            taskId: '',
            listActions: Schema.listActions,
            Headers: Schema.TableHeader,
            ListingData: [],
            searchCondition: '',
            Buttons: Schema.buttons,
            Iswishlist: false,
            wishListData: [],
            Currency: '',
            userId:0,
        };
    },
    created: async function () {
        this.CompanyId = this.GetUserInfo.CompanyId;
        this.userId = this.GetUserInfo.ID;
        this.Currency = this.projectCurrency;
        await this.FetchWishList();
    },
    methods: {
        renderActions: function () {
            var self = this;
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = { ...actionItem };
                switch (action.title) {
                    case 'AddWishList':
                        action.isVisible = true;
                        break;
                    default: {
                        action.isVisible = true;
                    }
                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchWishList();
        },
        actionButtonClick: function (callbackfunction, item) {
            switch (callbackfunction) {
                case 'EditWishList':
                    this.AddWishList(item);
                    break;
                case 'DeleteWishList':
                    this.commonDeleteData(item.wish_list_id);
                    break;
            }
        },
        commonHeaderButtonClick: async function (event) {
            var vm = this;
            switch (event.callbackfunction) {
                case "AddWishList":
                    vm.AddWishList();
                    break;
                case "BackToList":
                    vm.BackToList();
                    break;
                case "DeleteWishList":
                    vm.commonDeleteData();
                    break;
            }
        },
        AddWishList: async function (data) {
            var vm = this;
            var url = 'controller=Project&action=AddUpdateWishList';
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    vm.wishListData = data;
                    vm.Iswishlist = true;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            })
        },
        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.FetchWishList();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
        commonDeleteData: async function (id) {
            var vm = this;
            var url = 'controller=Project&action=AddUpdateWishList';
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    vm.isLoading = true;
                    if (id != null) {
                        vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Group")), function () {
                            var postJSON = {
                                userId: 0,
                                companyId: 0,
                                eventId: vm.eventid,
                                wishListId: id,
                            };
                            var objectPostString = JSON.stringify(postJSON);
                            DataService.DeleteWishListItem(objectPostString).then(function (response) {
                                vm.isLoading = false;
                                if (response.status == 200) {
                                    vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('WishList')]), "success", true, vm.$t("Alert"));
                                    vm.FetchWishList();
                                }
                                else {
                                    vm.ShowAlert(vm.$t('DeletedError', [vm.$t('WishList')]), "warning", true, vm.$t("Alert"));
                                }
                            });
                        });
                    }
                    else {
                        vm.ShowAlert(vm.$t('Selectanyrecordtodelete'), "warning", true, vm.$t("Alert"));
                    }
                    vm.isLoading = false;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            })
        },
        BackToList: function () {
            this.$router.push({ name: 'ProjectList' });
        },
        FetchWishList: async function () {
            this.isLoading = true;
            const params = `eventId=${this.eventid}&sortBy=${this.SortBy}&sortExp=${this.SortExp}&pageSize=${this.PageSize}&pageNum=${this.PageNumber}&search=`;
            await DataService.GetWishListListing(params).then(response => {
                const data = response.data.result.data;
                if (data.length > 0) {
                    this.ListingData = response.data.result.data;
                    this.TotalRecords = response.data.result.data[0].TOTALRECORDS;
                    this.TotalPages = Math.ceil(this.TotalRecords / this.PageSize);
                    this.$emit('callbackWidgets');
                } else {
                    this.TotalRecords = 0;
                    this.TotalPages = 1;
                    this.ListingData = [];
                }
            });
        },
        OpenLinkUrl: function (item) {
            window.open('//' + item);
        },
    }
};
</script>
