<template>
  <section>
    <div class="row m-0">
      <div class="heading-border">
        <h5 class="h5"><span>{{ $t('Ticket') }} {{ $t('Configuration') }}</span></h5>
      </div>
      <div class="col-12 p-0 mt-2">
        <p class="text-muted">{{ $t('TicketConfigurationDescription') }}</p>
        <div class="table-responsive">
          <table class="table table-bordered mt-0 w-100">
            <thead class="thead-bg">
              <tr>
                <th>{{ $t('Activity') }}</th>
                <th>{{ $t('Ticket') }} {{ $t('Name') }}</th>
                <th>{{ $t('Price') }}</th>
                <th>{{ $t('Status') }}</th>
              </tr>
            </thead>
            <tbody>
              <tr v-if="!ticketList || ticketList.length === 0">
                <td colspan="4" class="text-center"><span class="text-danger no-record">{{ $t('NoRecordfound') }}</span></td>
              </tr>
              <template v-for="(activity, ai) in ticketList">
                <tr v-for="(ticket, ti) in getTickets(activity)" :key="`${ai}-${ti}`">
                  <td>{{ activity.activityName || activity.selectedActivity && activity.selectedActivity.name }}</td>
                  <td>{{ ticket.ticketName }}</td>
                  <td>{{ ticket.price }}</td>
                  <td>{{ ticket.ticketStatus === 1001 ? $t('Active') : $t('Inactive') }}</td>
                </tr>
              </template>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  </section>
</template>

<script>
import DataService from '@/services/DataService';

export default {
  name: 'TicketPortion',
  props: { eventId: { type: [Number, String], required: true } },
  data() { return { ticketList: [] }; },
  created() { this.fetch(); },
  methods: {
    async fetch() {
      try {
        const res = await DataService.GetTicketConfiguration(`eventId=${this.eventId}`);
        this.ticketList = (res.data && res.data.result) ? (Array.isArray(res.data.result) ? res.data.result : res.data.result.ticketList || []) : [];
      } catch (_) { this.ticketList = []; }
    },
    getTickets(activity) { return (activity.ticketList || []).filter(t => !t.isDeleted); }
  }
};
</script>
