<template>
   <div>
    <section>
        <tg-list ref="tgList" :listType="['List']"  :showCheckBox="false"
            ModuleName="PROJECT" SubModuleCode="Task" IdentityColumn="task_id"
             :HeaderText="$t('Vendor Listing')"
            :ListData="ListingData" 
            :HeaderData="Headers" 
            :widgets="widgets" 
            :HeaderButtons="[]"
            :TotalRecords="TotalRecords" 
             :LegendArray="LegendArray"
            
             :ListDataCallBackFunction="FetchTaskList"
              :SortExp="SortExp" :SortBy="SortBy"
            :NorecordfoundText="$t('NoRecordfound')"
             v-on:PagerButtonClick="pagerMethod"
            v-on:SortdataButtonClick="sortdata"
            :isShowHeaderText="true"
            SearchPosition="top"
            :SearchFields="topsearchField"
            
            >
          </tg-list>
    </section>
 </div>
</template>


<script>
import DataService from '../../../../services/DataService';
import Schema from './VendorListingSchema';
import AddVendor from '../../../../components/Modal/AddVendor.vue';
export default{
    components: { AddVendor },
    props: {
        projectId: {
            type: Number,
            required: true
        },
        NewTabName:{
            type:String
        }
    },
    data() {
        return {
            NoRecordfound:false,
            IsVendor:false,
            Headers:Schema.TableHeader,
            Buttons:Schema.buttons,
            TotalRecords:0,
            ListingData:[],
            widgets: [],
            PageSize: 10,
            PageNumber: 1,
            isPaged: 1,
            SortBy: '',
            SortExp: '',
            searchCondition:'',
            topsearchField: [
                {
                    fieldName: 'Vendor Company',
                      fieldType: "ddl-check",
        fieldIcon: "fa fa-file-text-o",
        isSearch: true,
        value: "",
        listOptions: [],  
                },
            ]
        }
    },
    created(){
        this.FetchTaskList();
    },
    methods:{


        
        Add(){

       },
        FetchTaskList(){
            var vm=this;
            var url = `statusIDs=&createdBy=&vendorName=&phoneNumber=1234567890&dateFrom=&dateTo=&sortBy=${vm.SortBy}&sortExp=${vm.SortExp}&pageSize=${vm.PageSize}&pageNumber=${vm.PageNumber}&langCode=en&searchCondition=${vm.searchCondition}`;
            DataService.GetVendorListing(url).then((response)=>{
                
                if(response.data.data !='')
            {
                vm.ListingData=response.data.data;
                vm.TotalRecords=response.data.data[0].total_records;
            }
            else
            {
                vm.ListingData=[];
                vm.TotalRecords=0;
            }
            })
        },
        commonHeaderButtonClick: async function(event) {
            var vm=this;
            switch (event.callbackfunction) {
                case "AddVender":
                    vm.Add(0);
                    break;            
            }
        },
      
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchTaskList();
        },
        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.FetchTaskList();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
    }
}

</script>