<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title">{{$t('associateclient')}}</h4>
                        <button type="button" class="close" v-on:click="CloseAssociste()">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>
                    <div class="modal-body">
                        <div class="row">

                            <div class="col-4 col-sm-4 col-md-4 col-lg-4 col-xl-4 float-left pr-1 pl-3">
                                <div class="form-group">
                                    <input class="form-control" type="text"  v-model="searchString"
                                         @keyup="SearchClient" :placeholder="$t('SearchByClientName')">
                                </div>
                            </div>
                            <div class="col-4 col-sm-4 col-md-4 col-lg-4 col-xl-4 float-left pl-0">
                                <div class="search-btm-btn background-0 text-left form-check-inline">
                                    <a href="javascript:;" title="Clear" id="icon_clear" class="btn btn-danger"
                                        v-on:click="ClearSearchClient()"><i class="fa fa-refresh"></i></a>
                                </div>
                            </div>
                            <div class="col-md-12 listing">
                                <div class="table-responsive table-fix-header dynamic-dashboard-add-report-table">
                                    <table :id="'tblReport'" class="table table-bordered mt-0">
                                        <thead class="thead-bg">
                                            <tr>
                                                <th class="text-center">
                                                    <div class="custom-control custom-checkbox">
                                                        <input data-v-765974b3="" class="chkItems1 custom-control-input"
                                                            v-on:change="selectAllCheckBox($event)" :checked="IsAllChecked"
                                                            type="checkbox" style="display: none;" />
                                                        <label
                                                            class="custom-control-label universal-custom-control-label pt-1"
                                                            for="chkAll_20"></label>
                                                    </div>
                                                </th>
                                                <th>{{$t('ClientName')}} / {{$t('deal_company_name')}}</th>
                                                <th>{{$t('ClientEmail')}}</th>
                                                <th>{{$t('ClientContact')}}</th>
                                                <th>{{$t('COUNTRY')}}</th>
                                                <th>{{$t('StateCity')}}</th>
                                                <th>{{$t('SAStatus')}}</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            <tr v-for="(Item, Index) in clients" :key="Index">
                                                <td class="text-center">
                                                    <input class="chkItems" :data-reportid="Item.USER_ID"
                                                        v-on:change="SelectSingleCheckBox($event)" type="checkbox" />
                                                </td>
                                                <td>{{ Item.CLIENTNAME }}</td>
                                                <td>{{ Item.EMAIL_ID}}</td>
                                                <td>{{ Item.CLIENTPHONE || '--' }}</td>
                                                <td>{{ Item.COUNTRYNAME || '--' }}</td>
                                                <td>{{ Item.CITYSTATE || '--' }}</td>

                                                <td>
                                                    <span v-if="Item.CLIENTSTATUS == 'Active'" title=""
                                                        class="px-2 bg-success text-center text-white d-block">{{
                                                            Item.CLIENTSTATUS }}</span>

                                                    <span v-else-if="Item.CLIENTSTATUS == 'Inactive'" title=""
                                                        class="px-2 bg-danger text-center text-white d-block">{{
                                                            Item.CLIENTSTATUS }}</span>

                                                    <span v-else-if="Item.CLIENTSTATUS == 'ActivationAwaited'" title=""
                                                        class="px-2 bg-warning text-center text-white d-block">{{
                                                            Item.CLIENTSTATUS }}</span>

                                                    <span v-else-if="Item.CLIENTSTATUS == 'Pending'" title=""
                                                        class="px-2 bg-primary text-center text-white d-block">{{
                                                            Item.CLIENTSTATUS }}</span>
                                                </td>
                                            </tr>
                                            <tr v-if="clients.length == 0">
                                                <td colspan="8">
                                                    <div class="text-center text-danger">{{ $t('NoRecordfound') }}</div>
                                                </td>
                                            </tr>
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        </div>
                        <div class="clearfix"></div>
                        <div class="row flex-row-reverse mt-3"> 
                            <div class="col-lg-6 text-right">
                                <a href="javascript:;" class="submitbtn btn btn-success formbtn mr-2" v-on:click="SaveClient()"  title="Save"><i class="fa fa-save pr-2"></i>{{$t('Save')}}</a>
                                <a href="javascript:;" class="submitbtn btn btn-danger formbtn" v-on:click="CancelClient()" title="Cancel"><i class="fa fa-close pr-2"></i>{{ $t('Cancel') }} </a>
                            </div>
                            <div class="col-lg-6">
                                <div class="py-2"><span class="mandatory">{{$t('MandatoryString')}}</span></div>
                            </div>
                        </div>
                        
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
<script>

import DataService from '../../services/DataService';
export default {
    props: {       
        projectId: {
            type: Number,
            require: true
        }
    },
    data() {
        return {
            userId: null,
            companyId: null,
            UserType: null,
            clients: [],
            IsAllChecked: false,
            foundValue: null,
            searchString:'',
            isLoading:false,
            ProjectName:''
        }
    },
    mounted() {
        this.CheckBoxBootstrap();
    },    
    created: function () {
        var vm = this;
        vm.userId = vm.GetUserInfo.ID;
        vm.companyId = vm.GetUserInfo.CompanyId;
        vm.UserType = vm.GetUserInfo.UserType;
        vm.ProjectOverview();
        vm.GetAssociateClientsListing();
    },
    methods: {
        ProjectOverview:async function(){
            var vm = this;
            var params = `projectId=${this.projectId}`;
            await DataService.ProjectOverview(params).then(function (response) {                
                if(response.data != null > 0)
                {                   
                    vm.ProjectName=response.data.projecT_NAME;
                }
            });
        },
        GetAssociateClientsListing: function () {
            var ths = this;
            ths.isLoading = true;
            var url = `projectId=${ths.projectId}`;
            DataService.GetAssociateClientsDataDetails(url).then((response) => {
                if (response.data[0].Result != null) {
                   // debugger
                    const jsonData = JSON.parse(response.data[0].Result);
                    ths.clients = jsonData.Data;  
                    ths.isLoading = false;  
                    setTimeout(() => {
                        ths.CheckBoxBootstrap();
                    }, 1000);
                }
            })
        },
        CloseAssociste: function () {            
            var vm = this;
            vm.$parent.IsAssociateShow = false;
        },
        selectAllCheckBox: function (e) {
            var vm = this;
            if (e.target.checked) {
                $(e.target).closest("table").find("tbody tr td:first-child input.custom-control-input").prop("checked", true);
            } else {
                $(e.target).closest("table").find("tbody tr td:first-child input.custom-control-input").prop("checked", false);
            }
            vm.IsAllChecked = e.target.checked;
        },
        SelectSingleCheckBox: function (event) {
            var vm = this;
            var TotalLength = $(event.target).closest("table").find("tbody tr td:first-child input.custom-control-input").length;
            var checkedLength = $(event.target).closest("table").find("tbody tr td:first-child input.custom-control-input:checked").length;
            if (TotalLength == checkedLength) {
                vm.IsAllChecked = true;
            }
            else {
                vm.IsAllChecked = false;
            }
        },
        SaveClient: function () {  
            //debugger          
            var vm = this;
            vm.isLoading=true;
            var selectedIds = [];
            var Data=[];
            $(vm.$el).find("tbody tr td:first-child input.chkItems:checked").each(function () {
                selectedIds.push($(this).data("reportid"));
            });
            var CommaSeparatedIds = selectedIds.join(',');
            var abcArray = CommaSeparatedIds.split(',').map(Number);
            var filteredClients = vm.clients.filter(client => abcArray.includes(client.USER_ID));
            filteredClients.forEach((response)=>{
                let obj={
                    user_id:response.USER_ID,
                    user_type_id:response.USER_TYPE_ID
                }
                Data.push(obj);
            });
            if(Data.length>0){
                var jsonObj={
                    data:Data,
                    projectId:vm.projectId
                }           
                DataService.SaveClients(JSON.stringify(jsonObj)).then(function (response) {
                    vm.isLoading=false;
                    if (response.data.result.Data[0].StatusValue==1) {
                        vm.ShowAlert(vm.$t("ClientsAddedSuccessfully"), 'success', true, vm.$t('Alert'));
                        vm.$parent.IsAssociateShow = false;
                        vm.$parent.GetClientsListing();
                    }else{
                        vm.ShowAlert(vm.$t("SaveError"), 'failure', true, vm.$t('Alert'));
                    }
                })
            }else{
                vm.isLoading=false;
                vm.ShowAlert(vm.$t("SelectAtleastOneClient"), 'failure', true, vm.$t('Alert'));
            }
          
        },
        CancelClient: function () {
            this.$parent.IsAssociateShow = false;
        },
        ClearSearchClient:function(){
            this.searchString='';
            this.GetAssociateClientsListing();
        },
        SearchClient(event) {            
            if(event.key != 'Backspace'){
                var filteredTeamData = [];
                const query = this.searchString.toLowerCase();
                filteredTeamData = this.clients.filter(item =>
                    item.CLIENTNAME.toLowerCase().includes(query)
                );
                this.clients = [];
                this.clients = [] = filteredTeamData;
            }else{
                var filteredTeamData = [];
                this.GetAssociateClientsListing();
                const query = this.searchString.toLowerCase();
                if(query ==''){
                    this.GetAssociateClientsListing();
                }else{
                    filteredTeamData = this.clients.filter(item =>
                    item.CLIENTNAME.toLowerCase().includes(query)
                );               
                this.clients = filteredTeamData;
                }                
            }  
        }
    },


}

</script>
<style>
    div.table-responsive.table-fix-header.dynamic-dashboard-add-report-table{overflow:auto!important;}
</style>