<template>
  <section>
    <div class="row m-0">
      <div class="heading-border">
        <h5 class="h5"><span>{{ $t('MultiActivityAndCheckList') }}</span></h5>
      </div>
      <div class="listing mt-2">
        <div class="table-responsive">
          <table class="table table-bordered mt-0 w-100">
            <thead class="thead-bg">
              <tr><th>{{ $t('Activity') }}</th><th>{{ $t('Status') }}</th><th>{{ $t('Date') }}</th></tr>
            </thead>
            <tbody>
              <tr v-if="!list || list.length === 0"><td colspan="3" class="text-center"><span class="text-danger no-record">{{ $t('NoRecordfound') }}</span></td></tr>
              <tr v-for="(item, i) in list" :key="item.id || i">
                <td>{{ item.name || item.ACTIVITY_NAME }}</td>
                <td>{{ item.status || item.STATUS_NAME }}</td>
                <td>{{ item.date || item.SCHEDULED_DATE }}</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  </section>
</template>

<script>
import DataService from '@/services/DataService';

export default {
  name: 'EventChecklistPortion',
  props: { eventId: { type: [Number, String], required: true } },
  data() { return { list: [] }; },
  created() {
    DataService.GetEventChecklist(`eventId=${this.eventId}`).then(res => {
      const d = res.data && res.data.result;
      this.list = (d && d.data) ? d.data : (Array.isArray(d) ? d : []);
    }).catch(() => { this.list = []; });
  }
};
</script>
