                                            <td class="overflow-visible pt-4" >
                                                <span class="text-overflow-dynamic-container"
                                                    >{{ item.ActiveTask}}</span>
                                            </td> -->

                                            
                                            <td class="text-center" v-if="CheckDisabled()">
                                                <a class="text-success single-action" @click="EditSprint(item)">
                                                    <em class="fa fa-pencil action-icon"></em>
                                                </a>
                                                <a class="text-danger ml-3 single-action"
                                                    @click="commonDeleteData(item.sprint_id, item.TotalTask)">
                                                    <em class="fa fa-trash-o"></em>
                                                </a>
                                            </td>
                                        </tr>
                                        <tr v-if="item.isExpanded" class="text-center">
                                            <td colspan="12">
                                                <div class="listing">
                                                    <table id="tblPhase"
                                                        class="table table-bordered dt-responsive nowrap mt-0 mb-0 border">
                                                        <thead class="thead-bg">
                                                            <tr>
                                                                <th style="width:340px;" class="text-left"><span
                                                                        href="javascript:;">{{`${$t('Key')} /
                                                                        ${$t(TabsArray.find(t => t.displayCode ===
                                                                        "PROJECT_TASKS")?.displayName || 'Task')}
                                                                        ${$t('Name')}`}}</span></th>
                                                                <th style="width:340px;"><span
                                                                        href="javascript:;">{{ $t('Plan StartDate')}}</span></th>
                                                                <th style="width:340px;"><span href="javascript:;">{{
                                                                        $t('Plan End Date') }}</span></th>
                                                                <th style="width:340px;"><span href="javascript:;">{{
                                                                        $t('Priority') }}</span></th>
                                                                <th style="width:340px;"><span href="javascript:;">{{
                                                                        $t('Status') }}</span></th>
                                                                <th style="width:340px;"><span
                                                                        href="javascript:;">{{$t(TabsArray.find(t =>
                                                                        t.displayCode === "PROJECT_TEAM")?.displayName
                                                                        || 'Team') }}</span></th>
                                                                <th style="width:340px;"><span href="javascript:;">{{
                                                                        $t('Description') }}</span></th>
                                                            </tr>
                                                        </thead>
                                                        <tbody v-for="(stem, sitndex) in item.tasks" :key="sitndex">
                                                            <tr v-if="item.tasks.length > 0">
                                                                <td class="text-left">
                                                                    <span title="Task"
                                                                        class="fa fa-check-square mr-1 text-primary"
                                                                        v-if="stem.task_type == 'T'"></span>
                                                                    <span title="Bug"
                                                                        class="fa fa-warning mr-1 text-danger"
                                                                        v-if="stem.task_type == 'B'"></span>
                                                                    <span title="Story"
                                                                        class="fa fa-film mr-1 text-success"
                                                                        v-if="stem.task_type == 'S'"></span>
                                                                    <span @click="ParentTask(stem)"
                                                                        :title="stem.task_name"> {{ stem.task_number }}
                                                                        {{ TruncateStr(stem.task_name, 25) }}</span>
                                                                </td>
                                                                <td
                                                                    :title="$options.filters.formatDate(stem.planned_start_date)">
                                                                    {{
                                                                        stem.planned_start_date ==null?'N/A':$options.filters.formatDate(stem.planned_start_date)
                                                                    }}</td>
                                                                <td
                                                                    :title="$options.filters.formatDate(stem.planned_end_date)">
                                                                    {{
                                                                        stem.planned_end_date == null?'N/A':$options.filters.formatDate(stem.planned_end_date)
                                                                    }}</td>
                                                                <td>                                                                  
                                                                    <div class="cstm-drop-btn"
                                                                        v-if="stem.priority_name != null">
                                                                        <select id="crmlistingStatus_span"
                                                                            v-model="stem.priority_id" class="w-100"
                                                                            :style="{ backgroundColor: stem.color_code, color: stem.status_color }"
                                                                            @change="CommonPriortyUpdate(stem, $event)">
                                                                            <option
                                                                                v-for="(item, index) in PriorityData"
                                                                                :key="index" :value="item.value">{{
                                                                                item.name
                                                                                }}</option>
                                                                        </select>
                                                                    </div>
                                                                    <span class="d-block" v-else>
                                                                        {{ $t('NA') }}
                                                                    </span>
                                                                </td>
                                                                <td>
                                                                    <listing-status :isfor="'TASKLISTING'"
                                                                        ref="updatestatus" v-bind:dataid="stem.task_id"
                                                                        v-bind:statuslist="StatusList"
                                                                        v-bind:item="stem"
                                                                        v-bind:parentid="stem.task_id"
                                                                        v-bind:dataselected="stem.status_name"
                                                                        dataController="Task"
                                                                        dataAction="TaskStatusUpdate"
                                                                        v-bind:callbackfunction="FetchGetSprintList"
                                                                        v-bind:isselectedvaluestring="true">
                                                                    </listing-status>
                                                                </td>
                                                                <td>
                                                                    <span v-if="stem.Number == 0">
                                                                        <a @click="OpenAssignedUser(stem.task_id,stem.User_id)"
                                                                            class="text-dark single-action">
                                                                            <em class="fa fa-user-plus"></em>
                                                                        </a>
                                                                    </span>
                                                                    <span v-else>
                                                                        <a @click="OpenAssignedUser(stem.task_id,stem.User_id)"
                                                                            class="text-dark single-action">
                                                                            <em class="fa fa-user"></em>
                                                                            <span class="noti-circle noti-green"
                                                                                @mouseover="showAssignUser(stem)"
                                                                                @mouseleave="hideAssignUser(stem)">{{
                                                                                stem.Number }}</span>
                                                                        </a>
                                                                    </span>
                                                                    <div class="viewmoretagsbase_ptl showTags"
                                                                        v-if="stem.ispopover">
                                                                        <div class="popover-arrowss_ptl"></div>
                                                                        <div class="viewmoretags_ptl">
                                                                            <span class="head"
                                                                                title="Prashant shukla QA">Team
                                                                                Users</span>
                                                                            <div class="outerbase">
                                                                                <span
                                                                                    v-for="(item, index) in stem.AssignUser"
                                                                                    :key="index" title="test">{{ index
                                                                                    +1}}.
                                                                                    {{ TruncateStr(item, 15) }}</span>
                                                                            </div>

                                                                        </div>
                                                                    </div>
                                                                </td>
                                                                <td> {{ stem.task_description == null ||
                                                                    stem.task_description==''
                                                                    ?'N/A':TruncateStr(stem.task_description.replace(/<[^>]*>/g, ''),30) }}</td>
                                                            </tr>
                                                            <tr v-else>
                                                                <td colspan="6">
                                                                    <div
                                                                        class="text-center text-danger d-flex align-items-center justify-content-center norecs no-record">
                                                                        {{ $t('NoRecordfound') }}
                                                                    </div>
                                                                </td>
                                                            </tr>
                                                        </tbody>
                                                    </table>
                                                </div>
                                            </td>
                                        </tr>
                                    </tbody>
                                    <tbody>
                                        <tr v-if="ListingData.length == 0">
                                            <td colspan="20">
                                                <div
                                                    class="text-center text-danger d-flex align-items-center justify-content-center norecs no-record">
                                                    {{ $t('NoRecordfound') }}
                                                </div>
                                            </td>
                                        </tr>
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
        <CreateSprint v-if="IsCreateSprint" :TabsArray="TabsArray" :IsSprintTabType="IsSprintTabType"
            :SprintData="SprintData" :projectdata="GetProjectData" :NewTabName="NewTabName"></CreateSprint>
            <AssignedUserModal v-if="IsAssignedUser" :BacklogId="ParentTaskId" :AssigenedUser="assignUserdata"
             @CallbackFunction="FetchGetSprintList" :NewTabName="NewTabName" :AssignTabTabName="NewTabName"
             :AssignSprintTab="NewTabName" :TabsArray="TabsArray"></AssignedUserModal>
        <!-- <EditTask v-if="IsEditTask" :projectdata="projectdata" @callbackfunction="FetchGetSprintList" :isHideSprint="isHideSprint" :TabsArray="TabsArray" ></EditTask>  -->
    </section>
</template>
<script>
import CreateSprint from '../../../../components/Modal/CreateSprint.vue'
import DataService from '../../../../services/DataService';
import SprintListSchema from './SprintListSchema';
// import AddTeam from '../../../../components/Modal/AddTeam.vue'
import AssignedUserModal from '../../../../components/Modal/AssignedUserModal.vue';
// import EditTask from '../../../../components/Modal/EditTask.vue';
import Treeselect from '@riophae/vue-treeselect'
import '@riophae/vue-treeselect/dist/vue-treeselect.css'
export default {
    components: { CreateSprint, AssignedUserModal,Treeselect },
    props: {
        projectdata: {
            type: Object,
            required: true
        },
        NewTabName: {
            type: String,
            require: true
        },
        TabsArray: {
            type: Array
        },
        projectCurrency: {
            type: String
        }, 
        checkPmUser: {
            type: Boolean,
            required: true
        },
        ProjectOwner: {
            type: String
        }
    },
    data() {
        return {
            toDate:null,
            fromDate:null,
            IsTaskName:'',
            StatusFilter:null,
            StatusData:[],
            assignUserdata:null,
            isLoading: false,
            IsSprintTabType: '',
            IsCreateSprint: false,
            ListingData: [],
            ShowMoreFalse: false,
            TotalRecords: 0,
            noRecord: false,
            PageSize: 10,
            PageNumber: 1,
            completionPercentage: 0,
            isPaged: 1,
            TotalPages: 0,
            SortBy: '',
            SortExp: '',
            CompanyId: null,
            containerName: '',
            StatusList: [],
            ProjectId: null,
            SprintData: null,
            AssignUser: [],
            Headers: SprintListSchema.TableHeader,
            listActions: SprintListSchema.listActions,
            widgets: [],
            Buttons: SprintListSchema.buttons,
            PriorityData:[],            
            IsAssignedUser: false,
            projectId: 0,
            ParentTaskId: 0,
            ProjectName: '',
            GetProjectData: '',
        }
    },
    async created() {
        var ths = this;
        ths.NewTabName = ths.TabsArray.find(t => t.displayCode === "PROJECT_SPRINT")?.displayName || 'Sprint';
        ths.containerName = ths.GetUserInfo.ContainerName;
        ths.CompanyId = ths.GetUserInfo.CompanyId;
        ths.ProjectId = ths.$route.params.projectId;
        ths.GetProjectData = ths.projectdata;
        ths.StatusDropdown();        
        ths.GetProjectPriority()
        await ths.FetchGetSprintList();
        ths.CheckDisabled();
    },
    methods: {
        CheckDisabled() {
            const type = this.GetUserInfo.UserType;
            const hasAccess = this.checkPmUser || this.ProjectOwner;
            const isClient = type === 'CL' || type === 'NU';
            const isAdmin = type === 'CA' || type === 'PM';
            const isAllowed = isAdmin || (isClient && hasAccess);
            const buttons =
                isAdmin ? [true, true] :
                    (isClient && hasAccess) ? [true, true] :
                        [false,true];
            this.Buttons.forEach((b, i) => b.isvisible = buttons[i]);
            return isAllowed;
        },
        normalizeSelectIds(value) {
            if (value == null) return [];
            var arr = Array.isArray(value) ? value : [value];
            return arr
                .map(function (v) {
                    if (v == null) return null;
                    if (typeof v === 'object') {
                        return v.value != null ? v.value : (v.id != null ? v.id : null);
                    }
                    return v;
                })
                .filter(function (v) { return v !== null && v !== ''; });
        },
        toQueryDate(date) {
            if (!date) return '';
            var d = new Date(date);
            if (isNaN(d.getTime())) return '';
            var y = d.getFullYear();
            var m = String(d.getMonth() + 1).padStart(2, '0');
            var day = String(d.getDate()).padStart(2, '0');
            return `${y}-${m}-${day}`;
        },
        getFilterLimitText(count) {
            return `+${count}`;
        },
        GetProjectPriority() {
            var url = `id=&moduleName=PROJECT&type=PRIORITY&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            this.PriorityData = response.data.DATA;                            
                        }
                    }
                }
            })
        },
        CommonPriortyUpdate(data, evt) {            
            var vm = this;
            var postJSON = {
                ID: data.task_id,
                StatusId: evt.target.value,
                IsFor: 'UPDATE_PROJECT_PRIORTY'
            };
            var objectPostString = JSON.stringify(postJSON);
            DataService.CommonUpdateStatus(objectPostString).then(function (response) {
                if (response.data != null) {
                    if (response.data.status === 'Success') {
                        vm.FetchGetSprintList();
                        vm.ShowAlert(vm.$t("RecordUpdatedSuccessfully"), "success", vm.$t('Alert'));
                    } else {
                        vm.ShowAlert(vm.$t("UnknownErrorOccur"), "failure", true, vm.$t('Alert'));
                    }
                } else {
                    vm.ShowAlert(vm.$t("UnknownErrorOccur"), "failure", true, vm.$t('Alert'));
                }

            }, function () { });
        },
        OpenAssignedUser(TaskId,userId) {            
            var vm = this;
            vm.ParentTaskId = TaskId;
            vm.assignUserdata=userId;
            vm.IsAssignedUser = true;
        },
        renderActions: function (row) {
            var self = this;
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = { ...actionItem };
                switch (action.title) {
                    case 'Edit':
                        action.isVisible = true;
                        break;
                    case 'Delete':
                        action.isVisible = true;
                        break;

                    default: {
                        action.isVisible = true;
                    }
                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchGetSprintList();
        },
        BackToList: function () {
            var ths = this;
            ths.$router.push({ name: 'ProjectList' });
        },

        commonDeleteData: async function (id, count) {
            var vm = this;
            var val = "";
            var url = 'controller=Project&action=DeleteSprint'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    vm.isLoading = true;
                    if (count > 0) {
                        vm.ShowAlert(vm.$t('todeletethissprint', [vm.$t('Sprint')]), "warning", true, vm.$t("Alert"));
                    }
                    else {
                        if (id == null) {                            
                            $('.chkItems:checkbox:checked').not("[id^='chkAll_0']").each(function () {
                                if (val.length > 0)
                                    val += ',';
                                val += $(this).val();
                            });
                        }
                        else {
                            val = id;
                        }
                        val = id;
                        if (val != null) {
                            vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Group")), function () {
                                var postJSON = {
                                    ids: val,
                                    moduleName: "PROJECT",
                                    refCode: "TALYGEN_sprint"

                                };
                                var objectPostString = JSON.stringify(postJSON);
                                DataService.CommonCommonDelete(objectPostString).then(function (response) {
                                    vm.isLoading = false;
                                    if (response.status == 200) {
                                        vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
                                        vm.FetchGetSprintList();
                                    }
                                    else {
                                        vm.ShowAlert(vm.$t('DeletedError', [vm.$t(vm.NewTabName)]), "warning", true, vm.$t("Alert"));
                                    }
                                });
                            });
                        }
                        else {
                            vm.ShowAlert(vm.$t("Selectanyrecordtodelete"));
                        }
                    }
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
            vm.isLoading = false;
        },
        Clearsearch() {
            this.IsTaskName = '';
            this.StatusFilter = null;
            this.fromDate=null;
            this.toDate=null;
            this.FetchGetSprintList();
        },
        ReloadTimeline(data){this.FetchGetSprintList();},
        async FetchGetSprintList(SearchValue = null, SerachType = null) {
            var vueObj = this;
            var urlCheck = 'controller=Project&action=ProjectSprint';

            // Keep local filter state in sync for event-driven calls.
            if (SerachType === 'TASK_BY_NAME' && SearchValue != null) {
                vueObj.IsTaskName = SearchValue;
            } else if (SerachType === 'TASK_BY_STATUS') {
                vueObj.StatusFilter = SearchValue;
            } else if (SerachType === 'FROM_DATE') {
                vueObj.fromDate = SearchValue;
            } else if (SerachType === 'TO_DATE') {
                vueObj.toDate = SearchValue;
            }

            await DataService.CheckPrivilege(urlCheck).then(async function (response) {
                if (response.data || vueObj.checkPmUser || vueObj.ProjectOwner) {
                    vueObj.isLoading = true;

                    var statusIds = vueObj.normalizeSelectIds(vueObj.StatusFilter).join(",");
                    var searchByName = encodeURIComponent((vueObj.IsTaskName || '').trim());
                    var from = vueObj.toQueryDate(vueObj.fromDate);
                    var to = vueObj.toQueryDate(vueObj.toDate);

                    var url = `ProjectId=${vueObj.ProjectId}` +
                        `&sortBy=${vueObj.SortBy}` +
                        `&searchByName=${searchByName}` +
                        `&SearchByStatus=${statusIds}` +
                        `&to=${to}` +
                        `&from=${from}` +
                        `&sortExp=${vueObj.SortExp}` +
                        `&pageSize=${vueObj.PageSize}` +
                        `&pageNumber=${vueObj.PageNumber}`;

                    await DataService.FetchGetSprintList(url).then((response) => {
                        vueObj.isLoading = false;

                        if (response.data.result.DATA.length > 0) {
                            var updateArray = response.data.result.DATA;

                            updateArray.forEach((x) => {
                                if (x.planned_start_date) {
                                    x.planned_start_date = new Date(x.planned_start_date);
                                }
                                if (x.planned_end_date) {
                                    x.planned_end_date = new Date(x.planned_end_date);
                                }

                                x.ispopover = false;
                                x.child = {
                                    onExpandChild: vueObj.onExpandChild,
                                    isShowChild: false,
                                    isShowExpandButton: true,
                                    data: [],
                                    Header: []
                                };
                            });

                            vueObj.ListingData = updateArray;
                        } else {
                            vueObj.ListingData = [];
                        }
                    });

                } else {
                    vueObj.ShowAlert(vueObj.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        onExpandChild: function (item) {
            var vueObj = this;
            item.isExpanded = !item.isExpanded;
            var url = `ProjectId=${vueObj.ProjectId}&name=&priority=&SprintId=${item.sprint_id}&Type=List&BugType=&StatusId=&Assignee=&sortBy=&sortExp=&pageSize=${vueObj.PageSize}&pageNumber=${vueObj.PageNumber}&userType=`;
            DataService.GetChildSprint(url).then((response) => {
                if (response.data.result.Data.length > 0) {
                    item.tasks = response.data.result.Data;
                    item.tasks.forEach(x => {
                        x.ispopover = false;
                        x.AssignUser = x.Assign != null ? x.Assign.split(',') : '';
                    });
                    const index = vueObj.ListingData.findIndex(i => i.sprint_id === item.sprint_id);
                    if (index !== -1) {
                        vueObj.$set(vueObj.ListingData, index, { ...item });
                    }
                    vueObj.isLoading = false;
                }
                else {
                    item.tasks = [];
                    vueObj.isLoading = false;
                }
            });
        },
        showAssignUser(itm) {            
            itm.ispopover = true;
        },
        hideAssignUser(itm) {
            itm.ispopover = false;
        },        
        CreateSprint: async function () {
            var vm = this;
            var url = 'controller=Project&action=AddUpdateSprint'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    vm.IsCreateSprint = true;
                    vm.IsSprintTabType = 'Sprint';
                    vm.SprintData = null;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        SetTicketColor: function (color) {
            return {
                border: '2px solid ' + color,
                borderTop: '5px solid ' + color
            };
        },
        ShowMore(ths) {
            $('#' + ths).show();
            $('#a' + ths.split('v')[1]).hide();
        },
        ShowLess(ths) {
            $('#' + ths).hide();
            $('#a' + ths.split('v')[1]).show();
        },
        StatusDropdown: function () {
            var vm = this;
            var url = `langCode=en&companyId=${vm.CompanyId}&statusType=Project&hasGlobal=true`
            DataService.StatusListing(url).then((response) => {
                if (response.data != null && response.data != "") {
                    vm.StatusList = response.data.result.data || [];
                    vm.StatusData = vm.StatusList.map(function (item) {
                        return { id: item.STATUS_ID, label: item.STATUS };
                    });
                }
            });
        },
        CompletionPercentage(itm) {
            let completionPercentage = (itm.CompleteTask / itm.TotalTask) * 100;
            if (isNaN(completionPercentage)) {
                completionPercentage = 0;
            }
            return completionPercentage.toFixed(0);
        },
        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.FetchGetSprintList();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
        ParentTask(ths) {
            this.$emit('EditTask', ths);
            this.projectdata = ths;
            this.IsEditTask = true;            
            setTimeout(function () {
                $("#modalEditTask").modal("show");
            }, 1000);
        },
        async EditSprint(itm) {
            var vm = this;
            var url = 'controller=Project&action=AddUpdateSprint'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    vm.IsCreateSprint = true;
                    vm.IsSprintTabType = 'Sprint';
                    vm.SprintData = itm;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },       
        updateTaskStatus(itm) {
            var vm = this;
            var obj = {
                ID: itm.sprint_id,
                StatusId: itm.StatusId,
                IsFor: itm.IsFor
            };
            var objectPostString = JSON.stringify(obj)
            DataService.CommonUpdateStatus(objectPostString).then(function (response) {
                if (response.data.result == '0') {
                    vm.onExpandChild(itm);
                    //vm.FetchGetSprintList();
                }
            });
        }
    }
}
</script>
