<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title">{{ $t('ManageExpense') }} </h4>
                        <button type="button" class="close" v-on:click="CloseAddExpense">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>
                    <div class="modal-body">
                        <Form ref="form">
                            <dynamic-form lang="en" ref="AddExpense" :buttons="buttons" :schema="FormSchema"
                                :mandatorytext="MandatoryString" v-on:OnSubmit="OnSubmit"></dynamic-form>
                        </Form>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import ExpenseDataService from "@/services/DataService";
export default {
    props: {
        CategoryId: {
            type: Number,
            required: true
        },
        projectBudget: {
            type: Number,
            Required: true
        },
        pandingBudget: {
            type: Number | String
        },
        projectCurrency: {
            type: String
        }
    },
    data() {
        return {
            isLoading: false,
            companyId: 0,
            ExpenseId: 0,
            ShowTagModel: false,
            ShowTripModel: false,
            MandatoryString: 'Fields marked with an asterisk (*) are mandatory.',
            FormSchema: [],
            fileMulitpleData: [],
            ProjectBudgetCategory: [],
            CheckFileSize: null,
            UserType: '',
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success saveSendforApproval",
                    text: "<i class='fa fa-paper-plane pr-2'></i>Save",
                },
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.CloseAddExpense
                }
            ],
            selectedCategryAmount: 0,
            selectedCategoryLimitAmount: 0,
            userlisting: '',
            ProjectStartDate: '',
            ProjectEndDate: '',
            acceptArray: [],
            contentType: null,
            selectedFile: null,
            getFileName: null,
            Size:null
        }
    },
    created: async function () {
        var vm = this;
        vm.projectId = parseInt(vm.$route.params.projectId);
        vm.UserType = vm.GetUserInfo.UserType;
        await vm.ProjectOverview();
        vm.GetTeamForAssociateProject();
        vm.GetProjectBudgetCategory()
        vm.CheckExpenseFileSize('ExpenseAttachmentFileSize');
        vm.GetAllowFileType();
        vm.getForm(vm.ExpenseId);


    },
    methods: {
        async GetAllowFileType() {
            var ths = this;
            var url = `moduleName=ProjectFiles`;
            await ExpenseDataService.GetAllowFileType(url).then((response) => {
                if (response.data != null) {
                    const AllowedFileTypes = response.data.allowedFileTypes.split('^');
                    ths.acceptArray = [];
                    AllowedFileTypes.forEach(fileType => {
                        const fileTypeWithoutDot = fileType.trim().replace(/\./g, '');
                        if (fileTypeWithoutDot == 'image') {
                            ths.acceptArray.push(
                                { fileType: 'svg', iconClass: 'fa-file-code' },
                                { fileType: 'psd', iconClass: 'fa-file-image' },
                                { fileType: 'ps', iconClass: 'fa-file-pdf' },
                                { fileType: 'png', iconClass: 'fa-file-image' },
                                { fileType: 'jpg', iconClass: 'fa-file-image' },
                                { fileType: 'jpeg', iconClass: 'fa-file-image' },
                                { fileType: 'ico', iconClass: 'fa-file-image' },
                                { fileType: 'gif', iconClass: 'fa-file-image' },
                                { fileType: 'bmp', iconClass: 'fa-file-image' },
                                { fileType: 'ai', iconClass: 'fa-file-image' }
                            );
                        }

                        else if (fileTypeWithoutDot == 'audio') {
                            ths.acceptArray.push(
                                { fileType: 'wpl', iconClass: 'fa-list-ul' },        // playlist
                                { fileType: 'wma', iconClass: 'fa-file-audio-o' },
                                { fileType: 'wav', iconClass: 'fa-file-audio-o' },
                                { fileType: 'ogg', iconClass: 'fa-file-audio-o' },
                                { fileType: 'mpa', iconClass: 'fa-file-audio-o' },
                                { fileType: 'mp3', iconClass: 'fa-music' },          // popular audio
                                { fileType: 'midi', iconClass: 'fa-keyboard-o' },     // instrument-based
                                { fileType: 'mid', iconClass: 'fa-keyboard-o' },
                                { fileType: 'cda', iconClass: 'fa-compact-disc' },   // CD audio
                                { fileType: 'aif', iconClass: 'fa-file-audio-o' }
                            );
                        }
                        else if (fileTypeWithoutDot == 'document') {
                            ths.acceptArray.push(
                                { fileType: 'doc', iconClass: 'fa-file-word-o' },   // Word
                                { fileType: 'docx', iconClass: 'fa-file-word-o' },
                                { fileType: 'odt', iconClass: 'fa-file-text-o' },   // OpenDocument
                                { fileType: 'rtf', iconClass: 'fa-file-text-o' },
                                { fileType: 'tex', iconClass: 'fa-file-code-o' },   // LaTeX
                                { fileType: 'txt', iconClass: 'fa-file-text-o' },
                                { fileType: 'wpd', iconClass: 'fa-file-text-o' },   // WordPerfect
                                { fileType: 'pdf', iconClass: 'fa-file-pdf-o' });
                        }
                        else if (fileTypeWithoutDot == 'presentation') {
                            ths.acceptArray.push(
                                { fileType: 'odp', iconClass: 'fa-file-powerpoint-o' }, // OpenDocument Presentation
                                { fileType: 'ppt', iconClass: 'fa-file-powerpoint-o' }, // PowerPoint
                                { fileType: 'pptx', iconClass: 'fa-file-powerpoint-o' });
                        }
                        else if (fileTypeWithoutDot == 'video') {
                            ths.acceptArray.push(
                                { fileType: 'mp4', iconClass: 'fa-play-circle-o' },   // most common
                                { fileType: 'mkv', iconClass: 'fa-film' },
                                { fileType: 'avi', iconClass: 'fa-film' },
                                { fileType: 'mov', iconClass: 'fa-video-camera' },
                                { fileType: 'wmv', iconClass: 'fa-video-camera' },
                                { fileType: 'flv', iconClass: 'fa-file-video-o' },
                                { fileType: 'mpeg', iconClass: 'fa-file-video-o' },
                                { fileType: 'mpg', iconClass: 'fa-file-video-o' },
                                { fileType: 'm4v', iconClass: 'fa-file-video-o' },
                                { fileType: '3gp', iconClass: 'fa-mobile' },          // mobile video
                                { fileType: '3g2', iconClass: 'fa-mobile' },
                                { fileType: 'h264', iconClass: 'fa-cogs' },            // codec
                                { fileType: 'rm', iconClass: 'fa-file-video-o' },
                                { fileType: 'swf', iconClass: 'fa-flash' },           // flash
                                { fileType: 'vob', iconClass: 'fa-compact-disc' });
                        }
                        else if (fileTypeWithoutDot == 'Compressed') {
                            ths.acceptArray.push(
                                { fileType: 'z7', iconClass: 'fa-file-archive-o' }, // 7z (probably you meant 7z)
                                { fileType: 'deb', iconClass: 'fa-cube' },           // Debian package
                                { fileType: 'rar', iconClass: 'fa-file-archive-o' },
                                { fileType: 'rpm', iconClass: 'fa-cube' },           // Linux package
                                { fileType: 'zip', iconClass: 'fa-file-archive-o' });
                        }
                        else if (fileTypeWithoutDot == 'Spreadsheet') {
                            ths.acceptArray.push(
                                { fileType: 'csv', iconClass: 'fa-file-text-o' },   // plain data
                                { fileType: 'ods', iconClass: 'fa-file-excel-o' },  // OpenDocument Spreadsheet
                                { fileType: 'xls', iconClass: 'fa-file-excel-o' },  // Excel
                                { fileType: 'xlsm', iconClass: 'fa-file-excel-o' },  // Excel macro
                                { fileType: 'xlsx', iconClass: 'fa-file-excel-o' });
                        }
                        else if (fileTypeWithoutDot == 'application') {
                            ths.acceptArray.push(
                                { fileType: 'c', iconClass: 'fa-file-code' },
                                { fileType: 'class', iconClass: 'fa-gears' },
                                { fileType: 'java', iconClass: 'fa-file-code' },
                                { fileType: 'sh', iconClass: 'fa-terminal' });
                        }
                        else {
                            ths.acceptArray.push({
                                fileType: fileTypeWithoutDot,
                                iconClass: 'fa-video-camera'
                            });
                        }
                    });
                }
            });
        },
        ProjectOverview: async function () {
            var vm = this;
            var params = `projectId=${vm.projectId}`;
            await ExpenseDataService.GetProjectDetails(params).then(function (response) {
                if (response.data != null > 0) {
                    var ProjectDetailData = response.data.result.PROJECTOVERVIEW[0];
                    vm.ProjectStartDate = ProjectDetailData.PLANNED_START_DATE;
                    vm.ProjectEndDate = ProjectDetailData.PLANNED_END_DATE;
                }
            });

        },
        GetTeamForAssociateProject() {
            var ths = this;
            var url = `projectId=${ths.projectId}&projectName&designationId=&sortBy=&sortExp=&pageSize=${10000}&pageNum=${1}`;
            ExpenseDataService.GetTeamListing(url).then((response) => {

                if (response.data.result.data.length > 0) {
                    this.userlisting = response.data.result.data.map(element => {
                        return {
                            first_value: null,
                            name: element.ALIASNAME,
                            second_value: null,
                            value: element.USER_ID
                        };
                    });
                } else { ths.userlisting = [] }
            });
        },
        GetProjectBudgetCategory() {
            var vm = this;
            var url = `id=&moduleName=PROJECT&type=PROJECT_BUDGET_CATEGORY&search=&refId=${vm.projectId}`;
            ExpenseDataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            vm.ProjectBudgetCategory = response.data.DATA;
                        }
                    }
                }
            })
        },
        CheckExpenseFileSize: async function (ths) {
            var url = `ConfigurationValueByKey=${ths}`;
            await ExpenseDataService.GetConfigurationValue(url).then(response => {
                this.CheckFileSize = parseInt(response.data.CONFIG_DATA_VALUE);
            });
        },
        getForm: function (id) {
            var ths = this;
            ths.isLoading = true;
            var url = `recordId=${id}&moduleName=Expenses&subModuleCode=EM_EXPENSE&langCode=en`;
            ExpenseDataService.GetDynamicForm(url).then(function (response) {
                if (response != null && response.data != null) {
                    ths.FormSchema = ths.$refs.AddExpense.ConvertCustomFieldIntoDynamicFormObj(response.data.data);
                    ths.FormSchema.forEach((group) => {
                        if (group.group_name == 'Attachment') {
                            group.layoutType = 'single';
                        }
                        if (group.group_name == 'General Information') {
                            group.layoutType = 'four';
                        }
                        group.Data.forEach(async (field) => {
                            if (field.name == 'expense_id') {
                                if (field.value != "") {
                                    ths.GetExpenseFileList(field.value);
                                } else {
                                    field.value = 0;
                                }
                            }
                            if (field.name == "is_bulk_upload") {
                                if (field.value == "0") {
                                    field.value = 0;
                                }
                            }
                            if (field.name == 'expense_category_id') {
                                field.config.options = [];
                                field.config.options = ths.ProjectBudgetCategory;
                                if (ths.CategoryId > 0) {
                                    var cId = field.config.options.filter(c => parseInt(c.value) == ths.CategoryId);
                                    field.value = cId[0].value;
                                    field.disabled = true;
                                }
                            }
                            if (field.name == "status_id") {
                                field.value = 2;
                            }
                            if (field.name == "currency_id") {
                                var c_code = field.config.options.filter(c => c.first_value == ths.projectCurrency)
                                field.value = c_code[0].value;
                                field.disabled = true;
                            }
                            if (field.name == 'tag_id') {
                                field.config.showAddIcon = false;
                                field.config.onAddButtonClick = ths.openaddTagpopup;
                            }
                            if (field.name == "trip_id") {
                                field.config.showAddIcon = false;
                                field.config.onAddButtonClick = ths.openaddTrippopup;
                            }
                            if (field.name == "expense_date") {
                                field.config.maxDate = new Date(ths.ProjectEndDate);
                                field.config.format = "MM/DD/YYYY";
                            }
                            if (field.name == "task_id") {
                                field.visibility = false;
                                field.config.options = [];
                            }
                            if (field.name == "project_id") {
                                field.disabled = true;
                                field.visibility = false;
                                field.value = ths.projectId;
                                ths.BindTaskDDL(field.value);
                            }
                            if (field.name == "expense_amount") {
                                field.label = field.label + '(' + ths.projectCurrency + ')';
                            }
                            if (field.name == "created_by") {
                                field.disabled = ths.UserType != 'NU' ? false : true;
                                field.config.options = ths.userlisting;
                            }
                            if (field.name == "attachment") {
                                field.config.maxSize = ths.CheckFileSize;
                                field.config.accept = ths.acceptArray;
                                field.config.showSelectedFiles = [];
                                field.config.onDeleteSelectedFiles = ths.onDeleteSelectedFiles;
                                field.config.multiple = true;
                            }
                            field.config.onChange = ths.onChangeEventForFields;
                        });
                    });
                    ths.isLoading = false;
                }
            })
        },
        previewFiles(event) {
            
            const file = event.target.files && event.target.files[0];
            this.selectedFile = file || null;
            this.getFileName = file ? file.name : '';
            this.Size= file ? file.size : null;
            this.contentType = {
                "ContentType": file ? file.type : null,
                "Size": file ? file.size : null,
                "Extension": file ? file.name.substring(file.name.lastIndexOf('.')) : null
            }
        },
        onChangeEventForFields: function (x, y, z) {
            let ths = this;
            var vm = this;
            if (y.name == "attachment") {
                ths.previewFiles(x);
            }
            if (y.name == "project_id") {
                ths.FormSchema.forEach((group) => {
                    group.Data.forEach(async (field) => {
                        if (field.name == "task_id") {
                            let id = y.value;
                            await vm.GetTaskDDL(field, id);
                        }
                    })
                })
            }
            if (y.name == "cost_type_id") {
                ths.FormSchema.forEach((group) => {
                    group.Data.forEach(async (field) => {
                        if (y.value == '1') {
                            if (field.name == "task_id" || field.name == "project_id") {
                                field.visibility = true;
                            }
                        } else {
                            if (field.name == "task_id" || field.name == "project_id") {
                                field.visibility = false;
                            }
                        }

                    })
                })
            }

            if (y.name === "expense_category_id") {
                let selectedCategoryAmount = 0;
                let selectedCategorytotal = 0;
                y.config.OptionsForBind.forEach(element => {
                    if (element.first_value) {
                        const data = JSON.parse(element.first_value);
                        data.forEach(item => {
                            if (item.category_id === parseInt(y.value)) {
                                selectedCategoryAmount = item.estimated_amount;
                                if (item.category_amount_limit && item.category_amount_limit.length > 0) {
                                    const limit = item.category_amount_limit.find(limit => limit.category_id === item.category_id);
                                    if (limit) {
                                        selectedCategorytotal = limit.estimated_amount;
                                    }
                                }
                            }
                        });
                    }
                });
                ths.selectedCategryAmount = parseFloat(selectedCategoryAmount);
                ths.selectedCategoryLimitAmount = parseFloat(selectedCategorytotal);
            }
        },
        onDeleteSelectedFiles: function () {
            var vm = this;
            vm.FormSchema.forEach((group) => {
                group.Data.forEach(async (field) => {
                    if (field.name == "attachment") {
                        vm.$delete(field.config, 'showSelectedFiles');
                    }
                })
            })
        },
        GetExpenseFileList: async function (val) {
            var vm = this;
            const params = `ExpenseId=${val}`;
            await ExpenseDataService.GetExpenseFileList(params).then(function (response) {
                if (response.data != '') {
                    vm.attachmentArray = response.data.DATA;
                    vm.FormSchema.forEach((group) => {
                        group.Data.forEach(async (field) => {
                            if (field.name == "attachment") {
                                vm.attachmentArray.forEach((item, index) => {
                                    var Obj = {
                                        attachmentId: `${index}`,
                                        attachmentName: item.EXPENSE_FILE_NAME,
                                        attachmentPath: item.EXPENSE_FILE_PATH
                                    };
                                    field.config.showSelectedFiles.push(Obj);
                                    vm.$refs.AddExpense.UpdateKeyValue();
                                })
                            }
                        })
                    })
                }
            });
        },
        BindTaskDDL: function (val) {
            var vm = this;
            var params = `projectId=${val}`;
            ExpenseDataService.GetTaskListingddl(params).then(function (response) {
                vm.TaskDataddl = response.data;
                vm.FormSchema.forEach((group) => {
                    group.Data.forEach(async (field) => {
                        if (field.name == "task_id") {
                            vm.TaskDataddl.forEach((item) => {
                                var obj = {
                                    value: item.task_id,
                                    name: `${item.task_name.length > 83 ? item.task_name.substring(0, 83) + '...' : item.task_name}`

                                };
                                field.config.options.push(obj);
                                vm.$refs.AddExpense.UpdateKeyValue();
                            })
                        }
                    })
                })
            })
        },
        GetTaskDDL: async function (field, val) {
            var vm = this;
            var params = `projectId=${val}`;
            await ExpenseDataService.GetTaskListingddl(params).then(function (response) {
                vm.TaskDataddl = response.data;
                vm.TaskDataddl.forEach((item) => {
                    var obj = {
                        value: item.task_id,
                        name: item.task_name,
                    };
                    field.config.options.push(obj);
                    vm.$refs.AddExpense.UpdateKeyValue();
                })
            });
        },
        openaddTagpopup: function () {
            this.ShowTagModel = true;
        },
        openaddTrippopup: function () {
            this.ShowTripModel = true;
        },
        CloseExpenseTrip: function () {
            this.ShowTripModel = false;
        },
        CloseExpenseTag: function () {
            this.ShowTagModel = false;
        },
        CloseAddExpense: function () {
            this.$emit('CallBackFunction');
        },
        async uploadToDocStorage(file) {
            const vm = this;
            const formData = new FormData();
            formData.append("fileId", vm.FileId || 0);
            formData.append("folderId", 0);
            formData.append("moduleName", "ProjectFiles");
            formData.append("subModuleName", "");
            formData.append("isGlobal", 0);
            formData.append("file", file);
            formData.append("contentType", file.type);
            const response = await ExpenseDataService.UploadStreamNew(formData);
            const newdata = response && response.data ? response.data : null;
            if (!newdata) {
                throw new Error("Empty response from DocStorage upload");
            }
            if (newdata.UploadStatus !== 1) {
                throw new Error(newdata.ErrorMsg || "DocStorage upload failed");
            }
            return newdata;
        },
        async OnSubmit() {
            
            var ths = this;
            var ProjectId = "";
            var CategoryId = "";
            var ExpAmount = "";
            var ExpDate = "";
            var ExpenseId = "";
            var CurrencyId = "";
           
            var CustomFieldArray = ths.$refs.AddExpense.ConvertDynamicFormObjToCustomFieldObj(ths.FormSchema);
            
            for (const x of CustomFieldArray) {
                if (x.field_name == "task_id") {
                    x.field_value = `${x.field_value}`;
                }
                if (x.field_name == "is_bulk_upload") {
                    x.field_value = 0;
                }
                if (x.field_name == "expense_date") {
                    x.field_value = ths.$options.filters.formatDate(x.field_value);
                }
                if (x.field_name == 'project_id') {
                    ProjectId = x.field_value;
                }
                if (x.field_name == 'expense_amount') {
                    ExpAmount = parseFloat(x.field_value);
                }
                if (x.field_name == 'expense_date') {
                    ExpDate = x.field_value;
                }
                if (x.field_name == 'currency_id') {
                    CurrencyId = x.field_value;
                }
                if (x.field_name == 'expense_id') {
                    ExpenseId = x.field_value;
                }
                if (x.field_name == 'attachment') {
                    
                    if (ths.selectedFile) {
                        
                        const uploadedInfo = await ths.uploadToDocStorage(ths.selectedFile);
                        
                        if (JSON.parse(uploadedInfo.FileID)[0].Status == 'Success') {                            
                            var fileUrl = uploadedInfo.FilePath;
                            var FileName = uploadedInfo.FileName;
                            var FileThumb = uploadedInfo.FileThumbPath;
                            var DocFileId = JSON.parse(uploadedInfo.FileID)[0].Value;
                            var VarObject = {
                                FileTitle: FileName,
                                FileName: FileName,
                                Description: null,
                                FilePath: fileUrl,
                                ProjectId: ths.ProjectId,
                                TaskId: null,
                                UserIds: null,
                                FileId: 0,
                                Size:ths.Size,
                                DocFileId: Number(DocFileId),
                                ContentType: ths.contentType,
                                FileThumb: FileThumb
                            };  
                            x.field_value = JSON.stringify(VarObject);                        
                        }
                    }
                }
            }
            // Budget validations
            if (parseFloat(ths.selectedCategryAmount + ExpAmount) > ths.selectedCategoryLimitAmount && ths.selectedCategoryLimitAmount != 0) {
                ths.ShowAlert(ths.$t('The entered amount exceeds the allocated category budget.', [ths.$t('Budget')]), "failure", true, ths.$t("Alert"));
                ths.isLoading = false;
                return;
            }
            if (parseFloat(ExpAmount) > parseFloat(this.projectBudget) || parseFloat(ExpAmount) > parseFloat(this.pandingBudget)) {
                ths.ShowAlert(ths.$t('Amountcannotexceedthetotalbudget', [ths.$t('Budget')]), "failure", true, ths.$t("Alert"));
                ths.isLoading = false;
                return;
            }
            ths.isLoading = true;
            var postJSONN = {
                CurrencyId,
                ExpenseId,
                ProjectId,
                CategoryId,
                ExpAmount,
                ExpDate,
                moduleCode: "Expenses",
                subModuleCode: "EM_EXPENSE",
            };
            var postJSON = {
                data: CustomFieldArray,
                moduleCode: "Expenses",
                subModuleCode: "EM_EXPENSE",
            };
            try {
                
                const response = await ExpenseDataService.CheckAmountDateRange(JSON.stringify(postJSONN));

                if (response.data.error == 'faliure') {
                    ths.ShowAlert(ths.$t(response.data.msg), "failure", true, ths.$t("Alert"));
                    ths.isLoading = false;
                    return;
                }
debugger
                const saveResponse = await ExpenseDataService.SaveDynamicForm(JSON.stringify(postJSON));
                
                if (saveResponse?.data?.[0]?.Status == "Success") {

                    const msgKey = ths.ExpenseId > 0 ? 'UpdatedSuccess' : 'AddedSuccess';

                    ths.ShowAlert(ths.$t(msgKey, [ths.$t('Expense')]), "success", true, ths.$t("Alert"));
                    ths.$emit('getExpenseListingForPieChart');
                    ths.$emit('getBudgetListing');
                    ths.CloseAddExpense();
                }

            } catch (error) {
                console.error(error);
                ths.ShowAlert("Something went wrong", "failure", true, "Error");
            }

            ths.isLoading = false;
        }
    }
}
</script>