
<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 v-if="IsOldVersionOrDeleteFiles == 'OldVersion'" class="modal-title">{{ $t('OldVersion') }}</h4>
                        <h4 v-else class="modal-title">{{ $t('DeleteFile') }}</h4>
                        <button type="button" class="close" v-on:click="Close">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>
                    <div class="modal-body">
                        <div class="listing table-responsive table-fix-header">
                            <table id="FileversionListing" class="table table-bordered dt-responsive nowrap mt-0">
                                <thead class="thead-bg">
                                    <tr>
                                        <th id="th-FILENAME_24" class="ui-resizable"
                                            style="width: 108px; min-width: 108px; max-width: 108px;"><span
                                                href="javascript:;" style="min-width: 90px;">{{ $t("FileName") }}</span>
                                            <div id="th-FILENAME_24-sizer" class="sizer"></div>
                                            <div class="ui-resizable-handle ui-resizable-e" style="z-index: 90;"></div>
                                        </th>
                                        <th id="th-VERSION" class="ui-resizable"
                                            style="width: 85px; min-width: 85px; max-width: 85px;"><span href="javascript:;"
                                                style="min-width: 67px;">{{ $t("Version") }}</span>
                                            <div id="th-VERSION-sizer" class="sizer"></div>
                                            <div class="ui-resizable-handle ui-resizable-e" style="z-index: 90;"></div>
                                        </th>
                                        <th id="th-UPLOADEDBY" class="ui-resizable"
                                            style="width: 132px; min-width: 132px; max-width: 132px;"><span
                                                href="javascript:;" style="min-width: 114px;">{{ $t("UploadedBy") }}</span>
                                            <div id="th-UPLOADEDBY-sizer" class="sizer"></div>
                                            <div class="ui-resizable-handle ui-resizable-e" style="z-index: 90;"></div>
                                        </th>
                                        <th style="width: 85px; min-width: 85px; max-width: 85px;" id="th-ACTIONS_25"
                                            class="ui-resizable"><span href="javascript:;"
                                                style="min-width: 67px;">{{ $t("Actions") }}</span>
                                            <div id="th-ACTIONS_25-sizer" class="sizer"></div>
                                            <div class="ui-resizable-handle ui-resizable-e" style="z-index: 90;"></div>
                                        </th>
                                    </tr>
                                </thead>
                                <tbody>
                                    <tr v-for="item in OldVersionData" :key="item.file_version_id">
                                        <!-- <td><img src="/Content/images/inner/jpg-icon.png" class="mx-2 float-left"> -->
                                            <td><i class="fa fa-file-text mx-2 float-left"></i>
                                            {{ item.file_name }}
                                        </td>
                                        <td>{{ item.file_version }}</td>
                                        <td>{{ item.Name }} -- {{ $d(new Date(item.created_on)) }}</td>

                                        <td v-if="IsOldVersionOrDeleteFiles == 'OldVersion'"
                                            class="text-center single-action" style="width: 10%;">
                                            <a href="javascript:;" title="" class="actions-onclick"
                                                @click="DownloadFiles(item.file_version_id, item.file_version, item.file_name)"
                                                data-toggle-tooltip="tooltip" data-original-title="Download">
                                                <i class="fa fa-download action-icon text-info"></i></a>
                                        </td>
                                        <td v-else class="text-center single-action" style="width: 10%;">
                                            <a href="javascript:;" title="" class="actions-onclick"
                                                @click="DeleteOldFiles(item.file_id, item.file_version_id)"
                                                data-toggle-tooltip="tooltip" data-original-title="Delete">
                                                <i class="fa fa-trash action-icon text-info"></i></a>
                                        </td>
                                    </tr>

                                    <tr v-if="IsNoRecordShow">
                                        <td colspan="4">
                                            <div
                                                class="text-center text-danger d-flex align-items-center justify-content-center norecs">{{$t("NoRecordfound")}}</div>
                                        </td>
                                    </tr>

                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
<script>

import DataService from '../../services/DataService';

export default
    {
        props: {
            ProjectId: {
                type: Number,
                required: true,
            },
            FileId: {
                type: Number,
                required: true,
            },
            IsOldVersionOrDeleteFiles: {
                type: String,
                required: true,
            }
        },
        data() {
            return {

                userId: null,
                companyId: null,
                UserType: null,
                OldVersionData: [],
                IsNoRecordShow: false,
                isLoading:false

            }
        },
        created: function () {

            var ths = this;
            ths.userId = ths.GetUserInfo.ID;
            ths.companyId = ths.GetUserInfo.CompanyId;
            ths.UserType = ths.GetUserInfo.UserType;
            ths.GetFilesOldVersionListing();


        },
        methods: {

            GetFilesOldVersionListing: function () {               
                var vm = this;
                var url = `FileId=${vm.FileId}`;
                DataService.GetFilesOldVersionDetails(url).then((response) => {                    
                   if (response && response.data && response.data.Data && response.data.Data.length > 0) {
                        vm.OldVersionData = response.data.Data;
                        vm.IsNoRecordShow = false;
                    }
                    else{
                        vm.OldVersionData = [];
                        vm.IsNoRecordShow = true;
                    }
                });
            },
            Close: function () {
                var vm = this;
                vm.$parent.IsOldVersionShow = false;
            },
            DownloadFiles:async function (file_version_id, file_version, file_name) {                
                var vm = this;
                vm.isLoading = true;
                await DataService.CheckPrivilege('controller=ProjectFiles&action=downloadfile').then(async response => {
                    vm.isLoading = false;
                    if (response.data) {
                        var params = `fileId=${file_version_id}&IsVersion=${Math.ceil(file_version)}`;
                        DataService.DownloadSingleFile(params).then((response) => {                    
                            if (response.data != null) {
                                var fileURL = window.URL.createObjectURL(new Blob([response.data]));
                                var fileLink = document.createElement('a');
                                fileLink.href = fileURL;
                                fileLink.setAttribute('download', file_name);
                                document.body.appendChild(fileLink);
                                fileLink.click();
                                vm.isLoading = false;
                            }
                            else {
                                vm.isLoading = false;
                                vm.ShowAlert(vm.$t("FileNotDownload"), "warning", true, vm.$t("Alert"));
                            }
                        })
                    }
                    else {                        
                        vm.ShowAlert(vm.$t('NotAuthorizedSection'), 'failure', true, 'Alert');
                    }
                })           

            },
            DeleteOldFiles: function (file_id, file_version_id) {
                var vm = this;
                vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Active/Inactive")), function () {
                    var fileVersionIds = Array.isArray(file_version_id) ? file_version_id.join(',') : file_version_id;
                    var url = `FileId=${file_id}&FileVersionId=${fileVersionIds}`;
                    DataService.DeleteOldFiles(url).then((response) => {
                        if (response.data.length > 0) {
                            vm.ShowAlert(vm.$t('FileDeleted'), "success", true, vm.$t("Alert"));
                            vm.Close();
                            vm.$parent.GetFilesListing();
                        }
                        else {
                            vm.ShowAlert(vm.$t('Error'), "failure", true, vm.$t("Alert"));
                        }
                    });
                });


            }


        }
    }
</script>

