<template>
  <div>
    <loader :is-visible="isLoading"></loader>
    <transition name="modal">
      <div class="my-popups">
        <div class="modal d-block" id="myModal">
          <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
              <div class="modal-header">
                <h4 class="modal-title">
                  {{ $t(`Add`) }} {{ $t("Activity") }}
                </h4>
                <button type="button" class="close" @click="Close">
                  <i class="fa fa-times" aria-hidden="true"></i>
                </button>
              </div>
              <div class="modal-body">
                <dynamic-form
                  lang="en"
                  :key="formKey"
                  :buttons="buttons"
                  :schema="FormSchema"
                  v-on:OnSubmit="OnSubmit"
                  ref="AddActivityChecklistForm"
                >
                </dynamic-form>
              </div>
            </div>
          </div>
        </div>
      </div>
    </transition>
  </div>
</template>


<script>
import DataService from "@/services/DataService";
export default {
  name: "AddActivityandChecklist",
  data() {
    return {
      isLoading: false,
      formKey: 0,
      FormSchema: [
        {
          layoutType: "double",
          Data: [
            {
              astype: "TextField",
              label: this.$t("Activity Title"),
              name: "Activity Title:",
              value: "",
              placeholder: this.$t("Activity Title:"),
              validationRules: { required: true, max: 100 },
            },
            {
              astype: "CheckBoxField",
              label: this.$t("Recurring"),
              name: "Recurring",
              value: "",
              // label: this.$t("For All Days:"),
              placeholder: this.$t("For All Days:"),
              config: {
                options: [
                  {
                    name: "For All Days:",
                    value: "1",
                  },
                ],
                showAddIcon: false,
                onChange: this.GetCheckBoxValue,
              },
            },
            {
              astype: "SelectField",
              label: this.$t("Location"),
              name: "Location",
              value: "",
              config: {
                options: [],
                onChange: this.locationChange,
              },
              placeholder: this.$t("Select Location"),

              validationRules: { required: true, max: 100 },
            },
            {
              astype: "SelectField",
              label: this.$t("Venue"),
              name: "Venue",
              value: "",
              config: {
                options: [],
              },
              placeholder: this.$t("Select Venue"),
              validationRules: { required: false, max: 100 },
            },
            {
              astype: "DateField",
              label: this.$t("Activity Date"),
              disabled: false,
              name: "Activity Date",
              value: "",
              placeholder: this.$t("Activity Date"),
              validationRules: {
                required: true,
              },
              config: {
                mode: "date",
                format: "M/D/YYYY",
              },
            },
            {
              astype: "NumericField",
              label: this.$t("Estimated Time (Hours)"),
              name: "Estimated Time (Hours)",
              value: "",
              placeholder: this.$t("Estimated Time (Hours)"),
              validationRules: { required: true, max: 100 },
            },
          ],
        },
        {
          layoutType: "single",
          Data: [
            {
              astype: "TextAreaField",
              label: this.$t("Description"),
              name: "Description",
              value: "",
              validationRules: { required: false },
              config: {
                rows: 2,
              },
            },
          ],
        },
      ],
      buttons: [
        {
          type: "submit",
          class: "btn btn-success",
          text: "<i class='fa fa-save pr-2'></i>Save",
          isVisible: true,
        },
        {
          type: "button",
          class: "btn btn-danger",
          text: "<i class='fa fa-close pr-2'></i>Cancel",
          isVisible: true,
          onClick: this.Close,
        },
      ],
    };
  },

  methods: {
    Close() {
      this.$emit("close");
    },

    async locationChange(x, y, z) {
      await this.GetLocationOptions("VENUEBYLOCATION", y.value);
    },

    async GetLocationOptions(type = "LOCATION", refId = "") {
      this.isLoading = true;
      try {
        const url = `id=&companyId=${this.GetUserInfo.CompanyId}&userId=${this.GetUserInfo.ID}&type=${type}&refId=${refId}`;
        // `id=&companyId=110935&refId=11780&userId=2133&type=VENUEBYLOCATION`

        const response = await DataService.GetDDLData(url);

        if (response.status === 200) {
          const data = response?.data?.DATA;

          if (data && data.length > 0) {
            const options = data.map((el) => ({
              name: el.name,
              value: el.value,
            }));

            if (type === "LOCATION") {
              this.FormSchema[0].Data.forEach((field, index) => {
                if (field.label.toLowerCase() === "location") {
                  this.FormSchema[0].Data[index].config.options = options;
                }
              });
            }

            if (type === "VENUEBYLOCATION") {
              this.FormSchema[0].Data.forEach((field, index) => {
                if (field.label.toLowerCase() === "venue") {
                  this.FormSchema[0].Data[index].config.options = options;
                }
              });
            }
          } else {
          
            if (type === "VENUEBYLOCATION") {
              this.FormSchema[0].Data.forEach((field, index) => {
                if (field.label.toLowerCase() === "venue") {
                  this.FormSchema[0].Data[index].config.options = [];
                  this.FormSchema[0].Data[index].value = "";
                }
              });
            }
          }
        }
      } catch (error) {
        console.error("Error fetching project priority:", error);
      } finally {
        this.isLoading = false;
        this.formKey++;
      }
    },

    async OnSubmit() {
      const formfields = Object.fromEntries(
        this.FormSchema.flatMap((group) =>
          group.Data.map((field) => [field.name, field.value])
        )
      );

      let body = {
        SCHEDULER_ID: 0,
        MULTIDAY_ACTIVITIES_ID: 0,
        EVENT_ID: 0,
        ACTIVITY_TITLE: formfields["Activity Title"],
        DESCRIPTION: formfields["Description"],
        LOCATIONID: formfields["Location"],
        VENUEID: formfields["Venue"],
        START_DATETIME: formfields["Activity Date"],
        ESTIMATED_HOURS: formfields["Estimated Time (Hours)"],
        FOR_ALL_DAYS: formfields["Recurring"] ? true : false,
        COMPANY_ID: this.GetUserInfo.CompanyId,
        USER_ID: this.GetUserInfo.ID,
        ACTION_TYPE: "ADD",
      };

      try {
        let response = await DataService.SaveActivityandChecklist(
          JSON.stringify(body)
        );
        if (response?.data?.status.toLowerCase() == "failure") {
          this.ShowAlert(
            "Something went wrong",
            "error",
            true,
            this.$t("Alert")
          );
          return null;
        }

        if (response?.data?.status.toLowerCase() == "success") {
          this.$emit("saved");
          this.$emit("close");
        }
      } catch (error) {}
     
    },
  },
  created() {
    this.GetLocationOptions();
  },
};
</script>